import Foundation

private typealias E = EvidenceSeed

/// Alternate tellings, batch X: the same cases, played out another way.
extension StoryVariants {
    static let variantsX: [CaseTemplate] = [golfCartJoyrideV1, deputyShoveV1, packageThiefV1, domesticChokeV1, libraryBanV1, softballFieldFightV1, bottleWindowV1, airsoftCarV1, gasDriveOffV1, leashFightV1, bicycleRackV1, parkingSpaceV1, truckBedToolsV1, bouncerFlashlightV1, aisleSevenV1, securityGuardShotV1, marketplaceTrailerV1, farmGateShotsV1, tobaccoBarnFireV1, softballBatV1, crabPotTheftV1, sneakerMeetupV1, lockoutBreakInV1, barStoolV1, utilityImpostorV1, phoneOnTheFloorV1, receiptCheckV1, brakeLinesV1, zeroTurnMowerV1, afterThePartyV1, returnDeskV1, protectiveOrderV1, rentalFireV1, fishingCabinV1, duplexBurglaryV1, parkingLotShootingV1, kitchenStrangulationV1]

    static let golfCartJoyrideV1 = SmallCases.make(
        key: "story.golfCartJoyride",
        category: .property,
        headlines: ["Stolen Golf Cart Turns Up at the Drive-Through Window", "Lakeside Cart Vanishes From Dock Lot, Resurfaces on Burger Run"],
        law: "misdLarceny",
        threshold: 5,
        spec: "Took and carried away a golf cart valued at $3,400 belonging to {V}, on {DATE}.",
        ages: 18...24,
        victim: true,
        summary: "{V}'s golf cart was parked by the boat dock at a lake cottage on the evening of {DATE}. By 1 a.m. it was gone. A restaurant drive-through camera a mile and a half away showed {D} ordering from the seat of a cart that matched. The order was charged to {D.his} card. {DL} says a friend from the lake handed over the cart with the words that it was {D.his} uncle's, and {D.he} thought it was a loan.",
        state: [E(.video, 3, "Drive-Through Camera", "A cart with a cracked windshield and a green stripe pulls up at 12:40 a.m. {D} leans out and pays at the window."), E(.document, 2, "Order Receipt", "A card receipt in {D}'s name for two burgers and a shake at 12:41 a.m.")],
        defense: [E(.statement, 1, "Friend's Loan", "{DL} says a friend from the lake gave {D.him} the cart and said it was a family cart.")],
        role: "Sheriff's deputy",
        exam: [.direct("How did the golf cart theft come to your attention?", "\"The owner called at dawn to report the cart gone from the boat dock. I came out, took the report, and then checked the camera feeds in the area.\""), .direct("What did the drive-through camera show?", "\"A cart with a cracked windshield and a green stripe pulling up at 12:40 a.m. {D} leaned out and paid at the window.\""), .direct("Who was in the seat of the cart?", "\"{DL} paid with a card in {DL}'s own name. The receipt shows two burgers and a shake at 12:41 a.m.\""), .direct("How far was the drive-through from the dock?", "\"About a mile and a half. The cart had traveled along the road between the lake cottages and the restaurant.\""), .direct("What did {D} say when you spoke with {D.him}?", "\"That a friend from the lake handed over the cart and said it was a family cart. {D.He} said {D.he} thought it was a loan.\""), .direct("Did the owner know anything about a loan?", "\"No. The owner had not lent the cart to anyone and had not given permission. The cart was parked by the dock with the keys in the dash.\""), .direct("Where was the cart taken from?", "\"From a carport near {V}'s house, around midnight. {V} found it gone and the lights of the neighbor's house coming on.\""), .direct("What did the neighbor's camera show?", "\"Two young men riding the cart down the street with its lights off at 11:50 p.m. {DL} was on the back.\""), .direct("Where was the cart found?", "\"In a retention pond in the subdivision. It was pulled out, and it was a total loss.\""), .direct("What about the key?", "\"The key was never in it. Whoever took it started it some other way.\""),
                    .cross("{D} did not hide when {D.he} went through the drive-through, did {D.he}?", "\"No. {DL} ordered like anyone else, paid with a card in {DL}'s own name, and spoke to the window.\""), .cross("Did anyone see {D} take the cart from the dock?", "\"No one did. I have no witness to the moment it was taken.\""), .cross("The friend later admitted lending the cart, didn't the friend?", "\"Yes. The friend later said the cart was lent without the owner knowing. That matches what {D.he} told me.\""), .cross("The cart was a beat-up one, wasn't it?", "\"It had a cracked windshield. It was old and used. It did not look like a new, expensive vehicle.\""), .cross("{D} was cooperative with you, wasn't {D.he}?", "\"Yes. {D.He} answered questions and did not argue. {D.he} was embarrassed.\""),
                    .cross("{DL} was not driving?", "\"No. {D.He} was on the back the whole time, according to the camera.\""), .cross("The friend has not been identified?", "\"We could not identify him. {DL} knows him and has not given us a full name.\""), .cross("A text from {DL} said look what we got?", "\"It did. {D.He} sent it to another friend during the ride.\"")],
        theory: ("{D} rode a cart that was not {D.his} and paid with a card that proves it.", "A borrowed cart, a bold trip for burgers, and nothing hidden."),
        allocution: "\"A friend at the lake handed me that golf cart at the boat ramp, and I never asked who owned it. We were hungry, and the restaurant was open. I should have asked the owner for permission. I'm sorry to {V}, and I'll pay for any gas or damage.\"",
        truths: ("{DL} texted a friend that night, \"got us a ride, don't ask where.\"", "The friend later admitted lending the cart without the owner knowing and told {DL} it was a family cart."),
        defendant: [.direct("How did you get the golf cart?", "\"A friend from the lake handed it over at the boat ramp. The friend said it was a family cart and that I could use it.\""), .direct("Why did you go to the drive-through?", "\"We were hungry. It was late and the restaurant was open. I paid with my own card, in my own name.\""), .direct("Did you ask whose cart it was?", "\"No. I took my friend's word that it was a family cart, so I never asked whose it was.\""), .direct("Why was the windshield cracked?", "\"It was a beat-up cart, and the crack seemed ordinary. Many carts around the lake look like that.\""), .direct("What did you do with the cart afterward?", "\"I drove it back to the boat ramp where I got it. I left it there and went home. I did not hide it.\""), .direct("What would you say to the owner?", "\"That I am sorry. I should have asked whose cart it was, and I will pay for any damage.\""), .direct("What happened that night?", "\"My friend came by with a golf cart and told me to hop on. I did, and I thought it was his.\""), .direct("Did you know it was taken?", "\"No. He said it was his uncle's, and I did not ask. I was along for a ride.\""), .direct("What did you do while you were riding?", "\"I sat on the back and held on. I sent a text to a friend because I was excited.\""), .direct("How did it end up in the pond?", "\"My friend drove it in. I jumped off before it went in, and I ran home.\""), .direct("Why did you not tell anyone?", "\"I was scared. I did not know what to say, and I stayed home.\""),
                    .cross("You texted a friend that night, 'got us a ride, don't ask where,' didn't you?", "\"Yes. I was joking. I did not mean anything by it, and I regret the text.\""), .cross("You did not ask the owner for permission, did you?", "\"No. I did not know the owner. I now see that I should have checked.\""), .cross("You took a cart that was not yours to a restaurant, didn't you?", "\"Yes. I did. I paid with my own card, and I did not think about what it would look like.\""), .cross("The friend did not own the cart either, did the friend?", "\"No. The friend lent it without the owner knowing. I did not know that.\""), .cross("You could have called the owner or the sheriff's office, couldn't you?", "\"Yes. I could have. I did not, and I should have.\""),
                    .cross("Texts say look what we got.", "\"The texts say look what we got because I was excited.\""), .cross("You rode it in the dark.", "\"I know. I rode it in the dark, and I should not have.\""),
                    .cross("You rode on a cart you had not been given.", "\"I did. I did not ask whose it was, and I should have.\""), .cross("You jumped off before it went into the pond.", "\"I did. I did not want to be in the water, and I did not tell anyone afterward.\"")],
        openings: ("{V}'s golf cart was taken from a carport near midnight, driven around a subdivision with its lights off, and abandoned in a retention pond. A neighbor's camera shows {D} riding on the back of the cart with a friend.", "The defense will say {D} was invited by a friend who said the cart was his uncle's, never drove it, and jumped off before it went into the pond."),
        closings: ("A taken golf cart, a ride with the lights off, a text saying 'look what we got,' and a cart left in a pond, with {D} on the back.", "{D} sat on the back of a friend's cart believing it was his uncle's. The State must prove {D} knew it was taken."),
        timeline: [(0, "Evening: the cart is parked by the dock."), (0, "12:40 a.m.: the drive-through camera records the cart."), (1, "{V} reports it missing at dawn.")],
        identified: "A drive-through camera and a card receipt.",
        impact: "\"It was the cart I used to haul my mother around the lake, and it was gone by one in the morning. I was angry for a week, and my mother cried. It's an old cart, but it was part of our summers, and I'd like it to be taken seriously.\"")

    static let deputyShoveV1 = SmallCases.make(
        key: "story.deputyShove",
        category: .violent,
        headlines: ["Deputy Knocked Into Patrol Car During Backpack Search", "Bus Stop Frisk Ends With Officer Hurt and a Foot Chase"],
        law: "assaultLEO",
        threshold: 6,
        spec: "Assaulted {V}, a sworn law enforcement officer, inflicting physical injury, while {V.he} was discharging official duties, on {DATE}.",
        ages: 19...45,
        victim: true,
        summary: "A deputy stopped {D} outside a convenience store on {DATE} after a clerk reported someone loitering and arguing with customers. The deputy asked to look inside {DL}'s backpack. As the deputy reached for it, {DL} pushed the deputy with a forearm and ran. The deputy lost footing, hit the door of the cruiser, and tore a shoulder muscle. {D.He} was caught behind a laundromat. {DL} says {D.he} swung the bag away to protect a laptop and never meant to hit anyone.",
        state: [E(.video, 3, "Store Camera", "{D} drives a forearm into the deputy's chest and bolts across the lot."), E(.document, 2, "Medical Report", "A strained shoulder muscle and a bruised rib, with eight weeks of light duty.")],
        defense: [E(.statement, 1, "The Backpack", "{DL} says {D.he} swung the bag away and the deputy stepped into it.")],
        role: "Sheriff's deputy",
        exam: [.direct("Why did you stop {D} outside the convenience store on {DATE}?", "\"The clerk reported someone loitering and arguing with customers. I went to check, and found {D} standing by the door with a backpack.\""), .direct("What did you ask the defendant to do?", "\"To open the backpack so I could see what was inside. I asked politely. {D.He} said no and held the bag against {D.his} body.\""), .direct("What happened when you reached for the bag?", "\"A forearm hit my chest and I stumbled back into the door of my cruiser. I lost my footing and felt a tear in my shoulder.\""), .direct("What did the defendant do after that?", "\"Ran across the lot toward a laundromat. I called for backup and chased, and another deputy found {DL} behind the building.\""), .direct("What injuries did you suffer?", "\"A strained shoulder muscle and a bruised rib. I was on light duty for eight weeks and needed physical therapy.\""), .direct("What did the store camera show?", "\"It shows {DL} driving a forearm into my chest as I reached for the strap, and then bolting across the lot. It is clear and plainly recorded.\""), .cross("{D} was holding the bag with one hand, wasn't {D.he}?", "\"Yes. {DL} held it with one hand and pulled it away as I reached. I did not see {DL} swing it at me.\""), .cross("{D} did not threaten you with words, did {D.he}?", "\"Not with words. {D.He} said something about a laptop, and I could not make it out at the time.\""), .cross("The camera audio caught the defendant say 'Wait, that's my laptop,' didn't it?", "\"I listened to it later. It sounds like that. I did not hear it clearly in the moment.\""), .cross("You grabbed the strap before the defendant moved, didn't you?", "\"I reached for it. I may have touched the strap. Then {D.he} pulled away and hit me.\""), .cross("You did not have a warrant to search the bag, did you?", "\"No. I asked for consent. {D.He} declined. I did not have a warrant.\"")],
        defenseRole: "Store clerk",
        defenseExam: [.direct("What is your job at the store?", "\"I am the clerk. I work the counter, watch the door, and call the sheriff's office when someone is causing trouble.\""), .direct("What did you see from the counter?", "\"The deputy reached for the backpack, and {D} twisted away fast. It happened in a second, right at the door.\""), .direct("Where were you standing?", "\"Behind the counter, about fifteen feet from the door. I had a clear view through the glass.\""), .direct("How did {D} look when this happened?", "\"Scared. {DF} looked like a person who wanted to get away, not like someone who wanted to fight.\""), .direct("What did you hear?", "\"{D.He} said something about a laptop. I could not hear all of it, but I heard the word.\""), .direct("What did you do after the defendant ran?", "\"I called the sheriff's office again and said which way {DF} had run. I stayed inside until deputies came.\""), .cross("You saw an arm go out, didn't you?", "\"Yes. I saw an arm go out. I cannot say if it was a push or a twist.\""), .cross("You did not see whether the defendant meant to hit the deputy, did you?", "\"No. I cannot say what {D.he} meant. I saw it from the counter.\""), .cross("You were the one who called about the defendant, weren't you?", "\"Yes. I called because {D.he} was arguing with customers. I did not think it would lead to this.\""), .cross("{D} was loitering outside for some time, wasn't {D.he}?", "\"About twenty minutes. {D.He} argued with a couple of customers. It was not violent.\""), .cross("You do not know what was in the bag, do you?", "\"No. I never saw inside. I only know what {D.he} said.\"")],
        theory: ("{D} drove an arm into a deputy and fled.", "A twist away from a grab, and a scared run."),
        allocution: "\"I jerked my bag away and my arm hit {V}, and I panicked and ran. My laptop was inside and I didn't trust anyone to go through it. I'm sorry the deputy got hurt. I was scared, and I should have stood still and let it happen.\"",
        truths: ("{DL} was carrying a bag of pills in the backpack and meant to keep it closed.", "The camera audio caught {DL} saying, \"Wait, that's my laptop,\" before the deputy grabbed the strap."),
        defendant: [.direct("Did you hit the deputy?", "\"I jerked the bag away, and my arm hit {V}. I did not mean to hit anyone. It was a reflex, and I am sorry.\""), .direct("Why did you run?", "\"I panicked. I did not know what to do, and I was scared. I ran without thinking, and I know that was wrong.\""), .direct("Why did you not open the bag?", "\"It had my laptop, and I did not trust anyone to go through it. I said 'Wait, that's my laptop,' when the deputy grabbed the strap.\""), .direct("What was in the backpack?", "\"My laptop, some papers, and a bag of pills. I did not want it opened because of the pills.\""), .direct("Where did you run?", "\"To the laundromat. I hid behind the building and did not try to hurt anyone. I was caught within a few minutes.\""), .direct("What would you say to the deputy?", "\"That I am sorry. I did not mean to hurt you, and I will do what I can to make it right.\""), .cross("You were carrying a bag of pills in the backpack, weren't you?", "\"Yes. That is why I did not want it opened. I should have told the deputy.\""), .cross("You drove your forearm into the deputy's chest, didn't you?", "\"My arm hit the deputy's chest. I was twisting the bag away, and I know how it looks.\""), .cross("You ran a long way, didn't you?", "\"I ran across the lot to the laundromat. I was not thinking.\""), .cross("You did not stop when the deputy told you to, did you?", "\"No. I kept running. I was afraid, and it was a bad decision.\""), .cross("You could have opened the bag, couldn't you?", "\"Yes. I could have. I did not, and I made it worse.\"")],
        openings: ("A deputy stopped {D} outside a convenience store and reached for a backpack. {DL} drove a forearm into the deputy's chest and ran, and the deputy tore a shoulder muscle.", "{D} twisted a bag away to protect a laptop and never meant to hit anyone. It was a scared reaction, not an assault."),
        closings: ("A deputy got hurt and {D} fled. The camera shows a forearm into a deputy's chest and a bolt across the lot.", "{D} twisted away from a grab and ran in fear. The audio caught {DL} saying 'Wait, that's my laptop,' before the strap was grabbed."),
        timeline: [(0, "Afternoon: the clerk calls about a man loitering."), (0, "The deputy reaches for the backpack; the arm and the fall."), (0, "{DL} is caught behind a laundromat.")],
        identified: "The store camera and a foot chase.",
        aggravating: ["The victim was a law enforcement officer performing official duties"],
        mitigating: ["The defendant has accepted responsibility"],
        impact: "\"I took eight weeks of light duty after that stop outside the convenience store, and my shoulder still aches in the cold. I was only asking to look inside a backpack. I've worked patrol for years, and I lost overtime and time with my squad. It changed how I approach people on a quiet night.\"",
        genders: ["D": .male])

    static let packageThiefV1 = SmallCases.make(
        key: "story.packageThief",
        category: .property,
        headlines: ["Apartment Mailroom Camera Catches Man Pocketing Parcel", "Resident Says Her Coat Order Vanished From Lobby Shelf"],
        law: "misdLarceny",
        threshold: 5,
        spec: "Stole a package containing a winter coat valued at $180 belonging to {V}, on {DATE}.",
        ages: 18...48,
        victim: true,
        summary: "{V} lived in an apartment building where carriers left parcels on a shelf in the lobby. On {DATE}, a coat ordered online was marked delivered and was not on the shelf. The lobby camera showed {D} lift a box, check the label, and tuck it under a jacket. {V} later saw {DL} wearing a similar coat in the parking lot. {DL} says {D.he} lives in the building and took a box that had the same last name as a prior tenant.",
        state: [E(.video, 3, "Lobby Camera", "{D} reads a label, tucks the box under a jacket, and leaves through the side door."), E(.document, 2, "Delivery Scan", "The carrier's scan shows the coat delivered to the lobby at 1:05 p.m.")],
        defense: [E(.statement, 2, "Prior Tenant", "The building log shows a former tenant with a name close to {V}'s who still got mail.")],
        role: "Apartment property manager",
        exam: [.direct("What is your role at the apartment building?", "\"I am the property manager. I handle the lobby, the mail shelf, the maintenance requests, and the building log. I know most of the residents by name.\""), .direct("How are parcels delivered in the building?", "\"Carriers leave them on a shelf in the lobby, and residents pick them up. A carrier scans each parcel as delivered to the lobby.\""), .direct("What does the lobby video show?", "\"It shows {D} lifting a box from the shelf, reading the label, tucking it under a jacket, and leaving through the side door.\""), .direct("Where did the label point?", "\"To {V}'s unit. It had {V}'s name and apartment number, and it was addressed to a coat {V} had ordered online.\""), .direct("What did the carrier's scan show?", "\"The coat was delivered to the lobby at 1:05 p.m. on {DATE}. The shelf was checked an hour later, and the box was gone.\""), .direct("Where did {V} later see {D}?", "\"In the parking lot, wearing a coat similar to the one that was ordered. {V} told me right away, and I called the sheriff's office.\""), .direct("What does the doorbell video show?", "\"A man in a delivery-style vest walking up to {V}'s porch at 2:15 p.m., picking up a package, and walking off on foot.\""), .direct("How did you identify {DL}?", "\"{V} saw {D.him} at the grocery store and recognized the vest and the face from the video. {V} called us from the parking lot.\""), .direct("What other reports did you receive?", "\"Two neighbors on the same street reported missing parcels that same week, one on Tuesday and one on Thursday.\""), .direct("What does the delivery app show?", "\"That {DL} made fourteen deliveries on that street that week. It does not show a delivery to {V}'s address at that time.\""),
                    .cross("{D} lives in the building, doesn't {D.he}?", "\"Yes. {D.He} lives on the second floor. {D.He} is a resident, and {D.he} has picked up mail from that shelf before.\""), .cross("A former tenant with a similar name still gets mail, doesn't that tenant?", "\"Now and then. We forward it. The name is close to {V}'s, and I can see how a box could be confused.\""), .cross("{D} did not hide the box, did {D.he}?", "\"{D.He} tucked it under a jacket. It was not hidden from the camera, and {D.he} walked past the front desk.\""), .cross("Residents sometimes take boxes that are not theirs, don't they?", "\"Occasionally. It is usually a mistake, and they bring it back. {D.He} did not bring the box back.\""), .cross("You did not see the defendant open the box, did you?", "\"No. I know about it from the video and from {V}. I did not see inside.\""),
                    .cross("{DL} was working on that street?", "\"According to the app, yes. A driver could pick up a package by mistake.\""), .cross("The video shows {DL} walking away, not running?", "\"He walked casually, with the box under his arm. He did not hide it.\""), .cross("You have no video of the other two thefts?", "\"No. Only {V}'s camera. The other two neighbors do not have cameras.\""),
                    .cross("{DL} looks like a delivery driver in the video?", "\"Yes. The vest and the walk are what a delivery driver would wear. That is why I asked about the app.\"")],
        theory: ("{D} read the label and took the box anyway.", "A resident who grabbed a box with a familiar name."),
        allocution: "\"I thought that coat was for the prior tenant, because I have an arrangement to pick up their mail. I took it upstairs and put it in my closet, planning to hand it back. I should have checked the unit number. I'm sorry, {V}, and I'll replace it.\"",
        truths: ("{DL} had been seen at the dumpster with two empty boxes the same week.", "{DL} had a standing arrangement to pick up mail for the prior tenant, who still owed rent."),
        defendant: [.direct("Why did you take the box from the lobby shelf?", "\"I thought it was for the prior tenant. I have an arrangement to pick up that tenant's mail, and the name looked familiar.\""), .direct("What did you do with the box?", "\"I took it to my apartment and put it in my closet. I planned to deliver it to the prior tenant, who still owes rent.\""), .direct("Did you read the label?", "\"I skimmed it. I saw a last name that looked familiar. I did not look at the apartment number.\""), .direct("Did you open the box?", "\"Yes. I opened it to see what it was. I saw it was a coat, and that is when I knew it was not for the prior tenant.\""), .direct("Why did you not return the coat then?", "\"I was embarrassed. I tried it on, and I thought about returning it, and I put it off. I should have taken it back right away.\""), .direct("What would you say to {V}?", "\"That I am sorry. I should have brought it straight to you, and I will pay for the coat.\""), .direct("What do you do for a living?", "\"I deliver for an app, mostly food and small boxes. I work a few hours a day and I walk a lot of porches.\""), .direct("Why did you pick up that package?", "\"I thought it was the one I was assigned. The porch had a box, and the label looked like the address on my screen.\""), .direct("Why did you walk off?", "\"My car was around the corner. I picked up the box and carried it to the car, and I did not see the camera.\""), .direct("What did you do with the package?", "\"I put it in my bag. I looked inside later and saw it was not what I was supposed to deliver.\""),
                    .cross("You tried on the coat and wore it, didn't you?", "\"Yes. I wore it in the parking lot. I know that looks bad.\""), .cross("You were seen at the dumpster with two empty boxes that week, weren't you?", "\"Yes. I threw away packaging. Some of it was mine, and some was not.\""), .cross("You read the label and took the box anyway, didn't you?", "\"I skimmed it. I did not read it carefully. I should have.\""), .cross("You kept the coat for days, didn't you?", "\"Yes. I did. I did not return it until the deputy asked.\""), .cross("The prior tenant owes you or the building rent, doesn't the prior tenant?", "\"The prior tenant owes the building. It is not my debt. I only pick up mail.\""),
                    .cross("You looked inside.", "\"I did. I wanted to see what it was, and I should have taken it back.\""), .cross("Two other parcels went missing that week.", "\"I do not know about those.\""), .cross("You wore a delivery vest.", "\"I wear it every day for work. It was not a costume.\""),
                    .cross("You walked away with a package that was not yours.", "\"I did. I thought it was mine, and I should have looked at the name on the label.\"")],
        openings: ("A man in a delivery-style vest picked up a package from {V}'s porch at 2:15 p.m. and walked off on foot, and two other neighbors reported missing parcels the same week. {V} identified {D} from the video at the grocery store.", "The defense will say {D} is a delivery driver who works that street, mistook {V}'s box for an assigned package, and carried it to his car. A mistake is not a theft."),
        closings: ("A delivery vest, a porch, a box, and a man who left on foot with no delivery vehicle, plus two other missing parcels the same week.", "A delivery driver on fourteen stops that week who picked up the wrong box is a mistake. The State must prove {D} meant to take what was not {D.his}."),
        timeline: [(0, "1:05 p.m.: the coat is scanned delivered."), (0, "3:20 p.m.: the lobby camera shows the box taken.")],
        identified: "The lobby camera and {V}'s sighting.",
        impact: "\"I had to pay for a second coat, and I don't trust the lobby shelf anymore. The package was marked delivered and was gone before I got home. It's a small thing, but the lobby is supposed to be a safe place, and now I pick up my packages at the post office.\"")

    static let domesticChokeV1 = SmallCases.make(
        key: "story.domesticChoke",
        category: .violent,
        headlines: ["Neighbor's Knock Ends Argument; Woman Shows Marks on Neck", "Text to Sister Leads Deputies to Apartment After Choking Report"],
        law: "strangulation",
        threshold: 7,
        spec: "Assaulted {V} and inflicted physical injury by strangulation, on {DATE}.",
        ages: 22...50,
        victim: true,
        summary: "On {DATE}, {V} texted a sister that {V.his} partner was 'squeezing my neck' and then went silent. The sister called deputies. They found {V} in a hallway of a duplex with a hoarse voice and red marks, and a torn phone case on the floor. {D} was inside, calm, and said {V} had been drinking and swung a bag at {D.him}. {DL} says {D.he} only pinned {V}'s arms and never touched {V.his} throat.",
        state: [E(.digital, 3, "Text Messages", "{V} to {V.his} sister: '{DL} is squeezing my neck I can't breathe' at 9:31 p.m., then nothing."), E(.forensic, 3, "Nurse Exam", "A forensic nurse found petechiae in both eyes and a hoarse voice, consistent with pressure on the neck.")],
        defense: [E(.statement, 1, "Pinned Arms", "{DL} says {D.he} held {V}'s arms down and nothing else.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you find when you arrived at the duplex on {DATE}?", "\"{V} in a hallway with a hoarse voice, red marks on the neck, and shaking hands. A torn phone case lay on the floor nearby.\""), .direct("How did deputies get called?", "\"{V} texted a relative that {D} was squeezing {V.his} neck and that {V} could not breathe. Then the texts stopped. The relative called us.\""), .direct("What did {D} tell you?", "\"{DL} was calm. {DL} said {V} had been drinking and swung a bag, and that {DL} had held {V}'s arms down.\""), .direct("What did the forensic nurse find?", "\"Petechiae in both eyes and a hoarse voice. Those findings are consistent with pressure on the neck.\""), .direct("What did the text messages say?", "\"At 9:31 p.m., '{DL} is squeezing my neck I can't breathe,' and then nothing. We confirmed the time stamp with the carrier.\""), .direct("What was the defendant's demeanor when you arrived?", "\"Calm and polite. {D.He} answered the door and invited us in. {D.He} did not seem upset, and that struck me.\""), .cross("You did not see any weapon, did you?", "\"Only a torn phone case. I did not find a weapon, and I saw no bag with signs of use.\""), .cross("{D} was cooperative with you, wasn't {D.he}?", "\"Yes. {DL} let us in, answered questions, and did not resist. I would call {DL} very calm.\""), .cross("{V} had been drinking, hadn't {V}?", "\"I smelled alcohol on {V}. I do not know how much. {V} was able to answer questions.\""), .cross("You did not see anyone's hands on {V}'s throat, did you?", "\"No. I arrived after. I rely on the text, the nurse's findings, and {V}'s statement.\""), .cross("{V} had written that {V} would make the defendant leave, didn't {V}?", "\"An hour earlier, yes. The text history shows that. I do not know what it meant.\"")],
        defenseRole: "Upstairs neighbor",
        defenseExam: [.direct("How do you know {D} and {V}?", "\"I live upstairs in the duplex. I have heard them through the floor for the past year. We are friendly in the hall.\""), .direct("What did you hear that night?", "\"Raised voices from both of them. There was shouting and a thump, and then it went quiet.\""), .direct("Did you hear who was louder?", "\"Both. It was a mutual argument. I could not make out the words, only the tone.\""), .direct("Did you hear anything about choking?", "\"No. I did not hear anyone say anything like that. I did not hear gagging or coughing.\""), .direct("What kind of neighbor is the defendant?", "\"Quiet. I have never had an issue with {D}. {D.He} helps me carry groceries sometimes.\""), .direct("What did you do when you heard the sirens?", "\"I looked out and saw deputies arrive. I went down and told them what I had heard.\""), .cross("You did not see what happened, did you?", "\"No. I was upstairs. I only heard the argument through the floor.\""), .cross("You cannot say what the defendant did with {D.his} hands, can you?", "\"No. I cannot. I heard noise, not what was happening.\""), .cross("The quiet after the thump worried you, didn't it?", "\"A little. I did not call anyone. I should have checked.\""), .cross("You like the defendant, don't you?", "\"Yes. I do. I am trying to be honest.\""), .cross("You do not know how the argument started, do you?", "\"No. I only know it grew louder. I do not know who began it.\"")],
        theory: ("{D} put hands on {V}'s throat until {V} could not breathe.", "Two people arguing and one holding the other's arms."),
        allocution: "\"I never touched {V}'s throat. {V} was drunk and angry and swinging a bag at me, and I held {V}'s arms against the wall to stop it. I went too far in holding on. I'm sorry for what {V} went through, and I'll get help.\"",
        truths: ("{V}'s sister said {V} had told her about a choking incident once before.", "{V}'s text history showed {V} had written, 'I'll make {D.him} leave,' an hour before the call."),
        defendant: [.direct("Did you put your hands on {V}'s neck?", "\"No. I did not. I held {V}'s arms. I never touched {V}'s throat.\""), .direct("What started the argument?", "\"{V} was drunk and angry and started swinging a bag at me. I was trying to stop {V} from hitting me.\""), .direct("Why did you hold {V}'s arms?", "\"To stop the bag. I held {V}'s arms down against the wall. I wanted to keep us both from getting hurt.\""), .direct("How was {V} breathing when you let go?", "\"Normally, as far as I could tell. {V} was crying and yelling, but I did not hear any trouble breathing.\""), .direct("Why were you calm when the deputies came?", "\"It was over. I wanted to get through it without more yelling. I did not want to upset {V} further.\""), .direct("What would you say to {V}?", "\"That I am sorry. I did not mean to scare you, and I would never hurt you.\""), .cross("The nurse found petechiae in both of {V}'s eyes, didn't the nurse?", "\"So the nurse's report says. I cannot explain that. I did not touch {V}'s neck.\""), .cross("{V} texted that you were squeezing {V.his} neck, didn't {V}?", "\"Yes. I know what the text says. I do not understand why.\""), .cross("You were calm when the deputies came, weren't you?", "\"Yes. I was calm. I do not know how else to answer that.\""), .cross("{V}'s voice was hoarse, wasn't it?", "\"I heard that. I do not know why. {V} was yelling a lot.\""), .cross("You held {V}'s arms against the wall, didn't you?", "\"Yes. I held {V}'s arms. I did not hit {V}.\"")],
        openings: ("{V} texted a relative that {V.his} partner was squeezing {V.his} neck, then went silent. Deputies found {V} hoarse and marked, and a nurse found petechiae in both eyes.", "{D} says two people argued, {V} swung a bag, and {DL} only held {V}'s arms down. {DL} never touched {V}'s throat, and no one saw otherwise."),
        closings: ("A silent text, a hoarse voice, red marks, and petechiae in both eyes. A calm partner at the door and a story that does not explain the findings.", "No one saw a hand on a throat, and {V} had been drinking and swinging a bag. {D} held {V}'s arms to protect {D.himself}."),
        timeline: [(0, "9:20 p.m.: the argument begins."), (0, "9:31 p.m.: {V}'s text to {V.his} sister."), (0, "10:05 p.m.: deputies arrive.")],
        identified: "{V}'s text to a sister.",
        aggravating: ["The offense involved a victim in a domestic relationship"],
        mitigating: ["The defendant has accepted responsibility"],
        mood: .wantsConviction,
        impact: "\"My voice came back in a week. The rest of me did not. I sat in that hallway shaking and couldn't call anyone, so I texted my sister. I still flinch when someone raises a hand in the room. I want to feel safe in my own home again.\"",
        genders: ["D": .male, "V": .female])

    static let libraryBanV1 = SmallCases.make(
        key: "story.libraryBan",
        category: .property,
        headlines: ["Man Told to Stay Out of Community Center Gym Returns for Pickup Game", "Trespass Warning on Letterhead Ends in Weekend Arrest"],
        law: "trespass2",
        threshold: 5,
        spec: "Entered and remained on the premises of the county community center after being notified not to enter, on {DATE}.",
        ages: 22...65,
        victim: false,
        summary: "The county community center banned {D} for one year after an argument with a front-desk worker over a locker fee. The banning letter was left in a folder at the desk for pickup. On {DATE}, a staffer found {DL} playing in a weekend pickup game and called deputies. {DL} says {D.he} was never handed the letter and was never told by anyone not to come.",
        state: [E(.document, 3, "Banning Letter", "A letter dated five months earlier barring {D} for one year, with a note that it was left at the front desk."), E(.statement, 2, "Desk Worker", "The worker who wrote the letter recognized {D} at once.")],
        defense: [E(.document, 2, "Sign-In Sheet", "{D} signed in at the desk three times since the date on the letter, and no one stopped {D.him}.")],
        role: "Recreation center director",
        exam: [.direct("What is your role at the community center?", "\"I am the recreation center director. I run the schedules, supervise the staff, and handle bans and safety issues at the front desk.\""), .direct("Why was {D} banned?", "\"After an argument with a front-desk worker over a locker fee. The worker reported it, and I approved a one-year ban in writing.\""), .direct("What did the banning letter say?", "\"That {D} could not come on the property for one year. It was dated five months before the incident, and it noted that it was left at the front desk.\""), .direct("How was the letter supposed to get to the defendant?", "\"We left it in a folder at the front desk for pickup. That is our practice for people who do not have a mailing address on file.\""), .direct("What happened on {DATE}?", "\"A staffer saw {DL} playing in a weekend pickup game and called deputies. The staffer recognized {DL} from the ban list.\""), .direct("What did the desk worker say?", "\"The worker who wrote the letter recognized {DL} at once. The worker had texted a friend that {DL} was back and that the worker was calling it in.\""), .direct("How long have you managed this branch?", "\"Nine years. I supervise the staff, the front desk and the policies, including who is banned and for how long.\""), .direct("What happened with {DL} four months before?", "\"{DL} was caught sleeping in the stacks, and then argued with a librarian when she woke {D.him}. We wrote a notice banning {D.him} for six months.\""), .direct("How was the notice delivered?", "\"By mail to the last address we had on file for {D.him}. We did not have a way to hand it to {D.him}.\""), .direct("What did you see on the day of the arrest?", "\"A librarian called me and said {DL} was sitting at a table reading a newspaper. I recognized the name from the notice and called deputies.\""),
                    .cross("{D} signed in at the desk three times since the date on the letter, didn't {D.he}?", "\"Yes. The sign-in sheet shows at least three times. No one stopped {D.him}.\""), .cross("No one told the defendant in person about the ban, did they?", "\"I cannot say that anyone did. The letter was left in a folder, and I do not have a record of anyone speaking to {DL}.\""), .cross("The letter sat in the folder for five months, didn't it?", "\"Yes. It sat behind the desk. I do not know whether {D.he} ever saw it.\""), .cross("Staff greeted the defendant each time {D.he} came in, didn't they?", "\"Staff often greet regulars. I understand they said hello to {DL}. No one flagged the ban.\""), .cross("The center has no record of handing the letter to {D}, does it?", "\"No. There is no signed receipt. That was a gap in our process.\""),
                    .cross("{DL} was not disruptive that day?", "\"No. {D.He} was reading a newspaper and using a computer. Nobody complained about {D.him}.\""), .cross("The notice went to a shelter address?", "\"It went to the address we had. We learned later that {D.he} had left the shelter two days before the notice was mailed.\""), .cross("You never spoke to {DL} about the ban in person?", "\"I did not. The librarian who wrote the notice spoke to {D.him} after the incident, but the ban was in writing.\"")],
        theory: ("{D} was banned in writing and came back anyway.", "No one ever delivered the notice, and the staff kept welcoming {D.him}."),
        allocution: "\"I never got any letter, and nobody told me I was banned. I've been playing in that pickup game on Saturdays for years, and the staff always greeted me and waved me in. I'm sorry for the misunderstanding. I won't come back.\"",
        truths: ("A desk worker texted a friend, '{DL} is back, I'm calling it in,' after {DL} came in that Saturday.", "The folder with the letter was never opened by {DL} and sat behind the desk for five months."),
        defendant: [.direct("Did you receive the banning letter?", "\"No. It sat in a folder. I never saw it, and nobody told me I was not allowed to come.\""), .direct("Why were you at the center on {DATE}?", "\"I play in a pickup game most Saturdays. I have been doing it for years, and I signed in as I always do.\""), .direct("Did staff say anything about a ban when you signed in?", "\"Never. They greeted me every time and waved me in. If I had known, I would have stayed away.\""), .direct("What was the argument with the front-desk worker about?", "\"A locker fee. It was a disagreement that was over in a minute. I thought it was behind us.\""), .direct("What did you do when the deputies came?", "\"I told them I did not know about any ban. I left without a fuss and asked them to check with the desk.\""), .direct("What would you say to the center?", "\"That I would have respected the ban if I had known. I did not, and I am sorry for the confusion.\""), .direct("What do you use the library for?", "\"To read the newspaper and use the computers for job applications. I do not have a computer at home.\""), .direct("Why did you fall asleep in the stacks?", "\"I had been awake for two nights, and I was tired. I sat down with a book and nodded off.\""), .direct("What happened with the librarian?", "\"She woke me up, and I snapped at her. I was embarrassed and angry, and I said something I should not have.\""), .direct("Did you ever see the notice?", "\"No. I had left the shelter, and the mail did not reach me. I did not know I was banned.\""),
                    .cross("You argued with a worker over a fee, didn't you?", "\"Yes. I raised my voice. It was a short argument, and I did not think it was serious.\""), .cross("You signed in three times after the date of the letter, didn't you?", "\"Yes. I signed in every time. No one stopped me.\""), .cross("You never asked whether you were allowed to come back, did you?", "\"No. I assumed things were fine. I should have asked.\""), .cross("You did not open the folder, did you?", "\"I did not know there was a folder. No one told me.\""), .cross("You have used the center for years, haven't you?", "\"Yes. It is a place I know well. I would not have come back if I had known.\""),
                    .cross("You were told once not to return.", "\"I was told once not to return, but not in person.\""), .cross("You slept there before.", "\"Once. I was tired, and I fell asleep in a chair.\""), .cross("You came back four months later.", "\"I did, because I needed the computer. I did not think a single argument meant I was banned.\""),
                    .cross("You were never handed the notice.", "\"I was not. I did not know about it, and I am not sure I would have believed it.\"")],
        openings: ("The county library gave {D} a written notice not to return for six months after {D} was caught sleeping in the stacks and arguing with a librarian. The notice was mailed, and when {D} was seen reading at a table four months later, deputies were called and {D} was arrested.", "The defense will say {D} never received the notice because {D} had left the shelter two days before it was mailed, and was only reading the paper and using a computer. {D} was not disruptive."),
        closings: ("A written notice banning {D} for six months, mailed to the last known address, and four months later {D} was sitting at a table in the library.", "A man who left a shelter two days before a notice was mailed never saw it. The State must prove {D} knew he was banned when {D.he} came back."),
        timeline: [(-150, "A banning letter is left in a folder at the desk."), (0, "Saturday: {DL} is found in a pickup game.")],
        identified: "A staffer's call.")

    static let softballFieldFightV1 = SmallCases.make(
        key: "story.softballFieldFight",
        category: .violent,
        headlines: ["Church League Game Ends With Umpire on the Ground", "Scorekeeper's Notebook Backs Umpire After Dugout Punch"],
        law: "simpleAssault",
        threshold: 5,
        spec: "Assaulted {V}, an umpire, by striking {V.him} in the jaw with a fist, on {DATE}.",
        ages: 28...60,
        victim: true,
        summary: "In the last inning of a church league game on {DATE}, {D}, a team captain, argued a ruling that a runner had left early. {V}, the umpire, ejected {DL}. According to {V}, {DL} followed {V.him} to the backstop and punched {V.him} in the jaw. {DL} says {V} shoved {D.him} first and {D.he} swung back without thinking.",
        state: [E(.statement, 3, "Scorekeeper", "The scorekeeper saw a closed fist land on {V}'s jaw."), E(.document, 2, "Dental Note", "A chipped molar and a swollen jaw, treated the same evening.")],
        defense: [E(.statement, 1, "The Shove", "{DL} says {V} shoved {D.him} in the chest before the swing.")],
        role: "League scorekeeper",
        exam: [.direct("What is your job at the church league?", "\"I am the scorekeeper. I sit near the backstop, keep the book, and write down the lineup and the calls for each game.\""), .direct("What happened in the last inning on {DATE}?", "\"{D}, a team captain, argued a ruling that a runner had left early. {V}, the umpire, ejected {DL} for arguing.\""), .direct("What did you see after the ejection?", "\"{D.He} walked toward the backstop and approached {V}. I saw a closed fist land on {V}'s jaw. It was a clear punch.\""), .direct("What was the argument about before the punch?", "\"The call on a runner who left early. {DL} thought the runner was safe and kept shouting about it until {V} ejected {DL}.\""), .direct("How did {V} react after being hit?", "\"{V} staggered back, held {V}'s jaw, and called for the game to stop. {V} had a swollen jaw and a chipped molar.\""), .direct("What did you do after the punch?", "\"I called for help and checked on {V}. The league president took over. I gave a statement about what I saw.\""), .cross("You did not see {V} push first, did you?", "\"No. I did not see that. I was writing in the book at the time.\""), .cross("You were not watching the whole time, were you?", "\"No. I was looking down at my scorebook for part of it. I saw the punch, but not the moments before.\""), .cross("A bench player says {V} shoved {D} first, doesn't the player?", "\"I have heard that. I cannot say whether it is true. I did not see a shove.\""), .cross("The ejection was a heated moment, wasn't it?", "\"Yes. There was a lot of shouting. Both sides were upset, and the crowd was loud.\""), .cross("{D} was waiting by the backstop after the ejection, wasn't {D.he}?", "\"I saw {DL} near the backstop. I do not know how long {DL} was there or why.\"")],
        theory: ("{D} followed an umpire to the backstop and punched {V.him}.", "A shove and a swing in the heat of the moment."),
        allocution: "\"The call was wrong, and I was furious, but I swung back after I got shoved and hit {V} in the jaw. I lost my temper and I'm sorry. I'm a captain, and I should have set an example for my team. I'll apologize to {V} in person.\"",
        truths: ("The church parking lot camera showed {DL} waiting by the backstop after the ejection.", "A bench player said {V} shoved {DL} first and then said, 'Go ahead, hit me.'"),
        defendant: [.direct("Did you hit {V}?", "\"I swung back after I got shoved. I know I hit {V} in the jaw, and I am sorry. I did not mean to hurt anyone.\""), .direct("Why did you argue with {V}?", "\"The call was wrong. The runner stayed on the bag, and I felt the team was being cheated. I let my temper take over.\""), .direct("What did {V} do before you swung?", "\"{V} shoved me in the chest. I felt it, and I swung back without thinking. It was a reflex.\""), .direct("Where were you when you swung?", "\"By the backstop. I had been ejected, and I was talking to {V} as {V} came over. I was not planning a fight.\""), .direct("What did you do after the punch?", "\"I stepped back and asked if {V} was okay. I was shocked at what I had done. I stayed until the league officials arrived.\""), .direct("What would you say to {V}?", "\"That I am sorry. I will pay for the dental work, and I will not argue with umpires again.\""), .cross("You were ejected from the game, weren't you?", "\"Yes. I deserved it. I was shouting, and I should have walked away.\""), .cross("You waited by the backstop after the ejection, didn't you?", "\"I stood there to cool off. I know it may look like I was waiting for {V}.\""), .cross("You chipped {V}'s tooth, didn't you?", "\"Yes. I will pay for it. I feel awful.\""), .cross("{V} said 'Go ahead, hit me,' after the shove, didn't {V}?", "\"A bench player said that. I did not hear it clearly. It was a loud moment.\""), .cross("You could have walked away, couldn't you?", "\"Yes. I could have. I did not, and I regret it.\"")],
        openings: ("In the last inning of a church league game, {D}, a team captain, argued a ruling and was ejected by {V}, the umpire. A scorekeeper saw {DL} punch {V} in the jaw by the backstop.", "{V} shoved {D} first, and {DL} swung back without thinking. It was a reaction in a heated moment, and {DL} has apologized."),
        closings: ("A fist to an umpire's jaw, a chipped molar, and a captain who had just been ejected. {D} followed {V} to the backstop.", "A shove, then a swing, and a bench player who heard {V} say 'go ahead, hit me.' {D} reacted after being pushed."),
        timeline: [(0, "Evening: the early-leave ruling and the ejection."), (0, "The punch near the backstop.")],
        identified: "The scorekeeper and the league report.",
        impact: "\"I got hit in the jaw at a church league game I was only trying to umpire. I coach my kid's team, and I'll never be in a dugout without worrying. I'm eating soft food and I lost a week of work. I'd like the players to know it isn't worth it.\"",
        genders: ["V": .male])

    static let bottleWindowV1 = SmallCases.make(
        key: "story.bottleWindow",
        category: .property,
        headlines: ["Tire Shop Glass Door Shattered After Refund Dispute", "Customer Charged After Tire Iron Goes Through Front Door"],
        law: "injuryPersonalProperty",
        threshold: 5,
        spec: "Willfully and wantonly injured personal property of {V}, a glass shop door, causing damage of $1,850, on {DATE}.",
        ages: 21...52,
        victim: true,
        summary: "On {DATE}, {D} argued with the counter staff at {V}'s tire shop over a refused refund and left. Minutes later, {DL} came back to the parking lot and swung a tire iron at the glass front door, which shattered. {V} chased {DL} across the lot and wrote down the plate. The door cost $1,850 to replace. {DL} says the swing was aimed at a stack of tires and the door glass was already cracked.",
        state: [E(.video, 3, "Lot Camera", "{D} swings a tire iron at the front door and the glass drops in pieces."), E(.document, 2, "Door Invoice", "$1,850 for a tempered glass door and labor.")],
        defense: [E(.statement, 1, "Stacked Tires", "{DL} says the iron was aimed at a tire stack beside the door.")],
        role: "Tire shop owner",
        exam: [.direct("What do you do for a living?", "\"I own a tire shop. We sell tires, mount and balance them, and do alignments. I have run the shop for about fifteen years.\""), .direct("What happened at your shop on {DATE}?", "\"{D} argued with my counter staff over a refused refund and left. A few minutes later, {D.he} came back and swung a tire iron at the glass front door.\""), .direct("What did the lot camera show?", "\"It shows {DL} walking up to the door, swinging the iron, and the glass dropping in pieces. {DL} then ran toward the street.\""), .direct("What did you do after the door broke?", "\"I ran out and chased {D.him} across the lot. I wrote down the plate as {D.he} got into a car and drove away.\""), .direct("What did the door cost to replace?", "\"$1,850 for the tempered glass and labor. We were closed to walk-in customers for two days while it was replaced.\""), .direct("What was the refund dispute about?", "\"{D.He} had returned a set of tires and wanted a refund. My staff explained that the set was mounted and could not be refunded under our policy.\""), .direct("What time did it happen?", "\"About 1:50 in the morning. I had cut {DL} off and asked {D.him} to leave, and {D.he} went out the front door.\""), .direct("What did you see through the window?", "\"{DL} outside on the sidewalk, picking up a beer bottle from a table by the door, and winding up like a pitcher.\""), .direct("What happened to the window?", "\"The whole pane came down in sheets. Glass landed on two tables and the floor, and a customer had to move.\""), .direct("What did {DL} do afterward?", "\"Stood on the sidewalk and then sat on the curb until the deputies arrived. {D.He} did not run.\""),
                    .cross("There was a stack of tires near the door, wasn't there?", "\"Yes. There was a stack a few feet to the side. It was close to the door, but not in the line of the swing.\""), .cross("{D} did not run at first, did {D.he}?", "\"Not at first. {D.He} stood there for a second. I had to chase {D.him} once {D.he} started moving.\""), .cross("The glass door had a crack before this, didn't it?", "\"A glazier later said there was a long crack. I had not noticed it, and I cannot say how long it had been there.\""), .cross("You did not see the iron hit the glass, did you?", "\"The footage showed it to me afterward. I was inside at the counter when it happened.\""), .cross("The refund dispute was heated, wasn't it?", "\"Yes. {D.He} raised {D.his} voice. My staff stayed calm, but the conversation was tense.\""),
                    .cross("The window had a crack in it already, didn't it?", "\"A small one in the lower corner. It had been there for months, and the glass company said it was holding.\""), .cross("{DL} did not go back in the bar?", "\"No. {D.He} stayed outside the whole time. {D.He} did not threaten anyone.\""), .cross("You cut {DL} off because of how much {D.he} had drunk?", "\"I did. {D.He} was slurring, and I asked {D.him} to leave quietly.\"")],
        theory: ("{D} smashed a door after a refund dispute.", "A swing at a tire stack that went wrong."),
        allocution: "\"I swung that tire iron, yes. They refused to refund tires I'd returned and I felt cheated, and I went back angry. I wanted my receipt and a chance to talk again. I was furious, and I'm sorry for the glass door. I'll pay for it in full.\"",
        truths: ("{DL} told a friend by text, \"I'm going to teach that shop a lesson.\"", "A glazier later found a long crack in the door glass that was there before the swing."),
        defendant: [.direct("Did you swing a tire iron at {V}'s door?", "\"I swung it, yes. I was aiming at the tire stack beside the door, and the iron went wrong and hit the glass.\""), .direct("Why were you angry?", "\"They refused to refund a set of tires I had returned. I felt cheated, and I was out the money.\""), .direct("Why did you come back to the parking lot?", "\"I wanted my receipt and to talk again. I picked up the tire iron from my truck because I was frustrated.\""), .direct("What were you aiming at?", "\"The tires. I wanted to hit something, and the stack was a safe target. The iron slipped, and I hit the door.\""), .direct("Did you know the door was cracked?", "\"I noticed a crack before I swung. It was a long line across the glass, and I did not think it was in good shape.\""), .direct("What did you do after the glass broke?", "\"I ran. I was scared. I should have stayed and apologized, and I did not.\""), .direct("Why were you thrown out?", "\"The bartender said I had too much, and I felt it was for no reason. I had only had a few drinks.\""), .direct("What did you do after you left the bar?", "\"I stood outside, angry. I picked up a bottle from a table near the door, and I was going to throw it at a trash can.\""), .direct("What were you aiming at?", "\"The trash can on the sidewalk. I missed, and the bottle hit the window instead.\""), .direct("What did you do when the glass broke?", "\"I stood there in shock. I did not run, and I sat down on the curb and waited for the deputies.\""),
                    .cross("You texted a friend that you would teach the shop a lesson, didn't you?", "\"Yes. I was angry and venting to a friend, with no plan behind it.\""), .cross("The video shows the iron going toward the door, doesn't it?", "\"The angle is bad. I know how it looks. I did not mean to hit the door.\""), .cross("You came back after you left, didn't you?", "\"Yes. I wanted my receipt, but I also wanted to be heard. I made a poor choice.\""), .cross("You took a tire iron out of your truck, didn't you?", "\"Yes. I had it with me. I should have left it there.\""), .cross("You ran away after the door broke, didn't you?", "\"Yes. I panicked. That was wrong.\""),
                    .cross("You stood there afterward.", "\"I stood there afterward because I was in shock.\""), .cross("The video shows you aiming at the window.", "\"The video shows me aiming in that direction, but it was dark, and I was aiming at the can.\""), .cross("The window cost $1,400.", "\"I know. I told the deputy I would pay for it, and I still will.\""),
                    .cross("The video shows your arm go back and forward.", "\"It does. I threw the bottle at the can, and the can was behind the window.\"")],
        openings: ("After being cut off and asked to leave a bar at 1:50 a.m., {D} walked outside, threw a beer bottle through the front plate glass window, and stood on the sidewalk until deputies arrived. {V}, the owner, put the replacement cost at $1,400.", "The defense will say {D} threw the bottle at a trash can, missed in the dark, and that the window already had a crack. {D} stayed, shocked, and offered to pay."),
        closings: ("A bottle thrown through a plate glass window by a customer who had just been cut off, caught on the front camera, $1,400 of damage, and a night's business lost. {D} did not deny it.", "The window was cracked, the bottle was aimed at a trash can in the dark, and {D} stayed and offered to pay. The State must prove {D} meant to hit the window."),
        timeline: [(0, "Afternoon: the refund argument at the counter."), (0, "The tire iron and the door; {V} writes down the plate.")],
        identified: "The lot camera and a written plate number.",
        impact: "\"I've run that shop for twelve years, and the front door was brand new. Someone came back in a rage and smashed it with a tire iron over a refund. It cost me the glass, a day's work, and the feeling that I'm safe at my own counter.\"")

    static let airsoftCarV1 = SmallCases.make(
        key: "story.airsoftCar",
        category: .violent,
        headlines: ["Homeowner Points Black Pistol at Boys Cutting Across Yard", "Doorbell Camera Shows Man Aiming Airsoft Gun From Porch"],
        law: "assaultPointingGun",
        threshold: 5,
        spec: "Assaulted {V} by pointing a gun, an airsoft pistol that appeared to be a handgun, on {DATE}.",
        ages: 18...40,
        victim: true,
        summary: "Two teenagers on bicycles cut across {D}'s front yard on {DATE} as a shortcut. {DL} stepped onto the porch and pointed a black pistol at them, saying, \"Next time it's real.\" {V} dropped the bike and ran. A doorbell camera across the street recorded the porch. Deputies found an airsoft pistol with no orange tip under a cushion. {DL} says the boys had trampled the garden for weeks and the gun was a toy meant to scare them.",
        state: [E(.video, 3, "Doorbell Camera", "A figure on a porch raises a black pistol toward two boys on bicycles."), E(.physical, 2, "The Pistol", "An airsoft pistol with the orange tip missing, found under a couch cushion.", .search)],
        defense: [E(.statement, 1, "Garden", "{DL} says the boys had torn up {D.his} garden for weeks.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did the doorbell camera across the street show?", "\"A figure on a porch raising a black pistol toward two teenagers on bicycles who had cut across the front yard.\""), .direct("What did {D} say to the teens?", "\"'Next time it's real.' It is on the camera audio. {V} dropped the bike and ran, and the other teen followed.\""), .direct("How did {V} react?", "\"{V} was terrified. {V} told us {V} thought the gun was real and that {V} thought {V} was going to be shot.\""), .direct("What did you find in the defendant's house?", "\"An airsoft pistol under a cushion. It was black, the size of a real handgun, and it had no orange tip.\""), .direct("Why does the orange tip matter?", "\"By law and by custom it marks a toy. Without it, an airsoft pistol looks like a real firearm, especially from a distance.\""), .direct("What did the defendant tell you?", "\"That the teens had trampled the garden for weeks and the gun was a toy meant to scare them off.\""), .cross("The teens were in the defendant's yard, weren't they?", "\"Yes. They cut across the front yard on bikes. They were on {D}'s property.\""), .cross("No shot was fired, was there?", "\"No. The pistol was never fired, and it could not fire real ammunition.\""), .cross("The teens had trampled the garden before, hadn't they?", "\"A neighbor said so. The teens had been warned twice, and one had thrown a rock at the porch light.\""), .cross("{D} was visibly frustrated, wasn't {D.he}?", "\"Yes. {D.He} was tired and frustrated. I understood that, and I took it into account.\""), .cross("{D} was cooperative with you, wasn't {D.he}?", "\"Yes. {D.He} handed over the pistol and answered questions without any trouble.\"")],
        theory: ("{D} pointed what looked like a real gun at two boys.", "A toy shown to scare away trespassers."),
        allocution: "\"I told those kids to stay out of my garden because they'd been tearing it up for weeks. I raised the gun and said it to scare them. I shouldn't have used a gun for that, and I'm sorry. I'll never point one at anyone again.\"",
        truths: ("{DL} had filed down the orange tip the week before.", "A neighbor said the boys had been warned twice and had thrown a rock at the porch light."),
        defendant: [.direct("Why did you point the pistol at the teens?", "\"To scare them off the garden. They had been tearing it up for weeks, and I was tired of asking them to stop.\""), .direct("What did you say?", "\"I told them it was my yard and that they needed to stay out. I raised my voice.\""), .direct("Did you say it was real?", "\"I said 'Next time it's real.' I meant it as a threat to scare them. I should not have said it.\""), .direct("Why does the pistol have no orange tip?", "\"It broke off, and I filed down the rest. I did not think about how that would look.\""), .direct("What did you think when they ran?", "\"I felt bad. I did not mean to terrify anyone. I realized how it looked, and I was ashamed.\""), .direct("What would you say to the teens?", "\"That I am sorry. I should have called their parents or the sheriff's office instead.\""), .cross("You filed down the orange tip the week before, didn't you?", "\"Yes. I did. I know how it looks.\""), .cross("The pistol looks like a real handgun, doesn't it?", "\"Yes. It is a realistic replica. I should have kept it out of sight.\""), .cross("You raised it at two teenagers, didn't you?", "\"I did. I wanted to scare them. I should not have.\""), .cross("You told them 'Next time it's real,' didn't you?", "\"Yes. That was wrong, and I wish I could take it back.\""), .cross("You could have called their parents, couldn't you?", "\"Yes. I did not know who they were. I could have called the sheriff's office.\"")],
        openings: ("Two teenagers on bicycles cut across {D}'s front yard. {DL} stepped onto the porch, pointed a black pistol at them, and said, 'Next time it's real.' It was an airsoft pistol with no orange tip.", "{D} was a tired homeowner whose garden had been trampled for weeks. The gun was a toy meant to scare trespassers, and {D.he} meant no real harm."),
        closings: ("It looked real, the tip was filed off, and the teens believed it. {D} aimed a pistol at two teenagers and told them next time it would be real.", "A toy aimed at trespassers who had trampled the garden and thrown a rock at the porch light. No one was hurt, and the gun could not fire real rounds."),
        timeline: [(0, "Late afternoon: the boys cut across the yard."), (0, "{DL} steps onto the porch with the pistol."), (0, "The boys' parent calls deputies.")],
        identified: "A doorbell camera and the boys' description.",
        genders: ["D": .male])

    static let gasDriveOffV1 = SmallCases.make(
        key: "story.gasDriveOff",
        category: .property,
        headlines: ["Pickup Pulls Away From Pump With Nozzle Still Hanging", "Clerk's Phone Photo of Tag Leads to Drive-Off Charge"],
        law: "misdLarceny",
        threshold: 5,
        spec: "Stole $71 in motor fuel from a gas station, on {DATE}.",
        ages: 19...55,
        victim: false,
        summary: "At about 6:10 a.m. on {DATE}, a clerk watched a pickup fill at pump three, then pull out with the receipt unprinted. The clerk photographed the tag as it left. The tag came back to {D}. {DL} says {D.he} tapped a card at the pump, saw an approved screen, and had no reason to think the sale had failed.",
        state: [E(.video, 3, "Canopy Camera", "A pickup fills at pump three for $71 and leaves at 6:14 a.m. without a stop at the door."), E(.document, 2, "Tag Return", "The tag in the clerk's photo is registered to {D}.")],
        defense: [E(.document, 2, "Bank Alert", "{D}'s bank shows a pending hold for $71 at that station that dropped off two days later.")],
        role: "Gas station clerk",
        exam: [.direct("What is your job at the gas station?", "\"I am the clerk. I work the register inside, watch the pumps through the window, and report drive-offs to the sheriff's office.\""), .direct("What did you see at about 6:10 a.m. on {DATE}?", "\"A pickup filled at pump three for $71 and pulled out at 6:14 without coming inside. No receipt printed, and no payment came through.\""), .direct("What did you do when the truck left?", "\"I photographed the tag as it left the lot. I then checked the pump record and found an unpaid sale for $71.\""), .direct("What did the pump record show?", "\"An unpaid sale. The system listed $71 as dispensed with no payment recorded. Normally a card is approved before fuel flows.\""), .direct("How did you identify {D}?", "\"The tag in my photo came back to {D}. The registered owner and the vehicle matched the pickup I saw.\""), .direct("What did the canopy camera show?", "\"The pickup filling and leaving. There was no stop at the door, and no one came in to pay.\""), .direct("What time did this happen?", "\"At 11:20 p.m., on a quiet night. I was working the counter alone, and I watched the pumps on the monitor behind me.\""), .direct("How much fuel did {DL} pump?", "\"$64 worth at pump six. The pump log shows it ran for about four minutes and shut off at the preset amount.\""), .direct("What did you see when {DL} left?", "\"The car pulled out without anyone coming inside. I read the plate off the camera and wrote it down.\""), .direct("How was {DL} identified?", "\"The plate came back to {D.him}. I gave the number to the sheriff's office, and a deputy called {D.him} the next morning.\""),
                    .cross("The pump sometimes shows 'approved' before the bank answers, doesn't it?", "\"Sometimes. The reader may show a screen that says approved while the bank is still responding.\""), .cross("{D} came back after two days with a bank statement, didn't {D.he}?", "\"Yes. {D.He} came with a statement showing a pending hold for $71. I understand the hold later dropped.\""), .cross("{D} did not hurry out of the lot, did {D.he}?", "\"I did not see a rush. The truck pulled out normally. I only noted that no one came inside.\""), .cross("Many customers never wait for a receipt, do they?", "\"Yes. A lot of customers skip it. I do not read much into the lack of a receipt.\""), .cross("The pump vendor confirmed an approval screen, didn't it?", "\"I understand so. The vendor said the reader showed approved before the sale was voided.\""),
                    .cross("The card reader at pump six was down, wasn't it?", "\"Yes. My own log shows it. A sign on the pump said to pay inside.\""), .cross("{DL} came back to pay the next morning?", "\"Yes, after the deputy called. {D.He} paid in full and apologized.\""), .cross("No one told {DL} to pay inside?", "\"The sign did. A person who did not read it could have missed it, and I did not speak to {D.him}.\"")],
        theory: ("{D} pumped $71 of fuel and left without paying.", "A card tap that looked approved and dropped off."),
        allocution: "\"I tapped my card at the pump and the screen said approved, so I filled my tank and drove off. I never wait for a receipt. I should have checked it. I'm sorry to the station. I'll pay the bill in full right now.\"",
        truths: ("{DL} had two earlier drive-off reports at stations in the next county.", "The station's pump vendor confirmed the reader showed an approval screen before the sale was voided."),
        defendant: [.direct("Did you pay for the gas?", "\"I tapped my card at the pump, and it said approved. I thought it was paid, and I drove away.\""), .direct("Why did you not take a receipt?", "\"I never wait for one. I fill up and go. I did not see a reason to wait.\""), .direct("What did you see on the pump screen?", "\"An approved message. There was no error and no request for another card. I did not think anything was wrong.\""), .direct("When did you learn the sale was unpaid?", "\"Two days later, when I saw the bank hold had dropped. I went to the station to find out what happened.\""), .direct("Why did you go back to the station?", "\"I wanted to pay. I brought my bank statement and offered to pay the $71 right away.\""), .direct("What would you say to the station?", "\"That I am sorry for the confusion. I did not mean to drive off, and I will pay what I owe.\""), .direct("Why did you leave without paying?", "\"My cousin was in the hospital and I had just gotten a call. I filled the tank without thinking and drove off.\""), .direct("Did you see a sign at the pump?", "\"No. I looked for the card reader and it was dark. I did not see a sign about paying inside.\""), .direct("What did you do the next morning?", "\"A deputy called me, and I went right to the station and paid in full. I was embarrassed.\""), .direct("Did you mean to drive off without paying?", "\"No. I meant to pay inside, and I forgot because of the call. I would never do that on purpose.\""),
                    .cross("You had two earlier drive-off reports at stations in the next county, didn't you?", "\"Yes. Those were also card problems. I know how it looks.\""), .cross("The sale was unpaid when you left, wasn't it?", "\"I learned that later, from the pump record.\""), .cross("You did not go inside to check, did you?", "\"No. I trusted the screen. I should have checked.\""), .cross("You came back only after the hold dropped, didn't you?", "\"Yes. I noticed it two days later, and I came right away.\""), .cross("You filled $71 of fuel, didn't you?", "\"Yes. I did. I wanted to pay for every dollar.\""),
                    .cross("The sign was on the window too.", "\"I did not see it. I was not looking at the windows, and I am sorry.\""), .cross("Nobody called you until the next day.", "\"That is why I went myself. When no one called, I drove to the station and asked what I owed.\""), .cross("You drove off at 11:24.", "\"I did, and I was distracted. I should have gone in and told the clerk what happened.\""),
                    .cross("The log shows the reader was down that night.", "\"It was down. I wish I had gone in and paid. I did not see the sign.\"")],
        openings: ("At 11:20 p.m. {D} pumped $64 of fuel at pump six and drove off without going inside, and the camera caught the plate. The station's own log shows the pump's card reader was down that night.", "The defense will say {D} meant to pay inside, was distracted by a call about a cousin in the hospital, and went to pay the next morning as soon as a deputy called."),
        closings: ("$64 of fuel, a pump with a sign saying to pay inside, a readable plate, and a car that left without anyone coming in.", "A man who drove up under the lights with his own plate, paid in full the next day, and apologized did not mean to steal. The State must prove {D} drove off intending never to pay for the fuel."),
        timeline: [(0, "6:10 a.m.: fuel pumped at pump three."), (2, "{DL} returns with a bank statement.")],
        identified: "The clerk's photo of the tag.")

    static let leashFightV1 = SmallCases.make(
        key: "story.leashFight",
        category: .violent,
        headlines: ["Dog Park Gate Argument Turns Physical", "Volunteer Says Neighbor Shoved Dog Owner Into Fence"],
        law: "simpleAssault",
        threshold: 5,
        spec: "Assaulted {V} by shoving {V.him} against a metal fence, on {DATE}.",
        ages: 24...66,
        victim: true,
        summary: "At a county dog park on {DATE}, {V} found the double gate propped open and a dog loose in the small-dog yard. {V} accused {D} of leaving it open. Words were exchanged. According to {V}, {DL} shoved {V.him} against the fence and {V} bruised a shoulder. {DL} says {V} had grabbed {D.his} dog's collar and {D.he} pushed {V.him} off.",
        state: [E(.statement, 2, "Park Volunteer", "The volunteer saw {D} push {V} into the fence but not what led to it."), E(.document, 1, "Clinic Note", "A bruised shoulder and a scraped forearm.")],
        defense: [E(.statement, 1, "Collar", "{DL} says {V} grabbed {D.his} dog by the collar.")],
        role: "Park volunteer",
        exam: [.direct("What is your role at the dog park?", "\"I am a park volunteer. I check the gates, help visitors, and keep an eye out for problems. I was working the day of {DATE}.\""), .direct("What did you see that afternoon?", "\"{V} and {D} shouting at each other near the fence. Then {DL} shoved {V} into the fence. I was a few feet away.\""), .direct("What was the argument about?", "\"{V} said {DL} had left the double gate propped open and that a dog was loose in the small-dog yard. {DL} said it was not {DL}'s doing.\""), .direct("What happened to {V}?", "\"{V} hit the fence and held {V}'s shoulder. {V} had a bruise and a scraped forearm, and went to a clinic afterward.\""), .direct("Was the double gate open?", "\"Yes. It was propped open with a stone. I do not know who propped it open.\""), .direct("What did you do after the shove?", "\"I stepped in and separated them. I asked both to leave and reported what I saw to the park supervisor.\""), .direct("What were you doing at the park?", "\"Jogging on the path along the dog area. I saw {V} walking a small dog and {D} with a larger dog, off its leash.\""), .direct("What did you see first?", "\"{D.his} dog running at {V}'s small dog. {V} yelled, and {DL} yelled back, and then they were arguing.\""), .direct("What did you see next?", "\"{D.He} shoved {V}, hard enough that {V} fell to the ground. I did not see what came right before.\""), .direct("What injuries did {V} have?", "\"Scraped palms and a bruised hip, according to the urgent care note I saw later.\""),
                    .cross("You did not see {V} grab the dog, did you?", "\"No. I was not looking at the dog. I was looking at {V} and {DL}.\""), .cross("{D}'s dog was in the yard during the argument, wasn't it?", "\"Yes. {D.his} dog was close by. It was tense, and I could not tell what the dog was doing.\""), .cross("The park's camera shows {V} gripping the collar for several seconds, doesn't it?", "\"I have heard that. I did not witness it. I saw only the push and the shouting.\""), .cross("The gate was propped open before the defendant came, wasn't it?", "\"I cannot say. It was open when I came. I did not see anyone prop it.\""), .cross("Both of them were shouting, weren't they?", "\"Yes. It was a loud argument on both sides.\""),
                    .cross("You did not see the beginning, did you?", "\"No. I heard shouting and then I saw the shove, and I came over after {V} fell.\""), .cross("{V} had a leash in {V.his} hand?", "\"Yes. {V} was holding it, and a second walker says {V} swung it at {D}'s dog.\""), .cross("{D}'s dog was off its leash?", "\"It was loose, and it ran toward {V}'s dog. I cannot say more about what the dog did.\""),
                    .cross("You do not know who swung the leash?", "\"I did not see that. I only saw the push, and I came over after {V} fell.\"")],
        theory: ("{D} shoved a dog owner into a fence.", "A push to free a dog from a grab."),
        allocution: "\"{V} grabbed the collar hard and wouldn't let go of my dog, and I pushed. I didn't mean for {V} to fall. I didn't prop the gate open, and it was already open when I got there. I'm sorry for the shove, and I shouldn't have used my hands.\"",
        truths: ("{DL}'s dog had snapped at two other visitors that month.", "The park's camera showed {V} gripping the collar for several seconds before the push."),
        defendant: [.direct("Did you push {V}?", "\"Yes. I pushed {V} to get {V.him} off my dog. I did not mean for {V} to hit the fence.\""), .direct("Why did {V} grab your dog's collar?", "\"{V} said my dog was loose. {V} grabbed the collar hard and would not let go, and my dog was panicking.\""), .direct("Who left the gate open?", "\"Someone else. I did not prop it open. It was already open when I got there.\""), .direct("How long did {V} hold the collar?", "\"A few seconds. It felt like longer. I said to let go, and {V} did not.\""), .direct("What did you do after the push?", "\"I stepped back and apologized. I checked my dog and then tried to see if {V} was okay.\""), .direct("What would you say to {V}?", "\"That I am sorry. I did not mean to hurt you, and I should have called a volunteer first.\""), .direct("What happened with your dog?", "\"It ran toward {V}'s dog, as it does when it sees another dog. I called it, and it did not come.\""), .direct("What did {V} do?", "\"{V} swung the leash at my dog, hard, and I was afraid {V.he} would hit it. I shouted at {V.him}, and {V.he} came toward me.\""), .direct("How did you push {V}?", "\"With my hands, to get {V.him} away from my dog. I did not shove {V.him} to the ground on purpose.\""), .direct("What happened after {V} fell?", "\"I helped {V.him} up and asked if {V.he} was hurt. I stayed until the ranger came.\""),
                    .cross("Your dog had snapped at two other visitors that month, hadn't it?", "\"Yes. It was nervous around strangers. I was working on it, and I know that is a worry.\""), .cross("You shoved {V} into a fence, didn't you?", "\"I pushed {V} off my dog. The fence was behind {V}. I did not plan where {V} would land.\""), .cross("You could have called a volunteer, couldn't you?", "\"Yes. I could have. I reacted instead.\""), .cross("You and {V} were shouting at each other, weren't you?", "\"Yes. We both were. I raised my voice because I was scared for my dog.\""), .cross("{V} was bruised and scraped because of you, wasn't {V}?", "\"Yes. I am sorry. I did not intend that.\""),
                    .cross("Your dog was off its leash.", "\"I know. My dog was off its leash, and I should have had it on one.\""), .cross("{V} was hurt.", "\"I'm sorry about that. I'm sorry {V} was hurt.\""), .cross("A jogger saw you push {V} hard.", "\"It was not that hard. {V} lost footing on the gravel, and I did not mean for {V.him} to fall.\""),
                    .cross("Your dog was off its leash and ran at {V}'s dog.", "\"It was, and it ran. I called it and it did not come.\"")],
        openings: ("{D}'s unleashed dog ran at {V}'s small dog in a county park. {V} yelled, {D} yelled back, and according to {V}, {D} shoved {V} to the ground, scraping {V.his} hands and bruising {V.his} hip.", "The defense will say {V} swung a leash at {D}'s dog first, a second walker saw it, and {D} pushed {V} away to protect the dog. {D} helped {V} up and stayed."),
        closings: ("An unleashed dog, a shouting match, and a shove that put {V} on the ground, seen by a jogger and recorded in an urgent care note.", "A man protecting his dog from a swung leash is not an aggressor. The State must prove {D} pushed {V} on purpose and not to defend the dog."),
        timeline: [(0, "Morning: the gate is found open."), (0, "The grab, the shove, and the fence.")],
        identified: "A park volunteer's call.",
        impact: "\"I still check the gate before I let my dog in, and I used to take that for granted. I was shoved to the ground over an open gate and a loose dog, and my hands were scraped. I only wanted the small-dog yard to be safe for the dogs and people who use it.\"")

    static let bicycleRackV1 = SmallCases.make(
        key: "story.bicycleRack",
        category: .property,
        headlines: ["Dorm Bike Rack Raided; Marketplace Ad Leads to Arrest", "Student Spots Her Stolen Mountain Bike in Online Listing"],
        law: "misdLarceny",
        threshold: 5,
        spec: "Stole a bicycle valued at $520 belonging to {V}, on {DATE}.",
        ages: 18...36,
        victim: true,
        summary: "{V}'s mountain bike was cut from a dorm bike rack on {DATE}. Three days later {V} saw it listed on a resale site for $200, and arranged to meet the seller at a coffee shop. {D} showed up with the bike. {V} called campus police. {DL} says {D.he} bought the bike from a roommate and was selling it to cover rent.",
        state: [E(.document, 3, "Resale Listing", "A listing by {D}'s account with photos of {V}'s bike, including its stickers and a bent kickstand."), E(.statement, 2, "Meeting Report", "Campus police met {D} at the coffee shop with the bike.")],
        defense: [E(.digital, 1, "Roommate Text", "A text from a roommate, \"I'll take $150 for it, no questions.\"")],
        role: "Campus police officer",
        exam: [.direct("What is your role with campus police?", "\"I am a campus police officer. I take reports of thefts in the dorms, follow up on leads, and work with the sheriff's office.\""), .direct("How did {D} come to your attention?", "\"{V} told us {V}'s mountain bike had been cut from a dorm rack. Three days later, {V} saw it listed on a resale site and set up a meeting.\""), .direct("What did the resale listing show?", "\"Photos of {V}'s bike with {V}'s stickers and a bent kickstand. The listing was posted by {D}'s account at a price of $200.\""), .direct("What happened at the coffee shop?", "\"{V} met the seller, and {DL} showed up with the bike. {V} called us, and we arrived within a few minutes.\""), .direct("What did the defendant do when you arrived?", "\"{D.He} stayed where {D.he} was. {D.He} did not run and answered my questions. {D.he} said {D.he} bought the bike from a roommate.\""), .direct("What was on the bike?", "\"{V}'s stickers and the bent kickstand, as described in the report. The serial number also matched {V}'s purchase receipt.\""), .cross("{D} did not try to hide when you arrived, did {D.he}?", "\"No. {D.He} stood there with the bike and answered every question. {D.He} did not argue.\""), .cross("You do not have video of who cut the lock, do you?", "\"No. The rack is not covered by a camera. We have no video of the theft itself.\""), .cross("A roommate text says 'I'll take $150, no questions,' doesn't it?", "\"Yes. It is in the evidence. I understand it supports what {D.he} told us about a roommate.\""), .cross("{D} posted the listing in {D}'s own name, didn't {D.he}?", "\"Yes. It was {D.his} own account. {D.He} used a real name and a real photo of the bike.\""), .cross("You do not know who cut the lock, do you?", "\"No. I cannot say who did. I only know what was found at the coffee shop.\"")],
        theory: ("{D} sold a bike that was cut from a rack three days earlier.", "A bike bought from a roommate and sold in good faith."),
        allocution: "\"I bought that bike from my roommate for one hundred fifty dollars, and I took the story about a trade at face value. I was short on rent and listed it, and I should have asked more questions. I'll give the bike back.\"",
        truths: ("{DL}'s phone held a photo of the bike next to a lock cutter taken the night of the theft.", "The roommate was later arrested with two more stolen bikes and admitted selling {V}'s to {DL}."),
        defendant: [.direct("Where did you get the bike?", "\"From a roommate. My roommate sold it to me for $150, and I thought it was a fair price for a used mountain bike.\""), .direct("Why did you sell it?", "\"I was short on rent. I did not need two bikes, and I wanted to cover what I owed. I posted it online at $200.\""), .direct("Did you ask where it came from?", "\"My roommate said it was a trade. I took that at face value and did not ask further.\""), .direct("Did you see the stickers on the frame?", "\"Yes. I did not recognize them. Many students have stickers, and I did not connect them with anyone.\""), .direct("What did you do when the campus police arrived?", "\"I told them everything I knew. I gave the roommate's name and showed them the text. I did not run.\""), .direct("What would you say to {V}?", "\"That I am sorry. I had no idea the bike was stolen, and I am glad it is back with you.\""), .cross("You took a photo of the bike next to a lock cutter the night of the theft, didn't you?", "\"That is not what I remember. If a photo exists, I do not know how it got there.\""), .cross("You paid only $150 for a bike worth much more, didn't you?", "\"Yes. It was a bargain. I should have asked why.\""), .cross("You listed the bike three days after it was stolen, didn't you?", "\"Yes. I know how it looks. Nothing told me it was stolen.\""), .cross("The roommate was later arrested with two more stolen bikes, wasn't the roommate?", "\"I heard that. It shocked me. It does not change that I should have asked questions.\""), .cross("You did not check the serial number before you sold it, did you?", "\"No. I did not. I should have checked.\"")],
        openings: ("{V}'s mountain bike was cut from a dorm rack. Three days later, {V} saw it listed on a resale site, arranged a meeting at a coffee shop, and {D} showed up with the bike.", "{D} bought the bike from a roommate in good faith and listed it in {D.his} own name. {D.He} told campus police everything."),
        closings: ("The listing, the stickers, the bent kickstand, and {D} at the coffee shop with {V}'s bike. {DL} was selling a bike that had been cut from a rack.", "{D} sold in the open under a real name, did not run, and named the roommate. The roommate was later arrested with two more stolen bikes."),
        timeline: [(0, "Night: the bike is cut from the dorm rack."), (3, "{V} sees the listing and arranges a meeting.")],
        identified: "An online listing and a meeting at a coffee shop.",
        impact: "\"I used that bike to get to class, and I spent a month on foot. I saw it listed on a resale site for two hundred dollars and went to meet the seller myself. I don't want to be in this courtroom, but I can't afford to have another bike taken.\"")

    static let parkingSpaceV1 = SmallCases.make(
        key: "story.parkingSpace",
        category: .violent,
        headlines: ["School Pickup Line Dispute Ends With a Shove", "Parent Charged After Pushing Driver Against Car"],
        law: "simpleAssault",
        threshold: 5,
        spec: "Assaulted {V} by pushing {V.him} against the side of a car with both hands, on {DATE}.",
        ages: 28...66,
        victim: true,
        summary: "In the afternoon pickup line at an elementary school on {DATE}, {V} pulled out of line to go around and cut in front of {D}'s car. {DL} got out and walked up. According to {V}, {DL} shoved {V.him} against the car door when {V.he} stepped out. {DL} says {V} stepped out clenching a fist and {DL} put out {D.his} hands to hold {V.him} back. A crossing guard watched part of it.",
        state: [E(.statement, 2, "Crossing Guard", "The guard saw both of {D}'s hands on {V}'s chest but not what led to it."), E(.document, 1, "Clinic Note", "A bruised chest and a sore back.")],
        defense: [E(.statement, 2, "Other Parent", "Another parent says {V} stepped out cursing with a fist at {V.his} side.")],
        role: "Crossing guard",
        exam: [.direct("What is your job at the school?", "\"I am the crossing guard. I stand at the corner of the pickup line, direct cars, and help students cross. I was on duty the afternoon of {DATE}.\""), .direct("What did you see during pickup that day?", "\"{V} pulled out of the line to go around and cut in front of {D}'s car. {DL} got out and walked up to {V}'s car.\""), .direct("What did you see {D} do?", "\"{D.He} put both hands on {V}'s chest. I saw that clearly. I was about thirty feet away at the time.\""), .direct("What did you hear?", "\"Raised voices and a horn. I could not make out every word. It was a loud exchange between the two.\""), .direct("How did {V} react?", "\"{V} staggered back and then held {V}'s chest. {V} was upset and said {V} was going to call the sheriff's office.\""), .direct("What did you do?", "\"I walked over and told both to calm down and move their cars. I stayed until the line moved on and the school aide came.\""), .cross("You did not see what led to it, did you?", "\"No. I saw {DL} walk up and both hands on {V}'s chest. I did not see what {V} did before that.\""), .cross("Where were you standing when it happened?", "\"Across the walkway, about twenty feet away, looking toward the entrance.\""), .cross("{V} was cutting the line, wasn't {V}?", "\"I think so. {V} pulled out and went around. It happens at pickup, and it makes people angry.\""), .cross("Another parent says {V} stepped out cursing, doesn't the parent?", "\"I heard that. I did not hear the cursing myself, and I was not close enough.\""), .cross("{D}'s child was in the car, wasn't {D.he}?", "\"Yes. A child was in the back seat. It must have been upsetting.\"")],
        defenseRole: "Other parent in line",
        defenseExam: [.direct("What were you doing in the pickup line?", "\"I was waiting for my child. I was a few cars back and had a good view of both cars. I saw most of what happened.\""), .direct("What did you see {V} do?", "\"{V} jumped out of the car yelling and cursing. {V} had a fist at {V}'s side. I could see it from where I sat.\""), .direct("What did {D} do?", "\"{D} put out hands to stop {V}. I saw hands go out. It looked like {D.he} was holding {V} back.\""), .direct("Where was {V} before that?", "\"In a car that had cut into the line. {V} pulled out of line and went around, and that made people angry.\""), .direct("How did the defendant look?", "\"Upset, but controlled. {DF} did not swing at {V}. {DF} looked like someone trying to keep distance.\""), .direct("What did you do after?", "\"I stayed in my car and kept an eye on the children. I told the aide what I saw when the aide came.\""), .cross("You did not see the shove, did you?", "\"I saw hands go out. I cannot say it was a shove. It happened fast.\""), .cross("You could not hear what was said, could you?", "\"Not all of it. I heard raised voices, but I did not hear exact words.\""), .cross("You are a parent, and you like the defendant, don't you?", "\"I know {D.him} from school events. I am trying to be fair.\""), .cross("You saw {D} get out of the car on {D}'s own, didn't you?", "\"Yes. {D.He} got out and walked up. I do not know what {D.he} said.\""), .cross("You cannot say what {V} would have done next, can you?", "\"No. I only know {V} was angry. I do not know what {V} planned.\"")],
        theory: ("{D} pushed a driver over a place in line.", "{D} put out hands to stop an angry driver."),
        allocution: "\"I put my hands on {V}'s chest to hold {V} back, and I was angry because {V} had cut me off in front of my child. I lost my temper in front of the kids, and I'm sorry. I'll leave the pickup line when I get that angry.\"",
        truths: ("A school aide heard {DL} say, \"Get back in your car or I'll put you there.\"", "{V} told another parent afterward, \"I was ready to swing.\""),
        defendant: [.direct("Did you push {V}?", "\"I held {V} back with my hands. I put them on {V}'s chest to keep {V} away. I did not mean to shove.\""), .direct("Why did you get out of your car?", "\"{V} cut me off in front of my child. I was angry, and I wanted to talk. I should have stayed in the car.\""), .direct("What did {V} do when {V} got out?", "\"{V} stepped out clenching a fist and cursing. I put out my hands to keep {V} from coming at me.\""), .direct("What did you say?", "\"I said to get back in the car. I may have said more. I was frightened and I was loud.\""), .direct("What did your child see?", "\"The whole thing. I regret that. My child was in the back seat, and I should have thought of that first.\""), .direct("What would you say to {V}?", "\"That I am sorry. I should not have touched you, and I should have driven on.\""), .cross("A school aide heard you say 'Get back in your car or I'll put you there,' didn't the aide?", "\"I may have said something like that. I was upset. I did not mean it literally.\""), .cross("You put both hands on {V}'s chest, didn't you?", "\"Yes. I did. I was trying to hold {V} back, and I know how it looks.\""), .cross("{V} was bruised and sore afterward, wasn't {V}?", "\"I heard that. I am sorry. I did not mean to hurt {V}.\""), .cross("You got out of your car to confront {V}, didn't you?", "\"Yes. I did. I should have stayed in the car.\""), .cross("You could have driven away, couldn't you?", "\"Yes. I could have. I did not, and I regret it.\"")],
        openings: ("In an elementary school pickup line, {V} cut in front of {D}'s car. {DL} got out and put both hands on {V}'s chest, and {V} was bruised. A crossing guard saw part of it.", "{V} stepped out of the car clenching a fist, and {D} put out hands to hold {V} back. {DL} defended against an angry driver."),
        closings: ("Hands on a chest are an assault. A crossing guard saw both of {D}'s hands on {V}, and a school aide heard {DL} threaten to put {V} back in the car.", "Another parent saw {V} jump out cursing with a fist at {V}'s side. {D} put out hands to stop {V} and never meant to hurt anyone."),
        timeline: [(0, "3:10 p.m.: {V} cuts in front of {D}'s car."), (0, "The shove; the school calls deputies.")],
        identified: "A crossing guard and both parents stayed.",
        mitigating: ["The defendant acted under strong provocation", "The defendant has accepted responsibility"],
        mood: .divided,
        impact: "\"It happened in front of a school, with children watching. I'd stepped out of my car to move a cone, and I got shoved for no reason. I still feel embarrassed to this day. I'd like the kids to learn that you don't settle things with your hands.\"",
        doctrines: ["selfDefense", "burdenOfProof"],
        genders: ["D": .male, "V": .male])

    static let truckBedToolsV1 = SmallCases.make(
        key: "story.truckBedTools",
        category: .property,
        headlines: ["Work Van Window Smashed at Tire Lot; Cyclist Stopped With Tools", "Pry Bar and a Generator on a Bike Trailer Lead to Arrest"],
        law: "breakingVehicle",
        threshold: 5,
        spec: "Broke into and entered a motor vehicle belonging to {V}, with intent to commit larceny therein, on {DATE}.",
        ages: 19...42,
        victim: true,
        summary: "On {DATE} at about 5:15 a.m., a passerby heard glass break at a tire shop lot and saw a person climb out of {V}'s locked work van. A deputy found {D} ten minutes later pulling a bike trailer with a portable generator and a toolbox, and a pry bar in a backpack. {V} identified the generator and toolbox by serial number. {DL} says a stranger paid {D.him} $20 to haul the trailer.",
        state: [E(.physical, 3, "Trailer Load", "A portable generator and a toolbox with {V}'s serial number, pulled by {D} on a bike trailer.", .search), E(.statement, 2, "Passerby", "The passerby saw a person with a gray jacket leave the van and described a bike trailer.")],
        defense: [E(.statement, 1, "Hired Hand", "{DL} says a man at a bus stop paid {D.him} $20 to tow the trailer to a shop.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you find at 5:15 a.m. on {DATE}?", "\"I found {D} pulling a bike trailer with a portable generator and a toolbox, and a pry bar in a backpack. It was ten minutes after the call.\""), .direct("What was the call about?", "\"A passerby heard glass break at a tire shop lot and saw a person in a gray jacket climb out of a locked work van.\""), .direct("What was the condition of the van?", "\"A broken rear window and a punched lock. The van belonged to {V}, and the generator and toolbox had been inside.\""), .direct("How did {V} identify the property?", "\"By serial numbers on the generator and the toolbox. {V} gave us the numbers, and they matched what was on the trailer.\""), .direct("What did {D} tell you?", "\"That a stranger at a bus stop paid {DL} $20 to tow the trailer to a shop. {DL} said {D.he} did not know what was in it.\""), .direct("What was in the defendant's backpack?", "\"A pry bar. {D.He} said it was for work. I also found glass fragments in the pocket of a gray jacket.\""), .cross("The passerby saw a gray jacket, not a face, didn't they?", "\"Yes. The passerby described a gray jacket and a bike trailer. The face was not seen.\""), .cross("{D} did not run when you stopped {D.him}, did {D.he}?", "\"No. {D.He} stopped right away and answered questions. {D.He} did not try to flee.\""), .cross("Nobody saw the defendant touch the van, did they?", "\"No one did. We have no witness who saw {DL} at the van.\""), .cross("A tow truck driver says someone else in a gray jacket handed off the trailer, doesn't the driver?", "\"Yes. The tow truck driver described a different gray jacket at a bus stop. I know about that statement.\""), .cross("Many people wear gray jackets, don't they?", "\"Yes. It is a very common color. I would not rely on the jacket alone.\"")],
        theory: ("{D} was caught towing tools from a van minutes after it was broken into.", "A hired hauler and a gray jacket seen from a distance."),
        allocution: "\"A man at a bus stop paid me twenty dollars to haul that trailer, and I never knew what was in it. I was on my way to a scrap yard to drop it off. I needed money, and I'm sorry that I was part of it. I'll pay back what I can.\"",
        truths: ("{DL}'s gray jacket had glass fragments in the pocket.", "A tow truck driver said a man in a different gray jacket handed off the trailer at a bus stop."),
        defendant: [.direct("Where did you get the trailer?", "\"Someone at a bus stop paid me $20 to haul it. I did not know what was in it, and I took the job because I needed cash.\""), .direct("Why were you towing it at 5 a.m.?", "\"I was heading to a scrap yard to drop it off for the stranger. I get up early, and I thought it was an easy job.\""), .direct("Why did you have a pry bar in your backpack?", "\"It is for work. I use it every day, and I keep it in my pack. It has nothing to do with the van.\""), .direct("Did you know the tools were stolen?", "\"No. I did not look inside. The generator and toolbox were under a tarp. I did not ask.\""), .direct("What did you do when the deputy stopped you?", "\"I stopped and told the deputy the whole story. I did not run, and I let the deputy search the trailer.\""), .direct("What would you say to {V}?", "\"That I am sorry for your loss. I did not know, and I wish I had asked more questions.\""), .cross("Glass fragments were in your jacket pocket, weren't they?", "\"Yes. I cannot account for them. I did not break any window.\""), .cross("You cannot describe the stranger, can you?", "\"Only a little. A person in a gray jacket at a bus stop. I wish I had looked closer.\""), .cross("$20 is a small amount for towing a trailer, isn't it?", "\"It is. I needed the cash. I should have wondered why.\""), .cross("You were found ten minutes after the break-in, weren't you?", "\"Yes. It was a coincidence. I was on my way to the scrap yard.\""), .cross("You did not look inside the trailer, did you?", "\"No. I should have. I did not want to be nosy.\"")],
        openings: ("At about 5:15 a.m., a passerby heard glass break and saw a person in a gray jacket climb out of {V}'s locked van. Ten minutes later, a deputy found {D} towing a trailer with the generator and toolbox.", "{D} was hired for $20 by a stranger at a bus stop to tow a trailer. {D.He} did not know what was in it and did not run."),
        closings: ("The tools were in {D}'s hands ten minutes after the break-in, glass was in {D.his} jacket pocket, and a pry bar was in {D.his} pack.", "Nobody saw {D} touch the van. A tow truck driver described a different gray jacket at a bus stop. {D.He} was a hired hauler."),
        timeline: [(0, "5:15 a.m.: glass breaks at the tire shop lot."), (0, "5:25 a.m.: a deputy stops {DL} on the road.")],
        identified: "A passerby and a deputy's stop.",
        impact: "\"I lost a generator and every tool I own. I lost a week of work, and I'm behind on the jobs I'd promised. Those tools were how I make my living. I broke into a cold sweat when I saw my van's window. I just want my tools back and for people to leave things alone.\"",
        doctrines: ["burdenOfProof", "eyewitnessID"],
        genders: ["D": .male])

    static let bouncerFlashlightV1 = SmallCases.make(
        key: "story.bouncerFlashlight",
        category: .violent,
        headlines: ["Club Patron's Jaw Broken in Stairwell After Ejection", "Doorman Says He Swung Baton at Man With Broken Bottle"],
        law: "awdwisi",
        threshold: 7,
        spec: "Assaulted {V} with a deadly weapon, a nine-inch steel baton, inflicting serious injury, a fractured jaw, on {DATE}.",
        ages: 23...45,
        victim: true,
        summary: "At about 1:30 a.m. on {DATE}, {D}, a doorman at a nightclub, walked {V} down a back stairwell toward the parking deck after {V} threw a glass at a server. At the landing, {DL} struck {V} once with a steel baton. {V} fell down four steps and was in the hospital for five days with a fractured jaw that had to be wired shut. The stairwell camera shows {V} turning with an arm raised, but not what was in the hand. {DL} says {V} had picked up a broken bottle neck at the bar and brought it into the stairwell.",
        state: [E(.video, 3, "Stairwell Camera", "{D} and {V} reach the landing; {V} turns with an arm up; {D} swings once and {V} drops."), E(.document, 3, "Hospital Records", "A fractured jaw with five days in the hospital, wired shut for six weeks."), E(.physical, 2, "The Baton", "A nine-inch steel baton with a rubber grip, taken from {D}'s belt.", .search)],
        defense: [E(.physical, 2, "Bottle Neck", "A jagged glass bottle neck found on the stairs beneath where {V} fell.", .search), E(.statement, 1, "DJ's Account", "The DJ saw {V} grab a broken bottle off the bar floor before leaving.")],
        role: "Police detective",
        exam: [.direct("What does the stairwell video show?", "\"{D} and {V} reaching the landing. {V} turns with an arm raised, and {DL} swings a steel baton once. {V} falls down four steps.\""), .direct("What happened before the stairwell?", "\"{V} threw a glass at a server at the bar. {DL}, a doorman, walked {V} down a back stairwell toward the parking deck.\""), .direct("What injuries did {V} suffer?", "\"A fractured jaw. {V} was in the hospital for five days, and the jaw was wired shut for six weeks.\""), .direct("What did you recover?", "\"The steel baton from {D.his} belt, and a broken bottle neck a few feet below where {V} landed on the stairs.\""), .direct("What did {DL} tell you when you arrived?", "\"{D.He} said {V} came at {D.him} on the stairs with a broken bottle and that {D.he} swung to defend {D.himself}.\""), .direct("What did the club's second camera show?", "\"{V}'s hand empty and open at chest height when the baton swung. That camera was found later and was not in {DL}'s statement.\""), .cross("The picture in the stairwell is dark, isn't it?", "\"Yes. It is dark, and the angle is not good. I cannot say what was in {V}'s hand from that video.\""), .cross("A bottle neck was found near {V}, wasn't it?", "\"Yes. It was a few feet below where {V} landed. It could have been dropped or fallen.\""), .cross("A cleaning worker saw {V} carrying a broken bottle, didn't the worker?", "\"The worker said so. I have heard that statement.\""), .cross("{D} gave a warning before swinging, didn't {D.he}?", "\"{D.He} says so. The video has no audio, and I cannot confirm it.\""), .cross("{V} had just thrown a glass at a server, hadn't {V}?", "\"Yes. That is why {V} was being escorted out. {V} was aggressive.\"")],
        defenseRole: "Club DJ",
        defenseExam: [.direct("What is your job at the club?", "\"I am the DJ. I work in the booth over the main bar. I can see most of the room from there.\""), .direct("What did you see {V} do that night?", "\"{V} picked up a broken bottle off the bar floor before leaving. I saw it from the booth. {V} tucked it down by {V}'s leg.\""), .direct("How did {V} act?", "\"Aggressive. {V} had been shouting at a server and threw a glass. I was worried someone would get hurt.\""), .direct("Did you tell {D} about the bottle?", "\"I did not have time. {D} was already walking {V} toward the stairwell. I could not reach {DF}.\""), .direct("What did you do after?", "\"I stayed at the booth and kept the music going. I saw security leave and heard about the stairwell later.\""), .direct("What kind of doorman is the defendant?", "\"Calm. {DF} has handled difficult patrons for years and I have rarely seen {DF} use force.\""), .cross("You did not see the stairwell, did you?", "\"No. I could not see the stairwell from the booth. I only saw {V} pick up the bottle.\""), .cross("You were in the booth the whole time, weren't you?", "\"Yes. I stayed in the booth until the noise started.\""), .cross("You work with the defendant, don't you?", "\"Yes. I do. I like {DF}, and I am telling you only what I saw.\""), .cross("You could not see {V}'s hands the whole time, could you?", "\"No. The room was crowded and dark. I saw the bottle for a moment.\""), .cross("You do not know if {V} dropped the bottle on the way, do you?", "\"No. I do not. I only know {V} picked one up.\"")],
        theory: ("{D} broke a patron's jaw with a steel baton on a dark stairwell.", "{V} came into the stairwell with a broken bottle and {D} swung once to stop it."),
        allocution: "\"I saw glass in {V}'s hand and I was afraid I'd be cut. I told {V} twice to drop it, and I swung the flashlight once. I'm sorry for how it ended. {V} had thrown a glass at a server, and I was trying to get {V} out safely.\"",
        truths: ("The club's second camera, found later, showed {V}'s hand empty and open at chest height when the baton swung.", "A cleaning worker said {V} had a broken bottle in hand when {V} walked toward the stairwell."),
        defendant: [.direct("Why did you swing the baton?", "\"I saw glass in {V}'s hand. I was afraid {V} would cut me, and I swung once to stop it.\""), .direct("Did you warn {V}?", "\"Yes. I told {V} to drop it. I said it twice. {V} did not, and {V} turned toward me with an arm up.\""), .direct("What had {V} done earlier?", "\"Thrown a glass at a server. I was escorting {V} out. I wanted to get {V} out of the building without a scene.\""), .direct("Why did you take {V} down the back stairs?", "\"It was the quickest way to the parking deck and kept the patrons from watching. I had done it many times.\""), .direct("What did you do after {V} fell?", "\"I called for help and stayed with {V}. I called an ambulance and told the club manager what happened.\""), .direct("What would you say to {V}?", "\"That I am sorry. I thought I saw a weapon, and I may have been wrong. I did not mean to break your jaw.\""), .cross("The second camera shows {V}'s hand empty, doesn't it?", "\"I have seen that footage. I did not see it then. I saw glass.\""), .cross("You used a steel baton, not a bottle, didn't you?", "\"Yes. It was my only tool. I know it can do serious harm.\""), .cross("The hands were up in the stairwell video, weren't they?", "\"One arm was up. I saw glass. I may have been mistaken.\""), .cross("You swung at someone's head, didn't you?", "\"I swung once at the head and shoulder. I did not aim. It was in the dark.\""), .cross("You could have backed away, couldn't you?", "\"I could have. I did not have time to think.\"")],
        openings: ("A doorman walked {V} down a back stairwell after {V} threw a glass at a server. At the landing, {D} struck {V} once with a steel baton, and {V}'s jaw was fractured and wired shut.", "{V} carried a broken bottle neck into the stairwell, and {D} swung once to stop it. {DL} saw glass in {V}'s hand."),
        closings: ("A raised arm is not a weapon. The club's second camera shows {V}'s hand empty and open when the baton swung, and {V}'s jaw was broken.", "A cleaning worker and a DJ both saw {V} with a broken bottle. {D} swung once in a dark stairwell to stop it, and no more."),
        timeline: [(0, "About 1:15 a.m.: {V} throws a glass at a server."), (0, "About 1:30 a.m.: {D} walks {V} to the back stairwell."), (0, "About 1:32 a.m.: one swing on the landing; {V} falls."), (1, "The stairwell video is recovered by warrant.")],
        identified: "The stairwell camera and {D}'s account to deputies.",
        notDone: ["The club's second camera was never checked.", "The cleaning staff were not interviewed."],
        aggravating: ["The defendant was armed with a deadly weapon at the time of the crime"],
        mitigating: ["The defendant acted under strong provocation", "The defendant has a positive employment history and is gainfully employed"],
        mood: .divided,
        impact: "\"I ate through a straw for six weeks and I still cannot chew steak. I was wrong to throw the glass, but not wrong enough for this.\"",
        doctrines: ["selfDefense", "imperfectSelfDefense", "lesserIncluded"],
        genders: ["D": .male, "V": .male])

    static let aisleSevenV1 = SmallCases.make(
        key: "story.aisleSeven",
        category: .property,
        headlines: ["Pharmacy Counter Regular Caught Slipping Items Into Coat Again", "Bookkeeper Says Shoplifting Began After Husband's Death"],
        law: "misdLarceny",
        threshold: 5,
        spec: "Stole $94 in cosmetics and small household goods from a retail drugstore, on {DATE}.",
        ages: 38...64,
        victim: false,
        summary: "A store detective at a drugstore watched {D} put a $24 lipstick set, a $31 hair dryer, and two boxes of lightbulbs into a tote bag on {DATE}, then pay for a $4 box of tissues and walk out. {D.He} has been stopped at the same store twice this year and ordered to pay each time. {DL} has enough money to cover the items. {DL} says {D.he} has been in grief counseling since a spouse died and cannot explain why {D.he} takes things.",
        state: [E(.video, 3, "Store Camera", "{D} loads a tote bag in the cosmetics aisle, pays for tissues, and walks out."), E(.document, 2, "Prior Incident Reports", "Two earlier stops this year, each ending with a warning and a small purchase.")],
        defense: [E(.document, 2, "Counselor's Letter", "A grief counselor notes that {D} is being treated for impulsive taking since the death of a spouse.")],
        role: "Store detective",
        exam: [.direct("What is your job at the drugstore?", "\"I am the store detective. I watch the floor and the cameras, and I stop people who leave with merchandise they have not paid for.\""), .direct("What did you see {D} do on {DATE}?", "\"{D} put a $24 lipstick set, a $31 hair dryer, and two boxes of lightbulbs into a tote bag in the cosmetics aisle.\""), .direct("What did the defendant pay for?", "\"A $4 box of tissues at the register. {D.He} paid for it, took the receipt, and walked out past the exit with the bag still holding the rest.\""), .direct("What did you do when the defendant reached the exit?", "\"I stepped up, identified myself, and asked {D.him} to come back inside. {D.He} stopped right away and came with me.\""), .direct("Had the defendant been stopped before?", "\"Twice this year. Each time ended with a warning and a small purchase. The reports are in the store's file.\""), .direct("What was the defendant's response when you asked about the bag?", "\"{D.He} said {D.he} did not know why. {D.He} offered to pay at once and said {D.he} had been struggling.\""), .cross("{D} did not run, did {D.he}?", "\"No. {D.He} stopped when I asked and came back inside without any trouble.\""), .cross("{D} could afford to pay for the items, couldn't {D.he}?", "\"Yes. {D.He} had money on hand and offered to pay for everything right away.\""), .cross("{D} has been cooperative each time, hasn't {D.he}?", "\"Yes. {DL} has been polite and apologetic every time. I would not call {DL} defiant.\""), .cross("You learned that the defendant is in grief counseling, didn't you?", "\"I did. A counselor's letter was provided afterward. I cannot say whether it explains this.\""), .cross("The items were not hidden in a coat, were they?", "\"No. They were in a tote bag in plain view of the camera. {DL} did not conceal them from the camera.\"")],
        defenseRole: "Grief counselor",
        defenseExam: [.direct("What is your work?", "\"I am a grief counselor. I work with people who have lost loved ones, and I have seen {D} weekly since the death of {DF}'s spouse.\""), .direct("What does {D} tell you about taking things?", "\"That {D.he} takes things and cannot say why. {D.He} feels a rush and then shame. It is a pattern we are working on.\""), .direct("How would you describe the defendant's grief?", "\"Deep. {D.He} has not slept well and has trouble with daily tasks. Impulsive taking is a known response for some people in grief.\""), .direct("Does the defendant understand that taking is wrong?", "\"Yes. {D.He} knows it is wrong and feels terrible. That is part of why {D.he} came to me for help.\""), .direct("How is treatment going?", "\"{DF} stopped for two months while attending a support group. {DF} relapsed on the anniversary, and we are adjusting the plan.\""), .direct("What do you recommend?", "\"Continued treatment. {D.He} needs help more than punishment. I believe {D.he} can stop with support.\""), .cross("{D} knew it was wrong, didn't {D.he}?", "\"Yes. {D.He} knows. That is why this is so hard for {D.him}.\""), .cross("Treatment does not excuse taking things, does it?", "\"No. It does not. It explains something about why it happens, and it helps with change.\""), .cross("You cannot say the defendant will not take things again, can you?", "\"No. I cannot promise that. Relapse is part of recovery.\""), .cross("You see the defendant once a week, don't you?", "\"Yes. I see {DF} weekly. I do not see {DF} in the store.\""), .cross("You are on the defendant's side, aren't you?", "\"I want what is best for {D.him}. I am here to tell you what I know.\"")],
        theory: ("{D} put unpaid items in a bag and left, again.", "Grief, treatment, and a person who needs help more than a record."),
        allocution: "\"I don't understand why I did it. I felt a rush, and then it was done. I told the detective right away and offered to pay for every item. I'm in treatment, and I'm ashamed. I want it to stop, and I'm sorry to the store.\"",
        truths: ("A garage at {DL}'s house held dozens of unopened store items with tags still on.", "{DL} stopped for two months while attending a support group and relapsed on the anniversary of the death."),
        defendant: [.direct("Why did you take the items without paying?", "\"I do not know. I felt a rush, and then it was done. It is not something I can explain, and it scares me.\""), .direct("Can you pay for them?", "\"Yes. I told the detective right away, and I offered to pay for every item. I have the money.\""), .direct("Why did you pay for the tissues?", "\"I wanted to look normal. I did not want anyone to notice. I know that sounds strange.\""), .direct("What has been going on in your life?", "\"My spouse died last year. Since then I have felt lost and I take things without thinking. I started grief counseling, and it helps.\""), .direct("What do you have at home from earlier?", "\"A garage full of unopened items with tags still on. I never use them. I do not know why I keep taking things.\""), .direct("What would you say to the store?", "\"That I am sorry. I will pay for everything, and I am working with a counselor to stop.\""), .cross("You were stopped twice before this year, weren't you?", "\"Yes. I promised each time that I would stop. I meant it, and I did not.\""), .cross("You relapsed on the anniversary of your spouse's death, didn't you?", "\"Yes. It was a hard day. I do not say that as an excuse, only as what happened.\""), .cross("You stopped for two months while in a support group, didn't you?", "\"Yes. It helped. Then the anniversary came, and I fell back.\""), .cross("You put a lipstick set and a hair dryer in a tote bag, didn't you?", "\"Yes. I did. I know how it looks.\""), .cross("You walked out with the bag, didn't you?", "\"Yes. I did. I walked straight out, and I was ashamed.\"")],
        openings: ("A store detective watched {D} put a lipstick set, a hair dryer, and two boxes of lightbulbs into a tote bag, pay for a $4 box of tissues, and walk out. {D.He} has been stopped twice this year.", "{D} has been grieving since a spouse died and takes things without being able to explain why. {D.He} is in treatment and needs help more than a record."),
        closings: ("{D} had the money, had been stopped twice before, and loaded a tote bag in plain sight. Sorrow does not excuse a bag full of unpaid items.", "{D} cooperated, offered to pay, and is in counseling. A grieving person who needs treatment should not be treated like a hardened thief."),
        timeline: [(-200, "First recorded stop at the store."), (-60, "{DL} begins grief counseling."), (0, "Afternoon: items taken from the cosmetics aisle.")],
        identified: "The store camera and a store detective.",
        aggravating: ["The defendant has prior convictions of the same kind"],
        mitigating: ["The defendant was suffering from a mental or physical condition that reduced culpability", "The defendant has accepted responsibility", "The defendant has a support system in the community"],
        mood: .sympathetic,
        doctrines: ["burdenOfProof", "insanity"])

    static let securityGuardShotV1 = SmallCases.make(
        key: "story.securityGuardShot",
        category: .violent,
        headlines: ["Hospital Garage Guard Shoots Visitor Walking Toward Booth", "Flashlight in Hand: Armed Guard Fires Two Rounds"],
        law: "awdwikisi",
        threshold: 7,
        spec: "Assaulted {V} with a deadly weapon, a handgun, with intent to kill, inflicting serious injury, in a hospital parking garage on {DATE}.",
        ages: 28...46,
        victim: true,
        summary: "At about 2 a.m. on {DATE}, {D}, an armed security guard at a hospital parking garage, turned {V} away from a closed pay booth after {V} argued about a ticket. {V} left, saying, \"I'll be back.\" Ten minutes later {V} came back up the ramp toward the booth with a dark object in {V.his} right hand. {DL} fired twice. One round hit {V} in the thigh. The object was a flashlight. {DL} says {V} held it low and out in front like a pistol and kept coming after being told to stop.",
        state: [E(.video, 3, "Ramp Camera", "{V} walks up the ramp with a right arm at {V.his} side. {D} steps out of the booth and fires twice from about twenty-five feet. The dark object cannot be identified."), E(.physical, 2, "The Flashlight", "A black rubber flashlight found on the ramp beneath {V}. No weapon was found on {V} or in {V.his} car.", .search), E(.document, 2, "Hospital Records", "A gunshot wound to the left thigh with a broken femur and three weeks in the hospital.")],
        defense: [E(.statement, 2, "Attendant's Account", "A lot attendant heard {V} say, \"I'll be back, and you better have a gun.\""), E(.document, 1, "Guard License", "{DL}'s armed guard registration and firearm qualification are both current.")],
        role: "Detective",
        exam: [.direct("What did you find on the ramp at the hospital parking garage?", "\"A black flashlight under {V}, who had been shot in the thigh. We searched the area and found no weapon anywhere on the ramp.\""), .direct("What happened before the shooting?", "\"{V} argued with {D}, an armed security guard, at a closed pay booth about a ticket. {DL} turned {V} away, and {V} said 'I'll be back.'\""), .direct("What does the ramp camera show?", "\"{V} walking up the ramp with an arm at {V}'s side. {DL} steps out of the booth and fires twice from about twenty-five feet.\""), .direct("What were {V}'s injuries?", "\"A gunshot wound to the left thigh with a broken femur. {V} spent three weeks in the hospital and needed surgery.\""), .direct("What did the lot attendant hear?", "\"{V} say 'I'll be back, and you better have a gun.' The attendant heard it as {V} walked away from the booth.\""), .direct("What is {D}'s licensing?", "\"{DL}'s armed guard registration and firearm qualification are both current. {DL} is trained and licensed for that job.\""), .cross("You cannot tell from the video what {V} held, can you?", "\"No. The object cannot be identified from the footage. It was dark, and the hand was at {V}'s side.\""), .cross("{V} told the defendant {V} would be back, didn't {V}?", "\"Witnesses say {V} did. That is part of the record. It is a threatening thing to say to a guard.\""), .cross("A parked driver's phone video shows {V} raising the flashlight, doesn't it?", "\"I have seen it. It shows {V} raising the flashlight in both hands toward {DL} before the shots.\""), .cross("A flashlight can look like a pistol in the dark, can't it?", "\"In poor light, yes. That is a point to consider. I have seen it myself.\""), .cross("{D} was alone on that shift, wasn't {D.he}?", "\"Yes. {DL} was the only guard at the booth. There was no one else to help.\"")],
        defenseRole: "Use-of-force instructor",
        defenseExam: [.direct("What is your job?", "\"I am a use-of-force instructor. I train armed guards and officers on when and how to use force, and I have done it for many years.\""), .direct("How fast can a person close twenty-five feet?", "\"In under three seconds. A guard has very little time to decide when someone is coming toward the booth.\""), .direct("Is a flashlight a gun?", "\"No. But a flashlight held out low in the dark can look like a pistol, especially when the person says they will be back.\""), .direct("What does training say about a threat held low?", "\"A guard must treat an unidentified object as a possible weapon if the person is advancing and ignores commands.\""), .direct("What do you look for in a justified use of force?", "\"Whether the guard had a reasonable belief of danger based on what was known at the time. Hindsight does not decide it.\""), .direct("What would a trained guard do in {D}'s position?", "\"Give a clear warning and create distance. Many would also retreat. A few would fire if the person kept advancing with a dark object.\""), .cross("A flashlight is not a deadly weapon, is it?", "\"Not in itself. But the question is what the guard reasonably believed at the time.\""), .cross("The guard could have retreated into the booth, couldn't the defendant?", "\"Possibly. Each situation is different. I would want to see the layout and the timing.\""), .cross("The video does not show {V} raising the object toward the defendant, does it?", "\"The first camera does not. The driver's phone video does, in the moments before the shots.\""), .cross("You were not there, were you?", "\"No. I am giving you the standards that apply, not what happened.\""), .cross("You are being paid for your time today, aren't you?", "\"I am compensated for my time, not for what I say.\"")],
        theory: ("{D} shot an unarmed visitor who was walking up a ramp with a flashlight.", "A threat, a dark object held low, and a guard with seconds to decide."),
        allocution: "\"I believed I was about to be shot. {V} had said {V} would be back, and {V} came toward me with something dark pointed at me, held low like a pistol. I yelled to drop it twice. I was scared. I'm deeply sorry it turned out to be a flashlight.\"",
        truths: ("{DL} texted a friend earlier that night, \"If that guy comes back I'm done being nice.\"", "A parked driver's phone video later showed {V} raising the flashlight in both hands toward {DL}."),
        defendant: [.direct("Why did you fire?", "\"I thought {V} had a gun. {V} had said {V} would be back, and {V} came up the ramp holding something dark and straight at me.\""), .direct("Did you warn {V}?", "\"Yes. I yelled to drop it twice. {V} kept coming. I was scared, and I fired when {V} did not stop.\""), .direct("How did {V} hold the object?", "\"Low and out in front, like a pistol. I saw something dark pointed at me, and I could not tell what it was.\""), .direct("What had happened earlier?", "\"{V} argued about a ticket and I turned {V} away. {V} said {V} would be back, and ten minutes later {V} was.\""), .direct("What did you do after you fired?", "\"I called for help and checked {V}. I applied pressure to the wound until the paramedics arrived. I was shaking.\""), .direct("What would you say to {V}?", "\"That I am deeply sorry. I thought my life was in danger, and I was wrong about what you held.\""), .cross("No weapon was found on {V}, was there?", "\"No. I did not know that then. I know it now, and I will live with it.\""), .cross("You texted a friend earlier that you were done being nice, didn't you?", "\"Yes. I was frustrated, and the text was venting with no plan. I know how it reads.\""), .cross("The video shows {V}'s arm at {V}'s side, doesn't it?", "\"At first, yes. Then {V} raised it. I saw something pointed at me.\""), .cross("You fired from twenty-five feet, didn't you?", "\"Yes. It was about that. I could not tell what was in {V}'s hand.\""), .cross("You could have retreated into the booth, couldn't you?", "\"I could have. I thought it was too late. I had seconds to decide.\"")],
        openings: ("A security guard at a hospital garage turned {V} away from a closed pay booth. Ten minutes later {V} came back up the ramp with a dark object, and {D} fired twice. It was a flashlight.", "{V} threatened to come back, did, and held a dark object low and forward like a pistol. {D} had seconds to decide."),
        closings: ("A flashlight under {V}, no weapon on the ramp, and two shots from twenty-five feet. {D} texted a friend earlier that night about being done being nice.", "{V} said {V} would be back and came back with a dark object raised toward {D}. A guard's job is to read a threat, and {DL} read it."),
        timeline: [(0, "About 1:50 a.m.: {V} turned away from the pay booth; the threat."), (0, "About 2:00 a.m.: {V} walks up the ramp; {D} fires twice."), (0, "No weapon is found on {V} or in {V.his} car.")],
        identified: "{D} called 911 and reported the shooting.",
        notDone: ["No one measured the lighting on the ramp.", "Other visitors in the garage were never canvassed."],
        mitigating: ["No prior criminal record", "The defendant has been gainfully employed"],
        mood: .divided,
        impact: "\"I was rude and I was wrong to say I would be back. I did not deserve to be shot. I walk with a cane now.\"",
        doctrines: ["selfDefense", "imperfectSelfDefense", "burdenOfProof", "lesserIncluded"])

    static let marketplaceTrailerV1 = SmallCases.make(
        key: "story.marketplaceTrailer",
        category: .property,
        headlines: ["Stolen Bass Boat Found Under Tarp Behind Man's Shed", "Bait Shop Owner's Boat Spotted in Online Listing"],
        law: "possStolen",
        threshold: 6,
        spec: "Possessed a fishing boat and trailer valued at $18,400, the property of {V}, knowing and having reasonable grounds to believe them stolen, on {DATE}.",
        ages: 22...55,
        victim: true,
        summary: "{V}'s bass boat and trailer were taken from behind {V.his} bait shop over a weekend. Twelve days later {V}'s nephew spotted the boat in an online listing for $5,500 and told deputies. Deputies found it under a tarp behind {D}'s shed with the hull number ground off and fresh paint on the trailer fenders. {DL} says {D.he} paid $4,800 cash to a man at a flea market who handed over a handwritten bill of sale.",
        state: [E(.document, 3, "Online Listing", "A listing by {D}'s account showing {V}'s boat with its custom net hooks and a cracked livewell lid."), E(.physical, 3, "Ground Hull Number", "The hull number was ground smooth; a hidden stamp under the console matches {V}'s purchase records.", .search), E(.document, 2, "Value", "Boat $14,000, trailer $4,400.")],
        defense: [E(.statement, 2, "Flea Market Sale", "{DL} says {D.he} met a man at a flea market and paid $4,800 cash for a handwritten bill of sale."), E(.document, 1, "Past Purchases", "{DL} has bought and resold about six small boats in four years.")],
        role: "Bait shop owner",
        exam: [.direct("What do you do for a living?", "\"I own a bait shop and I rent out boats. I have run it for about twenty years, and I keep my bass boat and trailer behind the shop.\""), .direct("What was taken over the weekend?", "\"My bass boat and trailer. They were behind the shop on Friday and gone on Monday morning. The lock on the hitch had been cut.\""), .direct("How did you find the boat again?", "\"A relative of mine spotted it in an online listing twelve days later for $5,500. The photos showed the custom net hooks and a cracked livewell lid.\""), .direct("What made you certain it was yours?", "\"The net hooks are ones I welded myself, and the livewell lid has a crack I have been meaning to fix. I knew them at once.\""), .direct("Where did deputies find the boat?", "\"Behind {D}'s shed under a tarp. The hull number had been ground off, and the trailer fenders had fresh paint.\""), .direct("What is the boat worth?", "\"About $14,000 for the boat and $4,400 for the trailer. A boat like that is worth much more than $5,500.\""), .cross("You never saw {D} at your shop, did you?", "\"No. I had never seen {DL} before. I do not know how {DL} learned about my boat.\""), .cross("Would a used boat sell for less than new, wouldn't it?", "\"Of course. New, it would be near $18,400. Used, maybe fourteen thousand, as I said.\""), .cross("The boat was listed in the defendant's own account, wasn't it?", "\"Yes. It was {D.his} account, and {D.he} did not hide the listing. It had {D.his} name on it.\""), .cross("Deputies found the boat in plain sight behind a shed, correct?", "\"Under a tarp, behind the shed. It was not hidden far from the house.\""), .cross("You do not know where the defendant got the boat, do you?", "\"No. I only know it was mine and that {D.he} had it. I do not know the rest.\"")],
        defenseRole: "Flea market vendor",
        defenseExam: [.direct("What is your work?", "\"I am a vendor at a flea market. I sell tools and old fishing gear on weekends. I was at the market the day {D} bought the boat.\""), .direct("What did you see that day?", "\"I saw someone hand {DF} a trailer hitch and talk for a few minutes. I did not see the whole exchange.\""), .direct("Do you know the seller?", "\"No. I had seen the seller around the market a time or two. I do not know a name.\""), .direct("How did {D} behave?", "\"Normally. {D.He} was friendly and looked at the boat for a while. {D.He} did not seem to be in a rush.\""), .direct("Did the defendant seem to know it was stolen?", "\"No. I did not see anything to suggest it. {D.He} looked like a buyer who thought {D.he} had found a deal.\""), .direct("How often do boats change hands at the market?", "\"Now and then. It is not the usual stock. Most sales are small items.\""), .cross("You did not see the defendant pay for the boat, did you?", "\"No. I saw a hitch handed over. I did not see money change hands.\""), .cross("You do not know where the seller got the boat, do you?", "\"No. I have no idea. I only know what I saw at the market.\""), .cross("You do not know the defendant well, do you?", "\"No. I know {D.him} from the market. We say hello.\""), .cross("You do not know what was said, do you?", "\"No. I was too far away to hear. I only saw the exchange.\""), .cross("You cannot say whether a bill of sale was written then, can you?", "\"No. I did not see paper. I only saw them talk.\"")],
        theory: ("{D} kept and tried to sell a boat with its hull number ground off.", "A bargain from a stranger at a flea market."),
        allocution: "\"I bought that boat at a flea market from a man who said the title was lost, and I paid forty-eight hundred dollars in cash. It was too good a deal, and I should have known better. I'm sorry {V} lost a boat, and I'll cooperate however I can.\"",
        truths: ("{DL}'s phone had a text from the seller, \"got another one just like it if you want it.\"", "The seller was arrested months later with a storage unit of stolen boats and named {DL} among his buyers, who he'd lied to."),
        defendant: [.direct("How did you get the boat?", "\"I bought it at a flea market. I met someone there who had a boat on a trailer and a handwritten bill of sale.\""), .direct("Why was the bill of sale handwritten?", "\"The seller said the title was lost. I did not think that was unusual. People lose titles all the time.\""), .direct("How much did you pay?", "\"$4,800 in cash. It was a lot for me, but I thought it was a fair price for a used bass boat.\""), .direct("Why was the hull number ground off?", "\"It was ground off when I got it. I did not notice at first, and I did not ask about it.\""), .direct("What did you do with the boat?", "\"I put it behind my shed and planned to fix it up and resell it. I have done that with several small boats.\""), .direct("What would you say to {V}?", "\"That I am sorry. I did not know the boat was stolen, and I am glad you have it back.\""), .cross("You paid about a quarter of its value, didn't you?", "\"Yes. It looked like a deal. It was a trade-in deal, I was told, and I did not ask for more details.\""), .cross("You have bought and resold about six small boats in four years, haven't you?", "\"Yes. I do it as a hobby. I know what a fair price looks like, and I should have been more careful.\""), .cross("The seller texted that there was another one just like it, didn't the seller?", "\"Yes. I know that. It looks bad. I did not follow up.\""), .cross("You did not check the hull number, did you?", "\"No. I did not. I should have, and I know that now.\""), .cross("The paint on the trailer fenders was fresh, wasn't it?", "\"Yes. I painted them. I did not think anything about it.\"")],
        openings: ("{V}'s bass boat and trailer were taken from behind a bait shop. Twelve days later, deputies found the boat under a tarp behind {D}'s shed with its hull number ground off and fresh paint on the trailer.", "{D} bought the boat from a stranger at a flea market with a handwritten bill of sale. {D.He} did not know it was stolen and kept it in the open."),
        closings: ("A boat worth $14,000 bought for $4,800, a hull number ground off, and fresh paint on the trailer. {D} has bought and resold boats before.", "The seller was later arrested with a storage unit of stolen boats and named {D} among the buyers the seller lied to. {D.He} did not know."),
        timeline: [(-12, "Weekend: boat and trailer taken from behind the bait shop."), (-6, "{DL} lists the boat online."), (0, "{V}'s nephew spots the listing; deputies search behind {DL}'s shed.")],
        identified: "An online listing and a search behind {D}'s shed.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mitigating: ["The defendant has made substantial or full restitution", "The defendant has a positive employment history and is gainfully employed"],
        mood: .indifferent,
        impact: "\"I lost the summer fishing season when that boat was taken. It was how I paid the shop's bills, and I had to turn customers away. I still check behind the shop every morning. It took twelve days to find it, and I got no apology from the man who bought it.\"",
        doctrines: ["burdenOfProof", "mistakeOfFact"])

    static let farmGateShotsV1 = SmallCases.make(
        key: "story.farmGateShots",
        category: .violent,
        headlines: ["Landowner Fires Shotgun at Truck Leaving Hunting Lease", "Passenger Peppered With Birdshot at Locked Gate"],
        law: "dischargingOccupied",
        threshold: 6,
        spec: "Discharged a firearm into an occupied vehicle, a pickup truck in which {V} was a passenger, while it was in operation, on {DATE}.",
        ages: 52...71,
        victim: true,
        summary: "About midnight on {DATE}, a pickup with its spotlight on drove along the fence line of {D}'s hunting lease. {DL}, who had found two deer carcasses and a cut fence the week before, walked out with a 12-gauge shotgun and a flashlight. The driver turned toward the gate. {D.He} fired twice at the truck as it pulled away. Birdshot struck the tailgate and the back window, and {V}, in the passenger seat, was hit in the left arm and cheek. {DL} says the truck headed for {D.him} first and {D.he} fired at the tires.",
        state: [E(.physical, 3, "Truck Damage", "Dozens of birdshot holes across the tailgate and rear window, all from behind the truck.", .search), E(.document, 3, "Emergency Room Records", "Pellets removed from {V}'s left arm and cheek; a graze below the left eye."), E(.statement, 2, "Driver", "The driver says the truck turned to leave when the shots began.")],
        defense: [E(.document, 2, "Poaching Reports", "Two reports {DL} filed in the prior ten days: deer carcasses and a cut fence on the lease."), E(.physical, 1, "Tire Ruts", "Ruts show the truck came within thirty feet of where {DL} stood before turning.")],
        role: "Sheriff's investigator",
        exam: [.direct("What did you find when you examined the truck after the shooting?", "\"Holes in the tailgate and the back window from birdshot. The pattern shows the shots came from behind the truck as it was pulling away.\""), .direct("What injuries did {V} suffer?", "\"Pellets in the left arm and cheek, and a graze below the left eye. {V} was treated in the emergency room and released after pellets were removed.\""), .direct("What did {D} tell you?", "\"That {D} fired to stop poachers. {D.He} said the truck came toward {D.him} and that {D.he} aimed at the tires.\""), .direct("What did the tire ruts show?", "\"That the truck came within about thirty feet of where {D.he} stood before it turned. The ruts show a turn toward the gate.\""), .direct("What had the defendant reported before the shooting?", "\"Two poaching reports in the prior ten days: deer carcasses and a cut fence on the lease. We had received both.\""), .direct("What did the driver say?", "\"That the truck turned to leave when the shots began. The driver did not say the truck had been driven at {DL}.\""), .cross("{D} had reported poaching twice, hadn't {D.he}?", "\"Yes. Twice in ten days. We had not yet followed up on either one.\""), .cross("{D} was about thirty feet from the ruts, wasn't {D.he}?", "\"Yes, about thirty feet. That is close for a truck to come, with a spotlight in {D.his} face.\""), .cross("A spotlight can blind a person at night, can't it?", "\"Yes. It is bright and disorienting. I understand that could make a person feel threatened.\""), .cross("You did not see the shooting, did you?", "\"No. I arrived afterward. I rely on the physical evidence and the statements.\""), .cross("The truck was on a private lease at midnight, wasn't it?", "\"Yes. It was on the lease. I do not have any reason to think the driver had permission.\"")],
        defenseRole: "Neighboring landowner",
        defenseExam: [.direct("How do you know {D}?", "\"I own the land next to {D}'s lease. We talk over the fence, and I have seen {DF} often.\""), .direct("What had you seen at night in the area?", "\"A spotlight on the same road twice in the past week. I did not know who it was, but it worried me.\""), .direct("What did you hear the night of the shooting?", "\"Two shots. I was at my house. I did not see what happened, but I heard the truck rev afterward.\""), .direct("What had the defendant told you about poaching?", "\"That {D.he} had found two carcasses and a cut fence. {D.He} was angry and worried about the land.\""), .direct("What kind of person is the defendant?", "\"Quiet. {DF} keeps to {D.himself} and cares about the land. I have never known {DF} to be reckless.\""), .direct("Do you have poaching problems yourself?", "\"Yes. I have found cut fences and carcasses too. It is a real problem in this area.\""), .cross("You did not see the shooting, did you?", "\"No. I only heard two shots. I did not see the truck or {DF}.\""), .cross("You cannot say where the truck was when the defendant fired, can you?", "\"No. I was at my house. I do not know where it was.\""), .cross("You are a neighbor of the defendant, aren't you?", "\"Yes. I like {DF}. I am only telling you what I saw and heard.\""), .cross("You never saw a gun, did you?", "\"No. I never saw one. I only heard the shots.\""), .cross("You do not know who was in the truck, do you?", "\"No. I never saw them. I only know about the spotlight on the road.\"")],
        theory: ("{D} fired a shotgun at the back of a truck that was leaving.", "A landowner confronted by poachers who drove toward {D.him}."),
        allocution: "\"I'd found two deer carcasses and a cut fence the week before, and I was angry that night. I fired toward the tires to stop that truck. I'm sorry a young person got hurt. I let my frustration decide, and I never meant to hit anyone.\"",
        truths: ("{DL} told a neighbor the next morning, \"They weren't going to get away this time.\"", "The driver admitted to a friend that he swung the truck toward {DL} with the spotlight to scare the landowner."),
        defendant: [.direct("Why did you fire at the truck?", "\"It came at me. I was standing on the road with a flashlight and a shotgun, and the truck turned toward me with a spotlight in my face.\""), .direct("Where did you aim?", "\"At the tires. I wanted to stop the truck. I did not mean to hit anyone, and I did not think about the passengers.\""), .direct("What had been happening on your lease?", "\"Poachers had been killing deer and cutting my fence. I found two carcasses in a week and called the sheriff twice.\""), .direct("Why did you go out with a shotgun?", "\"I saw a spotlight along the fence line at midnight, and I thought it was the poachers again. I took my shotgun and a flashlight.\""), .direct("What was the truck doing when you fired?", "\"It was turning. It had come toward me and was pulling away toward the gate. I fired as it turned.\""), .direct("What would you say to {V}?", "\"That I am sorry. I did not mean to hit anyone, and I wish I had stayed in my house and called for help.\""), .cross("The pellets are in the back window and the tailgate, aren't they?", "\"Yes. That is where they hit. The truck was turning, and I know how it looks.\""), .cross("You told a neighbor the next morning that they were not going to get away this time, didn't you?", "\"I said something like that. I was angry and shaken, and it was just talk.\""), .cross("The truck was leaving when you fired, wasn't it?", "\"It was turning to leave. It had come at me first, and I fired as it moved.\""), .cross("You could have called the sheriff's office instead, couldn't you?", "\"I had called twice already and nothing came of it. I should have called again.\""), .cross("{V} was a passenger, not the driver, wasn't {V}?", "\"Yes. I did not know that. I am sorry.\"")],
        openings: ("At midnight, a pickup with a spotlight drove along the fence line of {D}'s hunting lease. {D.He} walked out with a shotgun and fired twice as the truck pulled away, and {V} was hit in the arm and cheek.", "{D} had two poaching reports and a truck that came within thirty feet with a spotlight in {D.his} face. {D.He} fired at the tires."),
        closings: ("The shots hit the back of a truck that was leaving, and {D} told a neighbor they would not get away this time. A passenger was hit in the arm and cheek.", "{D} had two reports unanswered and a spotlight in {D.his} face at midnight. The driver later admitted swinging the truck toward {DL}."),
        timeline: [(-10, "{DL} reports a cut fence and deer carcasses."), (0, "Midnight: the truck with a spotlight on the fence line."), (0, "Two blasts as the truck turns toward the gate."), (0, "{V} is treated at the hospital; {DL} is arrested at home.")],
        identified: "The driver went to deputies; {D} confirmed firing.",
        notDone: ["The driver's blood alcohol was never tested.", "No one measured where {DL} stood."],
        mitigating: ["No prior criminal record", "The defendant has been a person of good character"],
        mood: .divided,
        impact: "\"I still find a pellet in my cheek when I shave. I should not have been out there.\"",
        doctrines: ["selfDefense", "burdenOfProof", "lesserIncluded"],
        genders: ["D": .male])

    static let tobaccoBarnFireV1 = SmallCases.make(
        key: "story.tobaccoBarnFire",
        category: .property,
        headlines: ["Packhouse Fire Destroys Sweet Potato Crop and Sorter", "Canine Alert Points Fire Marshal to Pour Pattern in Farm Building"],
        law: "burningBuildings",
        threshold: 7,
        spec: "Willfully and wantonly set fire to and burned a packhouse, a building used for curing and grading sweet potatoes, on {DATE}.",
        ages: 50...70,
        victim: false,
        summary: "A farm packhouse on {D}'s land burned at about 3 a.m. on {DATE}, along with a grading line and about 900 bushels of sweet potatoes. Three weeks earlier {DL} had added a fire and loss rider that raised coverage on the building to $240,000. The farm had missed two loan payments. A State fire investigator's accelerant-detecting dog alerted at the loading door, and a lab found gasoline in swabs from the floor. A road camera caught {D.his} pickup passing at 2:20 a.m. {DL} says {D.he} was driving to a night shift at a feed mill and the fire began with old wiring in the packhouse.",
        state: [E(.forensic, 3, "Dog and Lab", "A trained dog alerted at the loading door and the lab found gasoline in three of five floor swabs."), E(.video, 3, "Road Camera", "{D}'s pickup passes the packhouse road toward the farm at 2:20 a.m. with no stops."), E(.document, 2, "Insurance Rider", "A rider raising coverage to $240,000 was signed by {D} twenty-one days before the fire.")],
        defense: [E(.document, 2, "Electrician Note", "A repair note from the prior year: \"Old knob wiring in packhouse, advised rewire, owner could not afford.\""), E(.document, 1, "Time Clock", "{D}'s feed mill punch card shows a punch-in at 3:10 a.m.")],
        role: "State fire investigator",
        exam: [.direct("What is your role with the State?", "\"I am a fire investigator. I examine the cause and origin of suspicious fires, and I work with trained dogs and the state lab.\""), .direct("Where did your dog alert at the packhouse?", "\"At the loading door, the same spot where the lab later found gasoline. The dog is trained to alert on ignitable liquid residue.\""), .direct("What did the lab find?", "\"Gasoline in three of five floor swabs. The pour pattern on the floor is consistent with liquid poured near the door and ignited.\""), .direct("What was lost in the fire?", "\"A farm packhouse, a grading line, and about 900 bushels of sweet potatoes. The fire started about 3 a.m. and the building was a total loss.\""), .direct("What did you learn about the insurance?", "\"{D} had signed a rider twenty-one days before the fire raising coverage on the building to $240,000. The farm had also missed two loan payments.\""), .direct("What did the road camera show?", "\"{D.his} pickup passing the packhouse road toward the farm at 2:20 a.m. with no stops. It was about forty minutes before the fire.\""), .cross("Old wiring is a common cause of fires, isn't it?", "\"Yes, it is. We looked at it carefully. An electrician had noted old knob wiring in the packhouse the year before.\""), .cross("A dog can alert on cleaning supplies, can't it?", "\"It can. That is why the lab tests are important. The lab found gasoline, not a cleaning product.\""), .cross("You did not rule out wiring entirely, did you?", "\"We did not rule out wiring as a possible source, but the pour pattern and the lab result point to a liquid accelerant.\""), .cross("{D} punched in at the feed mill at 3:10 a.m., didn't {D.he}?", "\"Yes. The punch card shows it. I know that cuts against the timing of the fire.\""), .cross("A gas receipt is not proof of setting a fire, is it?", "\"No. A receipt shows a purchase. It does not show how the gasoline was used.\"")],
        defenseRole: "Feed mill supervisor",
        defenseExam: [.direct("What is your job at the feed mill?", "\"I am the supervisor on the night shift. I set the schedule, keep the time clock, and see who comes in.\""), .direct("When did {D} clock in on the night of the fire?", "\"At 3:10 a.m., ten minutes after the shift started. I looked at the punch card the next day when the investigators asked.\""), .direct("Was that unusual?", "\"A little. {D} is usually on time. {D.He} said {D.he} had been delayed on the road, and I did not think anything of it.\""), .direct("How did the defendant seem when {D.he} arrived?", "\"Normal. {D.He} said hello and went to the line. {D.He} did not smell of smoke or gasoline, and I did not notice anything unusual.\""), .direct("What kind of employee is the defendant?", "\"Reliable. {D.He} works hard and does not cause trouble. {D.He} had been working night shifts for about a year.\""), .direct("How did the defendant react when {D.he} heard about the fire?", "\"With shock. {D.He} left early to go see the building. {D.He} was in tears when {D.he} came back.\""), .cross("You cannot say where the defendant was before 3:10, can you?", "\"No. I only know when {D.he} punched in. I do not know where {D.he} was before.\""), .cross("The mill is not far from the packhouse road, is it?", "\"About twenty minutes by truck. A person could stop on the way and still make it by 3:10.\""), .cross("You did not see the defendant arrive in the lot, did you?", "\"No. I was inside at the time clock. I only saw {DF} come to the line.\""), .cross("{D} was ten minutes late, wasn't {D.he}?", "\"Yes. It was only ten minutes, and it was the first time in weeks.\""), .cross("You like the defendant, don't you?", "\"Yes. I do. I try to tell you what I know.\"")],
        theory: ("{D} raised insurance, poured gasoline, and burned a packhouse.", "Old wiring, a night shift, and an honest fire."),
        allocution: "\"I did not set that fire. That building was part of my livelihood, and I lost a year of work in it. I raised the insurance only because the adjuster said I was underinsured. I was on the road to my night shift at the feed mill. I'm sorry for what it cost my neighbors.\"",
        truths: ("A receipt for a five-gallon can of gasoline was found in {DL}'s truck, though the farm ran only on diesel.", "A former farmhand with a grudge was later arrested for setting a fire at another farm and admitted this one."),
        defendant: [.direct("Did you set the packhouse on fire?", "\"No. I did not. That building was part of my livelihood, and I lost a year's crop in that fire.\""), .direct("Why did you raise the insurance coverage?", "\"The adjuster told me the building was underinsured. I raised it as the adjuster recommended. It was an ordinary decision.\""), .direct("Where were you at 2:20 a.m.?", "\"On the road to my night shift at the feed mill. I take that road every night, and the camera caught me passing.\""), .direct("What caused the fire in your view?", "\"Old wiring in the packhouse. An electrician warned me to rewire it. I could not afford it, and I wish I had found the money.\""), .direct("Why did you miss loan payments?", "\"A bad crop year. Prices dropped and my costs rose. I was behind, like many farmers around here.\""), .direct("What do you remember about the gas receipt?", "\"I do not remember buying it. It was a five-gallon can, and my farm runs on diesel. I cannot explain it.\""), .cross("You raised coverage twenty-one days before the fire, didn't you?", "\"Yes. The adjuster suggested it. I know how the timing looks.\""), .cross("A receipt for a five-gallon can of gasoline was in your truck, wasn't it?", "\"Yes. I do not remember it. It was in the truck, and I cannot say how it got there.\""), .cross("The farm was behind on two loan payments, wasn't it?", "\"Yes. Everyone knew it was a hard year. I did not burn my own building.\""), .cross("Gasoline was found on the floor of the packhouse, wasn't it?", "\"So the lab reports. I never carried gasoline into that building.\""), .cross("You passed the packhouse road at 2:20, forty minutes before the fire, didn't you?", "\"Yes. I was on my way to work. I did not stop.\"")],
        openings: ("A farm packhouse burned at 3 a.m. with 900 bushels of sweet potatoes. Three weeks earlier, {D} had raised the insurance to $240,000, and a dog and a lab found gasoline at the loading door.", "{D} was driving to a night shift at a feed mill when the fire started. Old wiring that an electrician warned about is a more likely cause."),
        closings: ("A rider signed three weeks earlier, a gas can receipt in {D}'s truck, gasoline in the floor swabs, and {D.his} pickup on the road at 2:20 a.m.", "A former farmhand with a grudge was later arrested for setting another fire and admitted this one. Old wiring and a bad year explain the rest."),
        timeline: [(-21, "{DL} signs the insurance rider."), (-10, "A default notice arrives on the loan."), (0, "About 2:20 a.m.: {DL}'s truck passes the road camera."), (0, "About 3 a.m.: the packhouse burns."), (25, "The lab finds gasoline in three of five swabs.")],
        identified: "A canine alert, a road camera, and the insurance rider.",
        notDone: ["The former farmhand was not interviewed.", "The feed mill's gate camera was never pulled."],
        aggravating: ["The offense was committed for pecuniary gain", "The defendant planned the offense"],
        mitigating: ["The defendant has a support system in the community", "The defendant has a positive employment history and is gainfully employed"],
        mood: .divided,
        doctrines: ["expertTestimony", "burdenOfProof", "characterEvidence"])

    static let softballBatV1 = SmallCases.make(
        key: "story.softballBat",
        category: .violent,
        headlines: ["Pickup Basketball Dispute Ends With Tire Iron to the Face", "Player's Cheekbone and Jaw Broken in Park Lot Fight"],
        law: "awdwisi",
        threshold: 7,
        spec: "Assaulted {V} with a deadly weapon, a steel tire iron, inflicting serious injury, at a park parking lot on {DATE}.",
        ages: 26...50,
        victim: true,
        summary: "After a pickup basketball game at a city park on {DATE}, {V} and {D} argued by the lot about a flagrant foul. Witnesses agree {V} grabbed {DL}'s shirt and shoved {D.him} between two cars. {DL} reached into the bed of {D.his} truck and swung a tire iron once. It struck {V} across the left cheek and jaw. {V} needed surgery and a metal plate. {DL} says {V} threw the first punch and was charging when the iron swung.",
        state: [E(.document, 3, "Surgical Records", "A fractured left cheekbone and jaw repaired with a metal plate. {V} spent three nights in the hospital and has trouble chewing."), E(.video, 2, "Phone Video", "Nine seconds from a bench thirty yards away. {V} shoves {D}, {D} turns to the truck, and the swing comes. Whether {V} is moving toward {D} is not clear."), E(.physical, 2, "Tire Iron", "A 24-inch steel tire iron with a bent tip, taken from the bed of {D}'s truck.", .search)],
        defense: [E(.statement, 2, "Referee's Account", "The pickup game's organizer says {V} had been warned twice for hard fouls that night and \"was spoiling for a fight.\""), E(.document, 1, "Park Ban", "{V} was told to leave the park league last year for shoving a player.")],
        role: "Sheriff's investigator",
        exam: [.direct("What did you recover from {D}'s truck?", "\"A steel tire iron from the truck bed with blood on it. It was the iron that struck {V} across the cheek and jaw.\""), .direct("What were {V}'s injuries?", "\"A fractured left cheekbone and jaw, repaired with a metal plate. {V} spent three nights in the hospital and has trouble chewing.\""), .direct("What did the defendant tell you?", "\"That {V} threw the first punch and was charging when {D} swung. {DL} said {DL} turned to the truck to protect {D.himself}.\""), .direct("What does the phone video show?", "\"Nine seconds from a bench thirty yards away. {V} shoves {DL}, {DL} turns to the truck, and then the swing comes.\""), .direct("What did the organizer of the pickup game say?", "\"That {V} had been warned twice for hard fouls that night and was spoiling for a fight.\""), .direct("What did you learn about {V}'s history at the park?", "\"{V} was told to leave the park league the year before for shoving a player. That was in the park's records.\""), .cross("The video shows {V} shoving the defendant, doesn't it?", "\"Yes. It shows a shove. {V} grabbed {DL}'s shirt and pushed {DL} between two cars.\""), .cross("You cannot tell from the video if {V} was charging, can you?", "\"Not clearly. The video is from thirty yards away and the picture is small.\""), .cross("A second video was found later, wasn't it?", "\"Yes. It shows {V}'s hands. I have seen it, and it is not conclusive.\""), .cross("{D} was cornered between two cars, wasn't {D.he}?", "\"{DL} was between two cars after the shove. I do not know how much room {DL} had.\""), .cross("{V} was the first to grab and shove, wasn't {V}?", "\"Yes. Witnesses agree on that. It is part of what I considered.\"")],
        defenseRole: "Pickup game organizer",
        defenseExam: [.direct("What do you do at the park?", "\"I organize the pickup basketball game. I set the teams, keep order, and make sure it stays friendly.\""), .direct("What was {V} like that night?", "\"Angry. {V} had been fouling hard, and I told {V} to cool down twice. {V} was spoiling for a fight.\""), .direct("How did {D} behave that night?", "\"Calm. {D} played hard but did not start anything. {D.He} was not the aggressor in any foul.\""), .direct("What did you see after the game?", "\"I was packing the ball bag. I heard shouting by the lot and looked over. I did not see the swing.\""), .direct("What did you do after you heard it?", "\"I ran over and found {V} on the ground. I called 911 and stayed until help came.\""), .direct("What kind of person is the defendant?", "\"Even-tempered. I have never seen {DF} in a fight. {DF} is one of the more relaxed players.\""), .cross("You did not see the swing, did you?", "\"No. I was packing the ball bag. I only saw {V} after.\""), .cross("You did not see {V} charge, did you?", "\"No. I heard shouting but did not see the movement.\""), .cross("You like the defendant, don't you?", "\"I do. I am telling you what I saw, and what I did not see.\""), .cross("{V} was warned for hard fouls, but never for violence, was {V}?", "\"Not that night. Last year, yes, for shoving.\""), .cross("You cannot say what the defendant was thinking, can you?", "\"No. I only know what {D.he} looked like when I got there. {D.He} looked shocked.\"")],
        theory: ("{D} grabbed a steel tire iron and swung it into a player's face.", "{V} shoved and charged, and {D} swung once to stop it."),
        allocution: "\"I grabbed the nearest thing in my truck and swung hard, and I think about the sound every day. {V} came at me and I wasn't thinking. I'm sorry for what I did. I'll pay for the medical bills and never pick up anything like that again.\"",
        truths: ("A second video, found later, showed {V} with both hands at {V.his} sides when the iron came around.", "A second video, found later, showed {V} lunging with a cocked fist as the iron swung."),
        defendant: [.direct("Why did you get the tire iron?", "\"{V} was coming after me. I turned to my truck and grabbed the nearest thing. I was scared.\""), .direct("Did you aim for {V}'s head?", "\"I just swung. I did not aim. I saw {V} coming, and I swung once. I did not mean to hit {V}'s face.\""), .direct("What happened before the shove?", "\"We argued about a flagrant foul. {V} grabbed my shirt and shoved me between two cars. I was pinned.\""), .direct("Why did you not leave?", "\"I was cornered between the cars. {V} was between me and the lot, and I felt trapped.\""), .direct("What did you do after you swung?", "\"I dropped the iron and stood still. I could see {V} was hurt. I stayed until deputies came and told them what I had done.\""), .direct("What would you say to {V}?", "\"That I am sorry. I did not mean to hurt you this badly, and I will help with your bills.\""), .cross("You turned your back on {V} to get the iron, didn't you?", "\"I turned to the truck. I know it looks like I walked away to arm myself. I was trying to protect myself.\""), .cross("You swung a steel bar at someone's face, didn't you?", "\"I swung it at {V}. I know where it landed, and I regret it.\""), .cross("A second video shows {V}'s hands at {V}'s sides, doesn't it?", "\"Another video shows that. I saw a fist coming. I may have been mistaken.\""), .cross("You could have called for help, couldn't you?", "\"Yes. I could have. I did not think of it.\""), .cross("You were not injured, were you?", "\"Not seriously. A bruise on my chest from the shove. {V} was hurt far worse.\"")],
        openings: ("After a pickup basketball game, {V} and {D} argued by the lot about a foul. {V} shoved {DL}, and {DL} swung a tire iron once, fracturing {V}'s cheek and jaw and requiring a metal plate.", "{V} grabbed {D} by the shirt, shoved {DL} between two cars, and charged, so {DL} swung once to stop it. {DL} was cornered and afraid."),
        closings: ("A broken cheekbone and jaw from a steel bar. {D} turned to the truck, grabbed the iron, and swung it at {V}'s face.", "A second video shows {V} lunging with a cocked fist as the iron swung. {D} swung once after being shoved and rushed."),
        timeline: [(0, "About 8:30 p.m.: the flagrant foul and the argument."), (0, "{V} shoves {D}; {D} goes to the truck bed; one swing."), (0, "Deputies arrive; the tire iron is taken; {V} goes to the hospital."), (2, "{V} has surgery.")],
        identified: "{D} stayed at the scene and admitted the swing.",
        notDone: ["The park's lot lighting was not checked.", "Not every player's phone was asked for video."],
        aggravating: ["The victim suffered permanent injury"],
        mitigating: ["The victim was a voluntary participant in the conduct", "No prior criminal record"],
        mood: .divided,
        doctrines: ["selfDefense", "burdenOfProof", "lesserIncluded"])

    static let crabPotTheftV1 = SmallCases.make(
        key: "story.crabPotTheft",
        category: .property,
        headlines: ["Oysters Vanish From Leased Bottom; Patrol Finds Sales Tickets", "Trail Camera Catches Skiff Working Another Waterman's Oyster Lease"],
        law: "felonyLarceny",
        threshold: 6,
        spec: "Stole about 60 bushels of cultivated oysters valued at $2,400, belonging to {V}, from {V.his} leased oyster ground, on {DATE}.",
        ages: 25...60,
        victim: true,
        summary: "{V} grows oysters on a leased bottom marked by four white stakes. On the morning of {DATE}, {V} found the cages emptied and the marker stakes pulled up. A trail camera on {V}'s dock caught a skiff passing at 4:15 a.m., and its hull number was partly readable. The number belonged to {D}. A seafood dealer's ticket showed 58 bushels sold the same morning under {D.his} license. {DL} says {D.he} worked the public bottom next to the lease and the stakes were already gone.",
        state: [E(.document, 3, "Dealer Ticket", "A seafood dealer's ticket for 58 bushels of oysters bought from {D} at 6:40 a.m."), E(.video, 3, "Trail Camera", "A skiff with a partly visible hull number passes the lease at 4:15 a.m.; two figures aboard."), E(.document, 2, "Value", "60 bushels at $40 each: $2,400.")],
        defense: [E(.document, 2, "Public Bottom Map", "The state survey shows public oyster bottom adjacent to the lease boundary."), E(.statement, 1, "Missing Stakes", "{DL} says the stakes were already down when {D.he} arrived.")],
        role: "Marine patrol officer",
        exam: [.direct("What is your work as a marine patrol officer?", "\"I patrol the waters, check licenses and gear, and investigate thefts from leased oyster beds and crab pots. I know the shoreline well.\""), .direct("What did {V} report on the morning of {DATE}?", "\"That the cages on {V}'s lease had been emptied and the four white marker stakes pulled up. {V} grows oysters on a leased bottom.\""), .direct("What did the trail camera on the dock show?", "\"A skiff passing the lease at 4:15 a.m. with two figures aboard. Part of the hull number was readable, and it matched {D}'s registration.\""), .direct("What did the dealer's ticket show?", "\"58 bushels of oysters bought from {D.him} at 6:40 a.m. under {D.his} license. The dealer opens early for the watermen.\""), .direct("How much were the oysters worth?", "\"About $2,400, at roughly $40 a bushel. That was close to the amount missing from {V}'s cages.\""), .direct("What did {D} tell you?", "\"That {D.he} worked the public bottom next to the lease and that the stakes were already down when {D.he} arrived.\""), .cross("The hull number was only partly visible, wasn't it?", "\"Yes. It was partly readable. It matched {D.his} skiff, but I understand there are other skiffs of that type.\""), .cross("Public bottom runs next to the lease, doesn't it?", "\"Yes. The state survey shows public bottom on the east side of the lease. {D.He} had every right to work there.\""), .cross("The stakes were missing when {D} arrived, according to {D}, correct?", "\"That is what {D.he} says. I cannot confirm it. The stakes were found pulled up and tossed on the shore.\""), .cross("Two figures were in the skiff, weren't they?", "\"Yes. The camera shows two. I do not know who the second was.\""), .cross("A rival waterman later admitted pulling the stakes, didn't a rival?", "\"Yes. Someone did later say so. That statement is in the file.\"")],
        defenseRole: "Fellow waterman",
        defenseExam: [.direct("What is your work?", "\"I am a waterman. I harvest oysters and crabs on the public bottom, and I work near {D} most weeks.\""), .direct("Did you work the public bottom that week?", "\"Most of the week. The stakes were gone on the lease for days before the theft. I noticed they were down.\""), .direct("What did you see on the water that morning?", "\"I saw several skiffs. I did not look at the hull numbers. I saw {D.his} skiff go by toward the public bottom.\""), .direct("How does the public bottom work?", "\"Anyone with a license can harvest there. It runs right up to the lease line, and the line is not always clear without stakes.\""), .direct("What kind of waterman is {D}?", "\"Honest. {D.He} follows the rules and has never been a problem. {D.He} works hard and sells at the same dealer every day.\""), .direct("Have there been thefts on the lease before?", "\"Not that I know of. There was some talk of a rival who wanted it, but I have no names.\""), .cross("You did not see the defendant that morning, did you?", "\"I saw a skiff that looked like {DF}'s. I did not see {DF}'s face.\""), .cross("You do not know what the defendant harvested that day, do you?", "\"No. Only {D.his} own account. I was working my own bottom.\""), .cross("The stakes were down before the theft, weren't they?", "\"I noticed they were down a day or two earlier. I cannot say who pulled them.\""), .cross("You and the defendant are friends, aren't you?", "\"We are friendly on the water. I am only describing what I saw myself.\""), .cross("You cannot say how the cages were emptied, can you?", "\"No. I never saw them emptied. I only know the stakes were missing.\"")],
        theory: ("{D} emptied another waterman's cages and sold the catch.", "A waterman on public bottom beside a lease with missing stakes."),
        allocution: "\"I worked the public bottom beside the lease that morning, and I sold to the dealer right at six. I crossed the line, and I know it. I'll make it right, replace the stakes, and pay for what was taken.\"",
        truths: ("{DL}'s phone has a photo of full cages on the lease dated two days before the theft.", "A rival waterman later admitted pulling the stakes and emptying the cages, then selling the oysters under a borrowed license."),
        defendant: [.direct("Where did you get the oysters you sold?", "\"From the public bottom beside the lease. I worked it that morning. I harvested every bushel there.\""), .direct("Why did you sell them so early?", "\"The dealer opens at six. I like to sell right away so the oysters are fresh. I do it every day.\""), .direct("Was that your skiff on the camera?", "\"The hull number looks like mine. It is a common skiff on this coast. There are many like it.\""), .direct("Where were the stakes when you got there?", "\"Gone. They were pulled out and I did not think much about it. I stayed on the public bottom side.\""), .direct("Who was with you in the skiff?", "\"A friend who helps me on the water. We both worked the public bottom that morning.\""), .direct("What would you say to {V}?", "\"That I am sorry for your loss. I did not take your oysters, and I hope you find who did.\""), .cross("You have a photo of full cages on the lease from two days earlier, don't you?", "\"Yes. I took it because I admired how well the lease looked. I did not take anything from it.\""), .cross("Your hull number is on the camera at 4:15, isn't it?", "\"Yes. We passed the lease on the way to the public bottom. It is on the way.\""), .cross("You sold 58 bushels, and {V} lost about that many, didn't {V}?", "\"Yes. It is a coincidence. I harvested those from public bottom.\""), .cross("The stakes were pulled up the same night, weren't they?", "\"I do not know when. They were gone when I came.\""), .cross("You did not call anyone about the missing stakes, did you?", "\"No. I should have. It did not seem like my business.\"")],
        openings: ("{V} grows oysters on a leased bottom marked by four white stakes. One morning the cages were empty and the stakes pulled up, a trail camera caught a skiff matching {D}'s, and a dealer bought 58 bushels from {DL}.", "{D} worked the public bottom beside the lease and sold what {D.he} harvested there. The stakes were already gone, and the hull number is common."),
        closings: ("A skiff with a hull number matching {D}'s at 4:15, 58 bushels sold under {D.his} license at 6:40, and a lease with its cages emptied.", "A rival waterman later admitted pulling the stakes, emptying the cages, and selling the oysters under a borrowed license. {D} worked public bottom."),
        timeline: [(-2, "{V} checks the cages; all are full."), (0, "4:15 a.m.: a skiff passes the trail camera."), (0, "6:40 a.m.: a dealer buys 58 bushels from {DL}."), (0, "{V} finds the cages emptied and the stakes gone.")],
        identified: "A trail camera and a dealer's ticket.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mitigating: ["The defendant has been gainfully employed", "The defendant has a support system in the community"],
        mood: .indifferent,
        doctrines: ["burdenOfProof", "mistakeOfFact", "lesserIncluded"])

    static let sneakerMeetupV1 = SmallCases.make(
        key: "story.sneakerMeetup",
        category: .violent,
        headlines: ["Student Shot Dead Selling E-Bike in Church Parking Lot", "Classified Ad Buyer Charged in Fatal Robbery"],
        law: "murder1",
        threshold: 8,
        spec: "Killed {V} by shooting {V.him} in the chest during the perpetration of a robbery with a firearm (first-degree murder under the felony murder rule).",
        ages: 18...24,
        victim: true,
        summary: "{V}, 19, fixed up and resold used electric bikes to pay for trade school. A buyer answering an online ad agreed to pay $900 for a refurbished e-bike and set a meeting at a church parking lot at 9:10 p.m. on {DATE}. {V} came in a van with a friend who stayed in the passenger seat. The buyer asked to test-ride it, took the bike around the lot, returned, pulled a pistol, and said, \"Give me the key.\" When {V} stepped forward, the buyer fired once, hitting {V} in the chest. {V} died at the scene. Deputies traced the buyer's prepaid number and later found the bike in {D}'s garage. {DL} says {D.he} bought the bike from a man on the street and was never at the church.",
        state: [E(.digital, 3, "Phone Records", "The buyer's prepaid number pinged a tower covering the church from 8:55 to 9:20 p.m., and the same phone then connected near {D}'s home.", .search), E(.physical, 3, "The E-Bike", "The refurbished e-bike with {V}'s serial label was in {D}'s garage, the battery freshly wiped.", .search), E(.forensic, 3, "Firearms Comparison", "The casing from the lot and the bullet from the autopsy were fired from the pistol found in {D}'s car."), E(.statement, 2, "Friend's Identification", "{V}'s friend picked {D} from a lineup: \"I think that's the one. Eighty percent.\"")],
        defense: [E(.statement, 1, "Lineup Confidence", "The friend saw the buyer for seconds under a dim parking lot light."), E(.statement, 2, "Street Seller", "{DL}'s cousin says a man called Tee brought the bike to {D}'s garage and left a bag in the car.")],
        role: "Homicide detective",
        exam: [.direct("What led you to {D} in the investigation of {V}'s death?", "\"The buyer's prepaid phone number, which we traced, and then the bike. A deputy found {V}'s refurbished e-bike in {D}'s garage.\""), .direct("What happened at the church parking lot?", "\"{V}, 19, came in a van with a friend to sell a refurbished e-bike for $900. The buyer test-rode it, came back, pulled a pistol, and shot {V} once in the chest.\""), .direct("What did you find in the defendant's car?", "\"A pistol that matched the casing from the lot and the bullet from the autopsy. It was in the car in a bag.\""), .direct("What did {V}'s friend say?", "\"The friend stayed in the passenger seat and saw the buyer for a few seconds under a dim light. The friend picked {DL} from a lineup at about eighty percent.\""), .direct("What did the defendant tell you about the bike?", "\"That {DL} bought it from someone on the street, someone called Tee. {DL} said Tee brought the bike to the garage and left a bag in the car.\""), .direct("What do you know about the prepaid phone?", "\"It was activated at a store where {D.he} used {D.his} own rewards card. That is one of the connections we found.\""), .cross("No one placed the defendant at the church except a friend at eighty percent, correct?", "\"Yes. The friend said, 'I think that's the one,' at about eighty percent. That is the only identification.\""), .cross("The friend saw the buyer for only seconds, didn't the friend?", "\"Yes. Under a dim parking lot light. I understand the limits of that kind of identification.\""), .cross("{D} told you someone else brought the bike, didn't {D.he}?", "\"Yes. {D.He} said a street seller named Tee did. We later arrested someone by that name.\""), .cross("You did not see the shooting, did you?", "\"No. I arrived afterward. I rely on the forensic evidence and the identification.\""), .cross("A pistol can be left in a car by someone else, can't it?", "\"Yes. That is possible. I considered it, and I also considered the phone and the bike.\"")],
        defenseRole: "{DL}'s cousin",
        defenseExam: [.direct("How are you related to {D}?", "\"I am {D}'s cousin. We grew up near each other, and I am at {D.his} house often.\""), .direct("Who brought the bike to the defendant's garage?", "\"Someone named Tee came by that week. I was there. Tee talked with {D.him} for a few minutes and left.\""), .direct("Did you see a bag left in the defendant's car?", "\"Yes. Tee put a bag in the back seat when Tee left. I did not see what was in it.\""), .direct("What did the defendant do when Tee left?", "\"{D.He} looked at the bike and said it was a good price. {D.He} cleaned it later that day.\""), .direct("Where was the defendant the night of the shooting?", "\"At home. I came by around eight, and {D.he} was there watching TV. I left a little after nine.\""), .direct("What kind of person is the defendant?", "\"Not violent. {D.He} has never owned a gun that I know of. I was shocked when I heard what happened.\""), .cross("You do not know Tee's full name, do you?", "\"No. I only know that name. Tee does not live near us.\""), .cross("You left around nine, didn't you?", "\"A little after nine. The shooting was at 9:10 at the church. I cannot say where {D.he} was after I left.\""), .cross("You did not look in the bag, did you?", "\"No. I did not. I did not know about a pistol.\""), .cross("You are close to the defendant, aren't you?", "\"Yes. I love {DF}. I am only describing what I saw myself.\""), .cross("You cannot say the defendant did not leave after you did, can you?", "\"No. I cannot say that. I only know when I left.\"")],
        theory: ("{D} lured a young seller to a parking lot, took the bike, and shot {V.him}.", "A bike bought on the street and a pistol left in a car by someone else."),
        allocution: "\"I did not do this, and I was at home that night. I bought that bike from a man called Tee on the street and planned to resell it. I'm deeply sorry for {V}'s family and the pain they're in. I hope the truth comes out.\"",
        truths: ("The prepaid phone was activated at a store where {DL} used {D.his} own rewards card.", "A man named Tee was later arrested with two more stolen e-bikes and admitted leaving a bag with a pistol in {DL}'s car."),
        defendant: [.direct("Were you at the church that night?", "\"No. I was at home. I did not go near that church, and I did not meet {V}.\""), .direct("Where did you get the bike?", "\"From someone on the street. A person called Tee came by with the bike and said it was cheap. I paid cash.\""), .direct("Why was the bike in your garage?", "\"I planned to resell it. I buy and resell bikes. I did not know it came from {V} or that anyone had been hurt.\""), .direct("Why was a pistol in your car?", "\"I did not know it was there. Someone left a bag in the car, and I did not look inside. I do not own that pistol.\""), .direct("Why did you clean the bike's battery?", "\"It was dirty. I wiped it down because I wanted it to look good for a buyer. I was not hiding anything.\""), .direct("What would you say to {V}'s family?", "\"That I am sorry for your loss. I did not do this, and I hope the truth comes out.\""), .cross("The phone was activated at a store where you used your rewards card, wasn't it?", "\"Yes. I buy things there. I do not know how that connects. I did not buy a prepaid phone for this.\""), .cross("The pistol in your car matches the casing, doesn't it?", "\"That is what they say. I did not fire it. I did not know it was there.\""), .cross("You wiped the battery of {V}'s bike, didn't you?", "\"I cleaned it. I did not know whose it was. I know how it looks.\""), .cross("The bike was in your garage, wasn't it?", "\"Yes. I bought it from a stranger and asked far too little about it.\""), .cross("You cannot give Tee's full name, can you?", "\"No. I only know that name. I do not know where Tee lives.\"")],
        openings: ("{V}, 19, was shot at a church parking lot while selling a refurbished e-bike for $900. Deputies traced the buyer's phone, found the bike in {D}'s garage, and found a pistol in {DL}'s car that matched the casing.", "{D} bought a bike from a stranger and had a pistol left in a car by someone else. A friend's eighty percent is not certainty."),
        closings: ("The phone, the bike, and the pistol all lead to {D}. {V}'s friend picked {DL} from a lineup, and {DL} cleaned the bike's battery.", "Someone named Tee was later arrested with two more stolen e-bikes and admitted leaving a bag with a pistol in {D}'s car. A pistol is not a person."),
        timeline: [(0, "9:10 p.m.: the meeting at the church lot."), (0, "9:15 p.m.: one shot; the buyer leaves with the bike."), (3, "The buyer's prepaid number is traced."), (5, "Deputies search {DL}'s garage and car.")],
        identified: "Phone records and the bike in a garage.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof", "eyewitnessID", "expertTestimony"])

    static let lockoutBreakInV1 = SmallCases.make(
        key: "story.lockoutBreakIn",
        category: .property,
        headlines: ["Tenant Charged After Pulling Plywood Off Padlocked Trailer", "Lot Owner Boarded Up Mobile Home Without Eviction Order"],
        law: "feloniousBE",
        threshold: 7,
        spec: "Broke and entered a mobile home at Lot 9 with intent to commit larceny therein, on {DATE}.",
        ages: 23...45,
        victim: true,
        summary: "{D} was five weeks behind on lot rent at a mobile home park. While {D.he} was working a double shift on {DATE}, {V}, who owns the park, padlocked the door and nailed plywood over the back door of Lot 9. No court had ordered an eviction. Late that night {DL} pulled the plywood off, forced the lock, and loaded a washing machine, a television, and two boxes of clothing into a pickup. {V}'s gate camera recorded it. {DL} says everything inside belonged to {D.him} and {D.he} was entering {D.his} own home.",
        state: [E(.video, 3, "Gate Camera", "A pickup backs to Lot 9 at 11:40 p.m. and a figure carries out a washer and two boxes."), E(.physical, 3, "Pried Plywood", "Plywood torn from the back door with pry marks and a broken padlock hasp.", .search), E(.document, 2, "Lot Notice", "A posted notice of unpaid rent and a warning that the unit was secured.")],
        defense: [E(.document, 2, "Court Search", "The clerk's records show no summary ejectment filed against {D}."), E(.document, 1, "Lease Copy", "The lease says only a court order may remove a tenant.")],
        role: "Responding deputy",
        exam: [.direct("What did you see when you responded to Lot 9?", "\"The plywood had been pulled off the back door and the lock was broken. Inside, there were boxes and empty spaces where large items had been.\""), .direct("What was in the pickup at the lot?", "\"A washer, a television, and two boxes of clothing. They were loaded in the bed and covered with a tarp.\""), .direct("What did {V}'s gate camera show?", "\"A pickup backing to Lot 9 at 11:40 p.m. and a figure carrying out a washer and two boxes. It was a clear recording.\""), .direct("What notice had {V} posted at the lot?", "\"A notice of unpaid rent and a warning that the unit was secured. It was taped to the front door and it was dated that day.\""), .direct("What did you learn about the lease?", "\"That only a court order may remove a tenant. The lease says so in plain terms in the section on default and removal.\""), .direct("What did {D} tell you?", "\"That everything belonged to {D} and that {D.he} was entering {D.his} own home. {D.He} was upset and said {D.he} had just come off a double shift.\""), .cross("You did not find anything of {V}'s in the pickup, did you?", "\"No. It all looked like {DL}'s belongings, including the clothes. I did not find any property that belonged to the park.\""), .cross("No eviction order existed, did one?", "\"Not that I found. The clerk's records show no summary ejectment filed against {DL}.\""), .cross("{V} secured the home without a court order, didn't {V}?", "\"That is what the records suggest. {V} padlocked the door and nailed plywood over the back.\""), .cross("{D} was five weeks behind on rent, wasn't {D.he}?", "\"Yes. That is not disputed. But the lease and the law require a court process for removal.\""), .cross("{D} did not run when you arrived, did {D.he}?", "\"No. {D.He} stayed and talked to me. {D.He} was cooperative and answered every question.\"")],
        defenseRole: "Legal aid paralegal",
        defenseExam: [.direct("What is your work?", "\"I am a paralegal at a legal aid office. I help tenants understand their rights when a landlord threatens to evict them.\""), .direct("Was there an eviction case against {D}?", "\"No. No case was ever filed. I checked the clerk's records, and there was nothing.\""), .direct("What does the law require before a tenant can be removed?", "\"A court order. A landlord cannot change locks or board up a unit without one. Self-help evictions are not allowed.\""), .direct("Did {V} have a history of lockouts?", "\"Yes. {V} had locked out two other tenants the same way. A legal aid lawyer had warned {V} in writing.\""), .direct("Did the defendant owe rent?", "\"Yes. Five weeks. That is not denied. But owing rent does not allow a landlord to lock a tenant out.\""), .direct("What would you advise a tenant in the defendant's position?", "\"To call legal aid and the sheriff's office, not to break a lock. I wish {D} had called us first.\""), .cross("{D} broke a lock, didn't {D.he}?", "\"Yes. That is what happened. I do not defend it.\""), .cross("{D} could have gone to court, couldn't {D.he}?", "\"Yes. We could have helped file a case. {D.He} did not call us in time.\""), .cross("{D} took property at night, didn't {D.he}?", "\"Yes. I cannot say why it was at night. I do not know what was in {D.his} mind.\""), .cross("You work with tenants, don't you?", "\"Yes. I help tenants. I am telling you what the law says, not what I wish.\""), .cross("The rent was five weeks late, wasn't it?", "\"Yes. {D.He} was behind, and the park had a right to pursue it in court.\"")],
        theory: ("{D} broke into a secured home at night and took belongings.", "A tenant locked out without a court order took back {D.his} own things."),
        allocution: "\"It was my home and my things behind that plywood, and I came off a double shift to find the door locked. I pulled off the board and broke the lock because I didn't know any other way to get my belongings. I'm five weeks behind on rent, and I'm sorry to {V}. I'll pay for the lock.\"",
        truths: ("{DL} told a coworker, \"I'm taking the washer and TV and selling them before {V.he} gets them.\"", "{V} had locked out two other tenants the same way and had been warned in writing by a legal aid lawyer."),
        defendant: [.direct("Why did you pull the plywood off the door?", "\"It was my home and my things. I came off a double shift and found the door boarded up. I wanted my belongings.\""), .direct("Why did you go at night?", "\"I got off work late. It was the first time I could get there. I did not hide, and I parked right at the lot.\""), .direct("How did you get in?", "\"I pulled off the plywood and broke the lock. There was no other way in. I did not damage anything inside.\""), .direct("What did you take?", "\"A washer, a television, and two boxes of clothes. All of it was mine. I bought the washer and the television myself.\""), .direct("Why did you say you would sell the washer and television?", "\"I was angry and worried about money. I said it to a coworker, and I did not mean it. I wanted my things back.\""), .direct("What would you say to {V}?", "\"That I should have gone to court and not broken the lock, and that you should not have locked me out without an order.\""), .cross("You told a coworker you were taking the washer and TV to sell them first, didn't you?", "\"I said it in anger. I was upset about being locked out, and it was talk.\""), .cross("You broke a lock that belonged to {V}, didn't you?", "\"Yes. It was the padlock {V} put on. I did not see another way in.\""), .cross("You were five weeks behind on rent, weren't you?", "\"Yes. I was behind because of cut hours. I was trying to catch up.\""), .cross("You did not go to a court, did you?", "\"No. I did not. I did not have money for a lawyer.\""), .cross("You took the property at night, didn't you?", "\"Yes. I got off work late. I did not mean to hide it.\"")],
        openings: ("A park owner padlocked and boarded up Lot 9 after five weeks of unpaid rent. Late that night, {D} pulled off the plywood, broke the lock, and loaded a washer, a television, and two boxes of clothes.", "{D} was locked out of {D.his} own home with no court order and took back {D.his} own belongings. The lockout was unlawful."),
        closings: ("The gate camera shows {D} backing a pickup to Lot 9 and carrying out a washer and boxes. {DL} told a coworker {D.he} would sell them first.", "No court order means no lawful lockout. {V} had locked out two other tenants the same way and had been warned in writing by a legal aid lawyer."),
        timeline: [(0, "Day: {V} padlocks and boards the unit."), (0, "11:40 p.m.: {DL} pulls the plywood and loads the pickup."), (0, "Midnight: {V} calls 911.")],
        identified: "{V}'s gate camera.",
        mitigating: ["No prior criminal record", "The defendant supports the defendant's family", "The defendant has been gainfully employed"],
        mood: .sympathetic,
        impact: "\"I own nine lots and I'm behind too. I didn't think I needed a court to lock my own property.\"",
        doctrines: ["burdenOfProof", "lesserIncluded", "mistakeOfFact"])

    static let barStoolV1 = SmallCases.make(
        key: "story.barStool",
        category: .violent,
        headlines: ["Cast-Iron Skillet Swing Fractures Guest's Cheekbone at Cookout", "Backyard Birthday Party Ends With Surgery and a Self-Defense Claim"],
        law: "awdwisi",
        threshold: 8,
        spec: "Assaulted {V} with a deadly weapon, a cast-iron skillet, by striking {V.him} in the face, inflicting serious injury: fractures of the left cheekbone and eye socket requiring surgery.",
        ages: 24...45,
        victim: true,
        summary: "On {DATE} at about 9 p.m., at a birthday cookout in a backyard, {D} and {V} argued over a card game. {V}, who had been drinking beer all afternoon, grabbed {DL} by the throat and pinned {D.him} against a truck. A guest's phone video shows {DL} break free, grab a cast-iron skillet off the grill table, and swing it into {V}'s face. {V}'s cheekbone and eye socket were fractured and needed surgery. {DL} says {V} was choking {D.him} and {D.he} could not breathe.",
        state: [E(.video, 3, "Guest's Phone Video", "{V} pins {D} by the throat for about four seconds. {D} breaks free, grabs the skillet, and swings from the grill table."), E(.document, 3, "Surgical Records", "Fractures of the left cheekbone and eye socket repaired with plates; double vision for two months."), E(.physical, 2, "The Skillet", "A twelve-inch cast-iron skillet, weighing about five pounds, with blood on the rim.", .search)],
        defense: [E(.document, 2, "Neck Photos", "Red marks on both sides of {D}'s neck, photographed at the jail."), E(.statement, 2, "Host's Account", "The host says {V} was drunk, loud, and had grabbed {D} hard.")],
        role: "Detective",
        exam: [.direct("What does the guest's phone video show?", "\"{V} pinning {D} by the throat for about four seconds against a truck. {DL} breaks free, grabs a skillet off the grill table, and swings.\""), .direct("What injuries did {V} suffer?", "\"Fractures of the left cheekbone and eye socket, repaired with plates. {V} had double vision for two months.\""), .direct("What was the argument about?", "\"A card game. {DL} and {V} got into it over a hand, and {V}, who had been drinking beer all afternoon, grabbed {DL}.\""), .direct("What did you find in the photos of {D}'s neck?", "\"Red marks on both sides of {D.his} neck. They were taken at the jail the night of the incident.\""), .direct("What did the host tell you?", "\"That {V} was drunk, loud, and had grabbed {DL} hard. The host said {DL} had been calm before that.\""), .direct("What did the defendant tell you about the skillet?", "\"That {D.he} could not breathe and grabbed what was within reach. It was on the grill table next to the truck.\""), .cross("{D} had marks on both sides of the neck, didn't {D.he}?", "\"Yes. The photos show red marks on both sides. They fit what {DL} described.\""), .cross("The grip lasted about four seconds, didn't it?", "\"Yes. About four seconds on the video. It may have been longer before the video started.\""), .cross("{V} had been drinking all afternoon, hadn't {V}?", "\"Yes. The host said so, and guests agreed. {V} was loud and unsteady.\""), .cross("{D} was not drunk, was {D.he}?", "\"No. {D.He} had one beer, I understand. {D.He} was sober and was driving later.\""), .cross("A second video shows {V} still gripping the defendant's collar, doesn't it?", "\"I have seen it. It shows both hands on the collar when the skillet swung. That is a point in the video.\"")],
        defenseRole: "Cookout host",
        defenseExam: [.direct("How do you know {D} and {V}?", "\"I hosted the cookout. I know both of them from the neighborhood. {D} is a quiet neighbor, and {V} is a regular at gatherings.\""), .direct("What was {V} like that night?", "\"Drunk and shoving people. {V} had been drinking all afternoon and was loud. I told {V} twice to calm down.\""), .direct("What happened with the card game?", "\"{DF} and {V} argued over a hand. {V} got angry and grabbed {DF} by the throat. It happened fast.\""), .direct("What did you see of the defendant?", "\"{D.He} was pinned against the truck and looked terrified. I saw {D.his} face turn red. I started toward them.\""), .direct("What did you see {V} do before the swing?", "\"I saw {V} let go before the swing. It was only a moment. I cannot say how long exactly.\""), .direct("What kind of person is the defendant?", "\"Gentle. {D.He} has never been in a fight that I know of. I was shocked by what happened.\""), .cross("You saw {V} let go before the swing, didn't you?", "\"Yes. I saw {V} let go. It was a moment before. I cannot say it was not at the same time.\""), .cross("You did not see the entire grip, did you?", "\"No. I saw part of it. I was on the other side of the yard when it started.\""), .cross("You like the defendant, don't you?", "\"I do. I am trying to be fair and to describe only what I actually saw.\""), .cross("You told {V} to calm down twice, didn't you?", "\"Yes. {V} did not listen. {V} was drunk and loud.\""), .cross("You did not see {D}'s face when {D} swung, did you?", "\"No. I saw {D.his} back. I could not see {D.his} face.\"")],
        theory: ("{D} broke free, grabbed a skillet, and swung it at a man who had let go.", "A man held by the throat who swung to breathe."),
        allocution: "\"That night at the cookout I couldn't breathe, and I couldn't push {V} off me. I grabbed the skillet that was within reach and swung. I never chose it. I'm sorry I hurt {V.him} that badly, and I'm sorry that a birthday party ended in an operating room.\"",
        truths: ("{DL} told a coworker, \"I saw {V.him} let go and figured, now's my chance.\"", "A guest's second video showed {V} still gripping {D}'s collar with both hands when the skillet swung."),
        defendant: [.direct("Why did you swing the skillet?", "\"I could not breathe, and I could not push {V} off. I grabbed the skillet because it was within reach. I swung to make {V} let go.\""), .direct("What did {V} do before you swung?", "\"{V} grabbed me by the throat and pinned me against the truck. I felt my vision going dark, and I was terrified.\""), .direct("What would you say to {V}?", "\"I'm sorry {V.he} was hurt. I only wanted to breathe and get away, and I never meant it to go that far.\""), .direct("How long did it feel like {V} held you?", "\"Much longer than four seconds. It felt like a minute. I could not get air, and I was panicking.\""), .direct("What did you do after the swing?", "\"I dropped the skillet and stepped back. I saw {V} was hurt, and I called for help. I stayed there.\""), .direct("Do you remember what happened right before?", "\"Not clearly. It happened so fast, and I only remember the shouting.\""), .cross("You told a coworker you saw {V} let go and figured it was your chance, didn't you?", "\"I said something like that. I was telling it badly. I did not mean it the way it sounds.\""), .cross("The video shows {V} letting go, doesn't it?", "\"It shows a hand falling away. I felt it a second after I swung.\""), .cross("Four seconds is a short time, isn't it?", "\"It is, but it felt long. I could not breathe at all.\""), .cross("You swung a cast-iron skillet at someone's face, didn't you?", "\"I swung it at {V}. I know where it hit. I am sorry.\""), .cross("You could have shouted for help, couldn't you?", "\"I could not make a sound. I did not have air.\"")],
        openings: ("At a birthday cookout, {V} grabbed {D} by the throat and pinned {DL} against a truck. A guest's video shows {DL} break free, grab a skillet, and swing it into {V}'s face, fracturing {V}'s cheekbone and eye socket.", "{V}, drunk and loud after an afternoon of beer, was choking {D} against a truck, and {DL} could not breathe. {DL} swung once to get free."),
        closings: ("The video shows a hand falling away from {D}'s collar before the skillet came around. {D.He} told a coworker it was a chance.", "A hand on the throat, red marks on both sides of {D}'s neck, and one swing to breathe. {D.He} did not have time to think."),
        timeline: [(0, "Afternoon: drinking at the cookout."), (0, "9 p.m.: {V} pins {D}; one swing."), (0, "Deputies arrive; {V} goes to the hospital.")],
        identified: "A guest's phone video and {D}'s own statement.",
        mitigating: ["No prior criminal record", "The victim was the initial aggressor", "Steady employment"],
        mood: .divided,
        impact: "\"I own that I grabbed {D.him}. I live with double vision now and I cannot climb a ladder. I'm a roofer.\"",
        doctrines: ["selfDefense", "burdenOfProof"],
        genders: ["D": .male, "V": .male])

    static let utilityImpostorV1 = SmallCases.make(
        key: "story.utilityImpostor",
        category: .property,
        headlines: ["Man Posing as County Water Inspector Takes Cash and Watch From Widow", "\"He Wore a Hard Hat and Carried a Test Kit\": Elderly Man Lets Fake Inspector In"],
        law: "feloniousBE",
        threshold: 7,
        spec: "Entered the residence of {V} by deception, falsely claiming to be a county water department inspector, with intent to commit larceny, on {DATE}.",
        ages: 28...50,
        victim: true,
        summary: "At about 9:30 a.m. on {DATE}, a man in a hard hat and a reflective vest knocked at the home of {V}, 79, saying the county water department needed to test the kitchen tap for lead. {V} let the visitor in, and the visitor stayed fifteen minutes. That afternoon {V} found an envelope with $1,800 in cash and a gold watch missing from a bedroom drawer. A neighbor's camera caught a white van with a magnetic sign leaving. The watch was pawned two days later with {D}'s ID. {V} picked {DL} from a photo array. {DL} says {D.he} was delivering parcels all morning and sold the watch for a friend.",
        state: [E(.video, 3, "Neighbor's Camera", "A white van with a magnetic sign stops at {V}'s house at 9:28 a.m. and leaves at 9:47 a.m.; the driver wears a hard hat."), E(.document, 3, "Pawn Slip", "A gold watch pawned under {D}'s ID and thumbprint at 11:10 a.m. two days later."), E(.statement, 2, "Photo Array", "{V} picked {D}: \"That's the face under the hard hat.\"")],
        defense: [E(.document, 2, "Delivery Log", "{D}'s courier scanner shows eleven stops in another town between 9:15 and 11:40 a.m."), E(.statement, 1, "Friend's Watch", "{DL} says a friend asked {D.him} to pawn the watch.")],
        role: "Property crimes detective",
        exam: [.direct("How did you trace the gold watch?", "\"A pawn slip came back to {D}, with {D.his} ID and thumbprint. The watch was pawned two days after the theft at 11:10 a.m.\""), .direct("What happened at {V}'s home on {DATE}?", "\"A visitor in a hard hat and a reflective vest said the county water department needed to test the tap for lead. {V}, who is 79, let the visitor in.\""), .direct("What was taken?", "\"An envelope with $1,800 in cash and a gold watch from a bedroom drawer. {V} found them missing that afternoon.\""), .direct("What did the neighbor's camera show?", "\"A white van with a magnetic sign stopping at {V}'s house at 9:28 a.m. and leaving at 9:47. The driver wore a hard hat.\""), .direct("What did {V} say at the photo array?", "\"{V} picked {DL} and said, 'That's the face under the hard hat.' {V} hesitated a little before choosing.\""), .direct("What did {D} tell you?", "\"That {DL} was delivering parcels in another town that morning. {DL} said a friend asked {D.him} to pawn the watch.\""), .cross("The van was not registered to the defendant, was it?", "\"No. It is registered to a coworker of {DL}'s. I do not know how {DL} connects to it.\""), .cross("{V} hesitated at the photo array, didn't {V}?", "\"A little. {V} looked at all six and then chose {DL}. It was not instant.\""), .cross("{D}'s courier scanner shows stops in another town, doesn't it?", "\"Yes. Eleven stops between 9:15 and 11:40. I am aware of that. It is important evidence.\""), .cross("{D} used a real ID at the pawn shop, didn't {D.he}?", "\"Yes. {D.He} used {D.his} own ID and thumbprint. {D.He} did not hide who {D.he} was.\""), .cross("Someone arrested a year later confessed to the same scheme, didn't they?", "\"Yes. The man was arrested in another county and confessed to a similar scheme, including this one.\"")],
        defenseRole: "Courier dispatcher",
        defenseExam: [.direct("What is your job?", "\"I am a dispatcher for a courier company. I assign routes and track each driver's scanner and stops.\""), .direct("Where was {D} that morning?", "\"The scanner shows eleven stops in the next town between 9:15 and 11:40. Each stop has a time and a signature.\""), .direct("How reliable is the scanner?", "\"Very. Each scan has a GPS tag and a time stamp. We use it for billing, so we watch it closely.\""), .direct("Can the scanner be lent to someone else?", "\"It can, but it was locked to {D}'s login. Another person would need {DF}'s password to use it.\""), .direct("How did the defendant work that day?", "\"Normally. {D.He} was on time and made all stops. I did not receive any complaints.\""), .direct("What kind of employee is the defendant?", "\"Reliable. {D.He} has worked here for two years and has never had a theft or a complaint.\""), .cross("You do not know where the defendant was at 9:30, do you?", "\"The scanner shows stops, but not each minute. I know where {D.he} was at the scanned times.\""), .cross("The next town is not far, is it?", "\"About thirty minutes. It would be hard but not impossible to travel between.\""), .cross("A scanner can be passed to someone else, can't it?", "\"It can, but it would take {D.his} login. I do not think that happened.\""), .cross("You like the defendant, don't you?", "\"Yes. {DF} is a good employee. I am telling you what the data shows.\""), .cross("You did not see the defendant that morning, did you?", "\"No. I was in the office. I saw the data.\"")],
        theory: ("{D} lied to get in and took cash and a watch from a widower.", "A delivery driver in another town and a watch pawned for a friend."),
        allocution: "\"I was making deliveries in another town that morning and never went to that house. A friend asked me to pawn the watch, saying it was a family item, and I did. I'm deeply sorry that an elderly woman was frightened in a kitchen that should have been safe. I never meant to be part of that.\"",
        truths: ("The van's registered owner is {DL}'s coworker, and {DL}'s phone had a photo of a hard hat and a vest.", "A man arrested a year later for the same water-inspector scheme confessed and returned the cash envelope."),
        defendant: [.direct("Were you at {V}'s house that morning?", "\"No. I was making deliveries in another town. I had eleven stops, and the scanner shows every one.\""), .direct("Why did you pawn the watch?", "\"A friend asked me to. The friend said it was a family item and that the shop gave a good price. I did not ask more.\""), .direct("Who is the friend?", "\"Someone I know from work. I do not know where the friend got the watch. I should have asked.\""), .direct("Why did you use your own ID?", "\"I had nothing to hide. I thought it was an ordinary favor. I gave my ID and thumbprint as requested.\""), .direct("Do you have a hard hat and vest?", "\"I have a hard hat and a vest from work. I have a photo on my phone. It does not mean I wore them at {V}'s home.\""), .direct("What would you say to {V}?", "\"That I am so sorry for what happened. I did not do it, and I hope you get your property back.\""), .cross("The van's registered owner is your coworker, isn't it?", "\"Yes. I know the owner. I did not drive the van, and I was not there.\""), .cross("Your phone had a photo of a hard hat and a vest, didn't it?", "\"Yes. They are from my job. I took a photo for a safety report.\""), .cross("You pawned a stolen watch, didn't you?", "\"I pawned a watch for a friend, with no idea it was stolen.\""), .cross("{V} picked you from a photo array, didn't {V}?", "\"Yes. I understand. It is a mistake.\""), .cross("You cannot name the friend with certainty, can you?", "\"I know a name. I cannot prove it. I wish I could.\"")],
        openings: ("A visitor in a hard hat and vest posed as a water inspector, stayed fifteen minutes in {V}'s home, and $1,800 and a gold watch went missing. The watch was pawned under {D}'s ID.", "{D} was delivering parcels in another town that morning. A scanner shows eleven stops, and a friend asked {DL} to pawn the watch."),
        closings: ("A van, a watch pawned under {D}'s ID and thumbprint, and a photo array pick. {D.He} had a photo of a hard hat and vest on {D.his} phone.", "A courier scanner places {D} in another town all morning, and someone arrested a year later confessed to the same water-inspector scheme and returned the cash envelope."),
        timeline: [(0, "9:28 a.m.: the van stops at {V}'s house."), (0, "9:47 a.m.: the van leaves."), (0, "Afternoon: {V} finds the drawer emptied."), (2, "{DL} pawns the watch.")],
        identified: "A neighbor's camera and a pawn slip.",
        notDone: ["The photo array was not shown by an independent administrator.", "The coworker who owns the van was never questioned."],
        aggravating: ["The victim was very old", "The defendant took advantage of a position of trust"],
        mood: .wantsConviction,
        impact: "\"That watch was my late wife's gift to me. I would give up the cash just to have it back.\"",
        doctrines: ["eyewitnessID", "burdenOfProof"],
        genders: ["D": .male, "V": .male])

    static let phoneOnTheFloorV1 = SmallCases.make(
        key: "story.phoneOnTheFloor",
        category: .violent,
        headlines: ["Smartwatch Alert Sends Deputies to Driveway After Argument in Car", "Neighbor's Camera Records Slap Through Windshield"],
        law: "assaultFemale",
        threshold: 6,
        spec: "Assaulted {V}, a female, by striking {V.him} in the face with {D.his} hand, {D} being a male person at least 18 years of age.",
        ages: 22...45,
        victim: true,
        summary: "At about 11:50 p.m. on {DATE}, {D} drove {V}, {V.his} partner of three years, home from a wedding. They argued in the driveway, parked with the engine off. {V} raised a phone to call a friend. {DL} took the phone, and {V}'s smartwatch recorded a hard-impact alert and sent a text to {V}'s sister. A neighbor's camera across the street shows a hand strike {V}'s face through the windshield. {DL} says {V} was grabbing {D.his} arm and {D.he} only pushed it away.",
        state: [E(.video, 3, "Neighbor's Camera", "Through the windshield, an arm swings and {V}'s head jerks sideways; the passenger door then opens."), E(.digital, 2, "Smartwatch Alert", "A fall and impact alert at 11:54 p.m., and an automatic text to {V}'s sister."), E(.document, 2, "Urgent Care Note", "A swollen cheek, a split lip, and a bruise.")],
        defense: [E(.statement, 2, "Wedding Guest", "A guest says {V} had been shouting and grabbing {D}'s arm at the reception.")],
        role: "Responding deputy",
        exam: [.direct("What was {V}'s condition when you arrived?", "\"A swollen cheek, a split lip, and a bruise. {V} was shaken and sitting on the porch step.\""), .direct("How did deputies get called?", "\"{V}'s smartwatch recorded a hard-impact alert at 11:54 p.m. and sent a text to a relative. The relative called us.\""), .direct("What did the neighbor's camera show?", "\"Through the windshield, an arm swinging and {V}'s head jerking sideways. The passenger door then opens.\""), .direct("What did {D} tell you?", "\"That {V} had been grabbing {D}'s arm and that {DL} only pushed it away. {DL} said it was a heated argument.\""), .direct("What had happened earlier that night?", "\"They were at a wedding. A guest says {V} was shouting and grabbing {DL}'s arm at the reception.\""), .direct("What did the defendant text a friend later?", "\"'I smacked {V}, I'm done.' It was sent at 12:20 a.m., about half an hour after the incident.\""), .cross("{D} had a scratch on the forearm, didn't {D.he}?", "\"Yes. A scratch. It could be from the grab {DL} described.\""), .cross("{D} cooperated with you, didn't {D.he}?", "\"Yes. {DL} answered questions and showed us the car. I would call {DL} cooperative.\""), .cross("A second neighbor's video shows {V}'s hand grabbing first, doesn't it?", "\"I have seen it. It shows {DL}'s arm moving after {V}'s hand grabbed it.\""), .cross("{V} had been shouting at the reception, hadn't {V}?", "\"A guest says so. I cannot confirm it myself.\""), .cross("You did not see the strike yourself, did you?", "\"No. I arrived afterward. I rely on the camera and the smartwatch.\"")],
        defenseRole: "Wedding guest",
        defenseExam: [.direct("How do you know {D}?", "\"I was a guest at the wedding. I know {D} and {V} through friends, and I sat at their table.\""), .direct("What was {V} like at the reception?", "\"Upset, and pulling at {DF}'s sleeve. {V} was loud and argumentative with {DF} for much of the night.\""), .direct("How did the defendant react?", "\"Calmly at first. {DF} tried to quiet things and said they should leave. {DF} did not raise a hand.\""), .direct("Did you see the driveway?", "\"No. I left before they did. I only saw the reception.\""), .direct("What kind of person is the defendant?", "\"Even-tempered. I have never seen {DF} hit anyone. I was surprised to hear about this.\""), .direct("How was {V} that night?", "\"Drinking and moody. I tried to talk to {V}, but {V} was not listening.\""), .cross("You did not see what happened in the car, did you?", "\"No. I was not there. I only know what I saw at the reception.\""), .cross("You do not know if the defendant hit {V}, do you?", "\"No. I cannot say. I only know what I saw earlier.\""), .cross("You are friends with the defendant, aren't you?", "\"Yes. I am. I am describing only what I saw.\""), .cross("{V} may have been upset for good reasons, mightn't {V}?", "\"Possibly. I do not know what was bothering {V}.\""), .cross("You did not see {V}'s injuries, did you?", "\"No. I did not see them. I only heard about them afterward.\"")],
        theory: ("{D} slapped {V} in a parked car and the video shows it.", "An arm pushed away in a heated argument."),
        allocution: "\"I pushed {V}'s hand away in the driveway because I wanted us to calm down before anyone made a call. It looks worse than it was, but I lost my temper, and I'm sorry. After three years together, I never wanted to hurt {V}. I'll get help.\"",
        truths: ("A text {DL} sent a friend at 12:20 a.m. read, \"I smacked {V.him}, I'm done.\"", "The video angle, a second neighbor showed, caught {D}'s arm moving only after {V}'s hand grabbed it."),
        defendant: [.direct("Did you strike {V}?", "\"I pushed {V}'s hand away. It looks worse than it was. I did not mean to hit {V}'s face.\""), .direct("Why did you take the phone?", "\"To stop the fight. {V} was about to call someone, and I wanted us to calm down. I should have let {V} call.\""), .direct("What was {V} doing before you pushed?", "\"Grabbing my arm. {V} was pulling hard, and I was driving. I pushed {V}'s hand away.\""), .direct("Why did you text a friend that you smacked {V}?", "\"I was upset. I used the wrong words. I did not mean it as a confession.\""), .direct("What had happened at the wedding?", "\"{V} had been drinking and arguing. {V} grabbed my sleeve, and we left early. I did not want to cause a scene.\""), .direct("What would you say to {V}?", "\"That I am sorry. I did not mean to hurt you. I wish I had stopped the car.\""), .cross("The video shows a swing, doesn't it?", "\"It does. I know how it looks. It was a push, not a slap.\""), .cross("{V} had a swollen cheek and a split lip, didn't {V}?", "\"Yes. I saw it. I am sorry.\""), .cross("You took {V}'s phone, didn't you?", "\"Yes. I did. It was wrong.\""), .cross("You texted that you were done, didn't you?", "\"I did. I was upset, and I meant the relationship.\""), .cross("You could have stopped the argument by leaving the car, couldn't you?", "\"I could have. I did not, and I regret it.\"")],
        openings: ("After a wedding, {D} drove {V}, a partner of three years, home. In the driveway, a neighbor's camera shows an arm strike {V}'s face through the windshield, and a smartwatch sent an automatic alert.", "{V} was grabbing {D}'s arm during a heated argument in a parked car, and {DL} pushed it away. A push away is not a slap."),
        closings: ("The camera shows the strike, the watch recorded the impact, and {D} texted a friend 'I smacked {V}.' A swollen cheek and a split lip are the result.", "A second neighbor's video shows {D}'s arm moving only after {V}'s hand grabbed it. A push in a heated argument is not an assault."),
        timeline: [(0, "Night: the wedding reception ends."), (0, "11:50 p.m.: the argument in the driveway."), (0, "11:54 p.m.: the smartwatch alert."), (0, "12:05 a.m.: deputies arrive.")],
        identified: "A neighbor's camera and a smartwatch alert.",
        mitigating: ["No prior criminal record", "Has completed an intake for an abuser treatment program"],
        mood: .wantsConviction,
        impact: "\"My cheek healed, but I still don't like sitting in a parked car with the engine off. That night I'd just come home from a wedding with someone I trusted. I still think about that driveway when I turn out the light. I want to feel safe again.\"",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

    static let receiptCheckV1 = SmallCases.make(
        key: "story.receiptCheck",
        category: .property,
        headlines: ["Shopper Leaves Electronics Store With Laptop After Frozen Checkout", "Frozen Screen, No Receipt: Customer Stopped at Door"],
        law: "felonyLarceny",
        threshold: 8,
        spec: "Took and carried away a laptop computer and monitor valued at $1,240, the property of Pinecrest Electronics, without paying for them, on {DATE}.",
        ages: 24...45,
        victim: false,
        summary: "At about 4:55 p.m. on {DATE}, {D} used a self-checkout lane at Pinecrest Electronics to buy a laptop and monitor. The screen froze on \"Processing\" after the card was inserted. {DL}, who had a flight to catch, took the items and walked out. A loss prevention associate stopped {D.him} in the lot. {D.He} showed a banking app with a pending charge. Store records show no completed sale. {DL} says {D.he} was told by the screen to take the items.",
        state: [E(.video, 3, "Self-Checkout Camera", "{D} inserts a card, waits, then loads the laptop and monitor into a cart and leaves."), E(.document, 3, "Register Log", "The sale was suspended at 4:56 p.m. and never completed; no receipt printed."), E(.statement, 2, "Loss Prevention", "The associate says {D} did not look back at the screen or ask for help.")],
        defense: [E(.document, 3, "Bank Hold", "A pending authorization for $1,276.40 at the store posted at 4:56 p.m."), E(.statement, 2, "Attendant", "The self-checkout attendant says the lane froze three times that afternoon.")],
        role: "Loss prevention associate",
        exam: [.direct("What is your job at Pinecrest Electronics?", "\"I am a loss prevention associate. I watch the floor and the cameras, and I stop customers who leave without completing a purchase.\""), .direct("What did you see at about 4:55 p.m. on {DATE}?", "\"{D} used a self-checkout lane to buy a laptop and a monitor. {D.He} inserted a card, waited, and then loaded both items into a cart and walked out.\""), .direct("What did the register log show?", "\"The sale was suspended at 4:56 p.m. and never completed. No receipt was printed, and no payment was recorded as final.\""), .direct("What did you do when {D} reached the lot?", "\"I stopped {D.him} outside and asked to see a receipt. {D.He} said {D.he} had paid and showed me a banking app with a pending charge.\""), .direct("What was the amount of the electronics?", "\"About $1,240 for the laptop and the monitor. The bank hold was $1,276.40, which would include tax.\""), .direct("Did the defendant look at the screen before leaving?", "\"I did not see {DL} look back at the screen or ask for help. {DL} appeared to be in a hurry.\""), .cross("The lane did freeze that afternoon, didn't it?", "\"Yes. The attendant said it froze three times that afternoon. I understand that is part of the problem.\""), .cross("{D} showed you a pending charge for $1,276.40, didn't {D.he}?", "\"Yes. It posted at 4:56 p.m. It was a pending authorization, not a completed sale.\""), .cross("The vendor's log showed a completed sale at 5:38 p.m., didn't it?", "\"Later, yes. The sale posted while we were questioning {DL}. I understand that matters.\""), .cross("{D} did not run, did {D.he}?", "\"No. {D.He} walked to the lot with the cart. {D.He} stopped when I called out.\""), .cross("{D} had a flight to catch, didn't {D.he}?", "\"Yes. {D.He} said so right away. {D.He} was nervous about the time.\"")],
        defenseRole: "Self-checkout attendant",
        defenseExam: [.direct("What is your job at the store?", "\"I am the self-checkout attendant. I help customers at the lanes, clear errors, and call a manager when a lane fails.\""), .direct("Was that lane working that afternoon?", "\"No. It froze three times that afternoon. I reported it to the store manager and asked for a technician.\""), .direct("What did you tell customers about the frozen lane?", "\"To wait for a receipt and not to leave if the screen froze. I did not have time to tell every customer.\""), .direct("Did you tell {D} to wait?", "\"I was helping another customer. I did not speak with {D} before {D.he} left.\""), .direct("What does the screen usually show when a sale fails?", "\"An error message and a request for help. In this case, the lane froze on a processing screen with no message.\""), .direct("What did the vendor say about the problem?", "\"That the lane held a completed sale for forty minutes before it posted. It was a known issue they were looking at.\""), .cross("You did not see the defendant leave, did you?", "\"No. I saw {DF} at the lane, but I was busy with another customer when {DF} left.\""), .cross("You cannot say what the defendant saw on the screen, can you?", "\"No. I can only say what the lane did for other customers. It froze on the processing screen.\""), .cross("Customers are supposed to wait for a receipt, aren't they?", "\"Yes. That is store policy. A receipt is the proof that the sale is done.\""), .cross("The lane froze three times, but not every customer left, did they?", "\"Right. Most waited or asked for help. {D.He} did not.\""), .cross("You work for the store, don't you?", "\"Yes. I am telling you what I know of the lane and the afternoon.\"")],
        theory: ("{D} walked out with $1,240 in electronics and no completed sale.", "A frozen lane, a pending charge, and a traveler in a hurry."),
        allocution: "\"The screen froze on Processing after I put in my card, and then it went blank and told me to remove it. No receipt came out, and I assumed it would print later. I had a flight in two hours. I should have waited. I'm sorry, and I'll pay for everything.\"",
        truths: ("The bank later confirmed the hold dropped off two days later and the sale never posted, and {DL}'s card reader said \"not complete\" when {D.he} left.", "The vendor's log showed the frozen lane held a completed sale for forty minutes; it posted at 5:38 p.m., while {DL} was being questioned."),
        defendant: [.direct("Why did you leave the store with the items?", "\"The screen froze on 'Processing' after I inserted my card. It said to take the items, and I thought the payment had gone through.\""), .direct("What did the screen say?", "\"It said Processing, then it went blank, and then a message said to remove my items. I did what it said.\""), .direct("Why did you not wait for a receipt?", "\"None came out. I assumed it would print later. I had a flight in two hours and I was watching the clock.\""), .direct("Did you ask for help?", "\"No. The attendant was busy with another customer. I did not want to miss my flight, and I thought it was done.\""), .direct("What did you do when the associate stopped you?", "\"I showed the banking app. I told the associate I had paid. I offered to go back and check the sale.\""), .direct("What would you say to the store?", "\"That I am sorry for the misunderstanding. I intended to pay and thought I had. I am glad the sale finally posted.\""), .cross("You walked out without a receipt, didn't you?", "\"Yes. I did. I know I should have waited, but the lane showed me nothing else.\""), .cross("You saw the processing screen go blank, didn't you?", "\"Yes. It said processing and then went blank. I took that as done.\""), .cross("You had a flight in two hours, didn't you?", "\"Yes. I was in a hurry. That was why I did not wait.\""), .cross("The sale was never completed when you left, was it?", "\"I learned later it was not. The bank hold shows the payment was pending.\""), .cross("You did not look at the screen again before you left, did you?", "\"No. I loaded the cart and left. I should have looked.\"")],
        openings: ("{D} tried to buy a laptop and monitor at a self-checkout lane. The screen froze, no receipt printed, and {D.he} walked out with $1,240 in electronics before the sale was completed.", "{D} had a flight to catch and was told by a frozen screen to take the items. A pending charge and a lane that froze all afternoon explain it."),
        closings: ("The log shows a suspended sale, no receipt, and a customer who did not look back at the screen. {D} walked out with the electronics before any payment was complete.", "The bank hold posted at 4:56 and the sale finally posted at 5:38 while {D} was being questioned. {D.He} paid, and the system failed."),
        timeline: [(0, "4:55 p.m.: {D} starts the checkout."), (0, "4:56 p.m.: the lane freezes; the sale is suspended."), (0, "5:05 p.m.: {D} is stopped in the lot."), (0, "5:38 p.m.: the sale posts.")],
        identified: "Store cameras and a loss prevention associate.",
        notDone: ["No one asked the register vendor for the full log before charging.", "The attendant was never interviewed."],
        mitigating: ["No prior criminal record", "The defendant has been gainfully employed"],
        mood: .divided,
        doctrines: ["burdenOfProof", "searchSeizure", "lesserIncluded"])

    static let brakeLinesV1 = SmallCases.make(
        key: "story.brakeLines",
        category: .violent,
        headlines: ["Loose Lug Nuts Blamed After Contractor's Wheel Flies Off on Highway", "Partner Charged After Front Wheel Leaves Work Truck at 60 mph"],
        law: "attemptedMurder1",
        threshold: 9,
        spec: "With malice, premeditation, and deliberation, attempted to kill {V} by loosening the lug nuts on the front wheel of {V.his} truck.",
        ages: 35...60,
        victim: true,
        summary: "{D} and {V} co-owned a roofing company. They were fighting over a buyout, and a $1 million key-person life insurance policy paid the company if either partner died. On {DATE}, the left front wheel of {V}'s truck came off on a highway ramp, the truck struck a guardrail, and {V} was treated for broken ribs. An engineer found all five lug nuts finger-loose with clean threads and no stripping. A shop camera shows {DL} alone near the truck the night before. {DL} says a tire shop rotated the tires that week and likely skipped the torque check.",
        state: [E(.forensic, 3, "Engineer's Report", "All five lug nuts were finger-loose with clean threads, which points to loosening by hand and not by vibration."), E(.video, 3, "Shop Camera", "{D} alone beside {V}'s truck at 9:40 p.m. the night before, bending near the left front wheel for about two minutes."), E(.document, 3, "Insurance Policy", "A $1 million key-person policy payable to the company if {V} died; {D} had asked the agent about the payout.")],
        defense: [E(.document, 2, "Tire Shop Invoice", "An invoice for a tire rotation on {V}'s truck three days before the crash."), E(.statement, 2, "Mechanic", "The tire shop mechanic says torque checks are done by hand when the shop is busy."), E(.statement, 1, "Shop Routine", "{D} says {D.he} often leaned on the trucks to check tire wear.")],
        role: "Forensic engineer",
        exam: [.direct("What did you find when you examined the left front wheel of {V}'s truck?", "\"All five lug nuts were finger-loose, with clean threads and no stripping. The wheel had come off on a highway ramp.\""), .direct("Why does the condition of the threads matter?", "\"Vibration leaves wear marks and stripped threads. These threads were clean and undamaged, which points to loosening by hand and not by vibration.\""), .direct("What does a properly torqued wheel look like after a failure like this?", "\"Usually the nuts are still tight or partly backed out with marks of movement. Here the nuts were loose with no such marks.\""), .direct("What did you learn about the tire shop's work three days earlier?", "\"An invoice shows a tire rotation on {V}'s truck. A shop mechanic said torque checks are done by hand at the end.\""), .direct("What did the shop camera show the night before?", "\"{D} alone beside {V}'s truck at 9:40 p.m., bending near the left front wheel for about two minutes.\""), .direct("What did you learn about the insurance policy?", "\"A $1 million key-person policy payable to the company if either partner died. {DL} had asked the agent about the payout.\""), .cross("A tire shop could leave lug nuts loose, couldn't it?", "\"Yes. But it would be unusual for all five to be loose. A careless shop might leave one or two.\""), .cross("You cannot say who loosened them, can you?", "\"No. I can say how they were loosened, by hand and not by vibration. I cannot say who did it.\""), .cross("{D} was near the truck at night, but that is not unusual for a co-owner, is it?", "\"Not by itself. They share the yard. It was the two minutes near the left front wheel that drew attention.\""), .cross("The tire rotation was three days before the crash, wasn't it?", "\"Yes. That is on the invoice. The crash came after three days of driving.\""), .cross("A former employee later admitted loosening the nuts, didn't that person?", "\"Someone did say so. I know about that statement. I have not independently verified it.\"")],
        defenseRole: "Tire shop mechanic",
        defenseExam: [.direct("What is your work?", "\"I am a mechanic at a tire shop. I mount tires, rotate them, and torque the lug nuts. I rotated the tires on {V}'s truck three days before the crash.\""), .direct("Did you rotate those tires?", "\"Yes, three days before the crash. It was a standard rotation, and I put the wheels back on and checked each nut.\""), .direct("How do you torque the nuts?", "\"With a torque wrench, in a star pattern. I do it at the end of each job. It is the last step before the truck goes out.\""), .direct("Did you torque the nuts on {V}'s truck?", "\"I think so, but it was a busy day. I do not remember each wheel. I did not skip it on purpose.\""), .direct("Would all five nuts come off from vibration alone?", "\"It would be very unusual. In my experience, loose nuts back off a little at a time and leave marks.\""), .direct("What would you say about the condition of the nuts?", "\"If all five were finger-loose with clean threads, I do not think my shop left them that way. I would have noticed.\""), .cross("You do not remember torquing each wheel, do you?", "\"No. I did many that day. I trust my routine, but I cannot recall each one.\""), .cross("A rushed shop can miss a torque check, can't it?", "\"It can, yes. I am not saying we did, but I cannot rule it out.\""), .cross("You do not know who was near the truck the night before, do you?", "\"No. I was home. I only know what I did three days earlier.\""), .cross("You want to protect your shop's reputation, don't you?", "\"Yes. I do. I am also trying to tell you what I know.\""), .cross("You cannot say all five nuts were tight when you finished, can you?", "\"I believe they were. I cannot prove it.\"")],
        theory: ("{D} loosened a partner's wheel to collect on a policy.", "A tire shop's rushed job and a partner who happened to be nearby."),
        allocution: "\"I did not do this. I was checking the tire wear that night because we were thinking about new tires, and I would never touch those lug nuts. I'm sorry for what {V} went through on that ramp. A tire shop rotated those wheels that week, and I hope the truth is looked at.\"",
        truths: ("A lug wrench with {V}'s truck's wheel dust was found in {DL}'s trunk.", "A former employee later admitted loosening the nuts to get back at {V}."),
        defendant: [.direct("Were you near {V}'s truck the night before the crash?", "\"Yes. I was checking the tire wear because we were thinking about new tires for the fleet. I was beside the truck for a couple of minutes.\""), .direct("Did you loosen the lug nuts?", "\"No. I did not touch the nuts. I would never do that to {V}, even in the middle of a fight over the buyout.\""), .direct("Why did you ask the insurance agent about the payout?", "\"It was routine. We were reviewing our policies, and I asked what the coverage was. I did not mean anything by it.\""), .direct("Why were you alone at night in the yard?", "\"I work late most nights. I like to walk through the yard after the crews leave and make sure everything is locked.\""), .direct("What was the dispute with {V}?", "\"A buyout. We disagreed about the price, and it got heated. But we had been partners for years, and I did not want {V} hurt.\""), .direct("How did you feel when you heard about the crash?", "\"Sick. I rushed to the hospital to see {V}. I felt terrible, and I knew people would think I had something to do with it.\""), .cross("A lug wrench with {V}'s truck's wheel dust was in your trunk, wasn't it?", "\"Yes. I keep one there. The dust is from changing a tire earlier that month.\""), .cross("You bent near the left front wheel for two minutes, didn't you?", "\"Yes. I was looking at the tire. I did not loosen the nuts.\""), .cross("You had asked about the payout of a $1 million policy, hadn't you?", "\"Yes. It was routine. I know how it looks.\""), .cross("You were fighting with {V} over a buyout, weren't you?", "\"Yes. It was a hard fight. It did not mean I would hurt anyone.\""), .cross("You were the only one seen near the truck, weren't you?", "\"That is what the camera shows. I do not know who else might have been there.\"")],
        openings: ("{D} and {V} co-owned a roofing company and were fighting over a buyout, with a $1 million policy payable if either died. {V}'s wheel came off on a highway ramp, and every lug nut was finger-loose.", "A tire shop rushed a rotation, and a partner happened to be near the truck. A shop's mistake is not an attempted murder."),
        closings: ("Five loose nuts with clean threads, a camera showing {D} alone at the left front wheel, and a $1 million policy {DL} had asked about.", "The mechanic cannot say every nut was torqued, and a former employee admitted loosening the nuts. {D} did not touch the wheel."),
        timeline: [(-3, "The tire shop rotates the tires on {V}'s truck."), (-1, "9:40 p.m.: {D} is seen beside the truck."), (0, "Morning: the wheel comes off on the ramp."), (1, "An engineer examines the wheel.")],
        identified: "The shop camera and the engineer's report.",
        notDone: ["Former employees with yard access were not interviewed.", "The tire shop's torque records were not subpoenaed."],
        mitigating: ["No prior criminal record"],
        mood: .wantsConviction,
        impact: "\"I drive my kids to school on that ramp. I still hold the wheel too tight, and I flinch every time a truck passes close to the rail. I spent weeks healing broken ribs, and I couldn't go to work. I'd like to feel safe on the road again.\"",
        doctrines: ["burdenOfProof", "expertTestimony"],
        genders: ["V": .male])

    static let zeroTurnMowerV1 = SmallCases.make(
        key: "story.zeroTurnMower",
        category: .property,
        headlines: ["GPS Tracker Leads Excavation Contractor to Stolen Mini Excavator", "Stolen Excavator and Trailer Found Behind Man's Rented Lot"],
        law: "possStolen",
        threshold: 8,
        spec: "Possessed a mini excavator and a 14-foot equipment trailer, together valued at $31,500, belonging to {V}, knowing or having reasonable grounds to believe they had been stolen.",
        ages: 25...58,
        victim: true,
        summary: "On the weekend of {DATE}, someone cut the padlock on {V}'s equipment yard and drove off with a mini excavator on a trailer. A hidden GPS tracker on the machine pinged an address eleven days later, a rented lot with a metal shed where {D} stored equipment. Deputies found the excavator with its yellow paint rolled over in gray and the serial plate removed. {DL} says {D.he} took the machine in exchange for work done for a customer and never saw the paperwork.",
        state: [E(.digital, 3, "GPS Tracker", "A hidden tracker on the excavator pinged the rented lot where {D} stored equipment for eight days.", .search), E(.physical, 3, "Repainted Machine", "Gray paint over yellow, serial plate removed; a hidden frame stamp matches {V}'s purchase records.", .search), E(.document, 3, "Value Records", "Excavator $24,000; trailer $7,500.")],
        defense: [E(.statement, 2, "Payment in Kind", "{DL} says a customer handed over the machine to settle a $6,000 trenching bill."), E(.document, 1, "Work Invoice", "{DL}'s invoice for $6,000 in trenching work, marked unpaid.")],
        role: "Equipment yard owner",
        exam: [.direct("What do you do for a living?", "\"I own an equipment yard. I rent out mini excavators, skid steers and trailers to contractors. I keep the machines behind a fence with a padlock.\""), .direct("What was taken over the weekend of {DATE}?", "\"A mini excavator on a trailer. Someone cut the padlock on the gate and drove off with the machine and trailer.\""), .direct("How much were the machine and trailer worth?", "\"The excavator is worth $24,000 and the trailer $7,500. It was a major loss for my business.\""), .direct("How was the machine found?", "\"A hidden GPS tracker pinged an address eleven days later. It was a rented lot with a metal shed, and the machine was inside.\""), .direct("How do you know it is yours?", "\"The hidden frame stamp and a dent in the bucket. The serial plate was removed and the yellow paint rolled over in gray, but the stamp is still there.\""), .direct("Did you ever have dealings with {D}?", "\"Not before this. I had never heard of {D}. I do not know how {D.he} learned about my machine.\""), .cross("You did not know the defendant before, did you?", "\"No. I had not met {D.him}. I only know what I saw at the lot.\""), .cross("{D} did not have a bill of sale, did {D.he}?", "\"No. {D.He} said it was a handshake deal. I saw no paperwork, and I did not see a title.\""), .cross("{D} says a customer paid with the machine, doesn't {D.he}?", "\"Yes. {DL} says a customer handed it over to settle a $6,000 trenching bill. I do not know that customer.\""), .cross("The paint job could have been done by anyone, couldn't it?", "\"Yes. I do not know who painted it. The paint was fresh.\""), .cross("{D} did not hide the machine from deputies, did {D.he}?", "\"It was in a metal shed on a rented lot. It was not far from the road, but it was not in plain sight.\"")],
        defenseRole: "{DL}'s helper",
        defenseExam: [.direct("How do you know {D}?", "\"I help {D} with jobs. I was at {D.his} lot the day the machine arrived.\""), .direct("Did you see how the machine arrived?", "\"Someone dropped it off and said it was payment for a trenching job. I did not hear the whole conversation.\""), .direct("What did the defendant say?", "\"That it was a good deal and that the customer owed {DF} for work. {DF} seemed pleased.\""), .direct("Did you see money or paperwork?", "\"No. I saw them shake hands. I did not see any papers, and I did not see money.\""), .direct("What kind of boss is the defendant?", "\"Fair and hard-working. {D.He} pays on time and does not cut corners.\""), .direct("What did the defendant do with the machine?", "\"Painted it and stored it in the shed. {DF} did not try to hide it from me or from anyone else.\""), .cross("You did not see a title or a bill of sale, did you?", "\"No. I did not. I never asked for one.\""), .cross("You do not know the customer's name, do you?", "\"No. I only know it was a customer. I did not catch a name.\""), .cross("You work for the defendant, don't you?", "\"I want to help, but I am telling you only what I saw.\""), .cross("You did not see the serial plate, did you?", "\"No. I never looked for one. I did not know it was missing.\""), .cross("You cannot say where the machine came from, can you?", "\"No. I only know it arrived on a trailer.\"")],
        theory: ("{D} kept a stolen machine and painted it to hide where it came from.", "A machine taken in payment for work, without paperwork."),
        allocution: "\"A customer paid me with that machine for six thousand dollars of trenching I was owed, and I never suspected anything. I painted it to match my fleet. The tracker was gone when it arrived. I took it without asking enough questions, and I'm sorry to {V}.\"",
        truths: ("The customer who supposedly paid {DL} said {DL} offered to buy the machine for cash and asked no questions.", "The customer was later arrested for stealing equipment and admitted telling {DL} the machine was payment."),
        defendant: [.direct("How did you get the machine?", "\"A customer paid me with it. The customer owed me $6,000 for trenching work, and offered the machine in settlement.\""), .direct("Why did you paint it?", "\"To match my fleet. I paint my machines gray, and I painted this one when I got it.\""), .direct("What about the serial plate?", "\"It was gone when the machine arrived. I did not remove it, and I did not think about it.\""), .direct("Did you have paperwork?", "\"No. We shook hands. I know that was a mistake, and I should have asked for a title or a bill of sale.\""), .direct("Why did you keep the machine in a shed on a rented lot?", "\"It is where I store my equipment. I rented the lot for that purpose, and the machine was one of several.\""), .direct("What would you say to {V}?", "\"That I am sorry. I did not know the machine was stolen, and I will do what I can to return it.\""), .cross("The customer you named says you offered to buy it for cash, doesn't the customer?", "\"That is not how I remember it. The customer said it was payment. I did not ask questions.\""), .cross("You never saw the paperwork, did you?", "\"No. I should have. I trusted the customer.\""), .cross("You painted a machine that had no serial plate, didn't you?", "\"Yes. I did. I know how that looks.\""), .cross("You billed $6,000 for trenching work, didn't you?", "\"Yes. The invoice is marked unpaid. I did the work, and I was owed.\""), .cross("A $24,000 machine for a $6,000 debt is a good trade, isn't it?", "\"It was lopsided, and I should have asked why.\"")],
        openings: ("Someone cut the padlock on {V}'s equipment yard and drove off with a mini excavator. A hidden tracker led deputies to {D}'s rented lot, where the machine had been repainted and its serial plate removed.", "{D} took the machine as payment for unpaid trenching work and never saw the paperwork. A handshake deal is not a theft."),
        closings: ("A tracker, fresh gray paint, a missing serial plate, and no bill of sale. {D} kept a $24,000 machine that was not {DL}'s.", "The customer was later arrested for stealing equipment and admitted telling {D} the machine was payment. {D.He} acted on a debt and a handshake."),
        timeline: [(-11, "Weekend: the machine is taken from {V}'s yard."), (-3, "{DL} paints the machine gray."), (0, "The tracker pings the rented lot."), (0, "Deputies search the shed.")],
        identified: "A GPS tracker.",
        notDone: ["The customer who allegedly paid {DL} was not interviewed.", "No one checked who else had keys to the rented lot."],
        aggravating: ["Property was worth more than $10,000"],
        mitigating: ["No prior criminal record", "Was not the thief"],
        mood: .divided,
        impact: "\"I built that business one trench at a time. When that excavator was gone I lost two jobs, and I had to turn down work I'd already promised. I felt sick standing in an empty yard. Those machines are how I feed my family, and I want them treated with respect.\"",
        doctrines: ["burdenOfProof"])

    static let afterThePartyV1 = SmallCases.make(
        key: "story.afterTheParty",
        category: .violent,
        headlines: ["Rape Charge After Lake House Party Weekend", "A Doorbell Camera, a Blood Alcohol Level, and a Disputed Memory"],
        law: "rape2",
        threshold: 9,
        spec: "Engaged in vaginal intercourse with {V}, who was physically helpless and mentally incapacitated by alcohol, when {D} knew or should reasonably have known of that condition.",
        ages: 20...26,
        victim: true,
        summary: "On {DATE}, {V} and {D}, both in their early twenties, were at a rented lake house party with about thirty people. Guests say {V} drank heavily over several hours. At about 12:40 a.m., {DL} took {V} upstairs to a bedroom. {V} woke the next morning with no memory of the night, was driven to a hospital by a friend, and underwent an exam. {DL} says {V} was drunk but talking, laughing, and walked up the stairs unaided, and that {V} said yes.",
        state: [E(.forensic, 3, "Toxicology", "{V}'s blood alcohol was estimated at 0.22 to 0.28 at the time of the encounter."), E(.video, 3, "Porch Camera", "At 12:38 a.m. {V} stumbles at the porch steps and {D} half-carries {V} toward the stairs."), E(.digital, 3, "Group Chat", "A guest's message at 1:10 a.m.: \"{V} was out cold on the couch an hour ago, where did {V.he} go?\"")],
        defense: [E(.statement, 2, "{DL}'s Roommate", "The roommate says {V} walked up the stairs and kissed {D} on the landing."), E(.digital, 2, "Morning Text", "A text from {V} to {D} at 9 a.m.: \"Did we hang out last night? I don't remember how I got to the bed.\"")],
        role: "Forensic toxicologist",
        exam: [.direct("What is your work?", "\"I am a forensic toxicologist. I analyze blood and urine samples to estimate alcohol and drug levels, and I testify about what they mean.\""), .direct("What was {V}'s estimated blood alcohol level at the time of the encounter?", "\"Between 0.22 and 0.28. That is an estimate based on the sample taken later and the time that had passed.\""), .direct("What does that level mean for a person's awareness?", "\"At that range, many people are in or near a blackout, with impaired judgment and memory. Some can still walk and talk.\""), .direct("What can a blood alcohol level tell you about a person's capacity?", "\"It gives a range, not a certainty. It tells us that impairment was significant, but it cannot say what a person understood at a particular minute.\""), .direct("What does the research say about blackouts?", "\"A person can appear awake and talk, yet not form memories. Others around them may not know the person will not remember.\""), .direct("What did you review in this case?", "\"The lab results, the timeline of drinks from guests, and the porch camera. I did not interview anyone.\""), .cross("A person at that level can talk and walk, can't they?", "\"Some can, yes. Many people at that level still move and speak. I would not say all are incapacitated.\""), .cross("You cannot say what {V} could do at 12:40, can you?", "\"No. I can only give a range. I cannot say what {V} understood or decided at that minute.\""), .cross("A person can be in a blackout and still be conscious, can't they?", "\"Yes. In a blackout, a person may act normally but not remember. That does not tell us what they understood at the time.\""), .cross("The estimate has a wide range, doesn't it?", "\"Yes. 0.22 to 0.28 is a wide range. It depends on assumptions about drinking times and body weight.\""), .cross("You did not see {V} that night, did you?", "\"No. I only know the sample. I have no personal knowledge of what happened.\"")],
        defenseRole: "Roommate of {DL}",
        defenseExam: [.direct("How do you know {D}?", "\"I am {D}'s roommate. We share an apartment, and I was at the lake house party that night.\""), .direct("What did you see at the stairs?", "\"{V} walked up with {DF} and was laughing. They seemed comfortable, and {V} was talking.\""), .direct("Did you see {V} kiss the defendant?", "\"Yes. On the landing. {V} kissed {DF}. It looked mutual to me.\""), .direct("Did you see {V} fall?", "\"{V} stumbled once. {DF} caught {V}. It was a small stumble, not a collapse.\""), .direct("How was {V} that night?", "\"Drunk, but talking and laughing. {V} was in a good mood. I did not see anything that worried me.\""), .direct("What kind of person is the defendant?", "\"Respectful. {D.He} has always been considerate to others. I was shocked when I heard about this.\""), .cross("You did not see what happened upstairs, did you?", "\"No. I stayed downstairs. I only saw the stairs.\""), .cross("You were drinking too, weren't you?", "\"Yes. I had a few drinks. I was not drunk, but I was not perfectly sober either.\""), .cross("You cannot say how clearly {V} understood things, can you?", "\"No. I can only say what I saw. {V} seemed willing and aware.\""), .cross("You are the defendant's roommate and friend, aren't you?", "\"Yes. I am, and I am keeping to what I personally saw.\""), .cross("A guest says {V} was out cold earlier, doesn't a guest?", "\"I heard that. I did not see it. I only saw {V} on the stairs.\"")],
        theory: ("{D} took an intoxicated {V} upstairs when {V} could not consent.", "A drunk but willing partner and a blackout memory."),
        allocution: "\"{V} said yes and kissed me on the landing, and I took that to mean we both wanted to go upstairs. I was drunk too, and I should not have trusted my own judgment that night. I'm sorry for the harm that has come to {V}. I'll never look at things that way again.\"",
        truths: ("A second guest later said {V} was not responding when {D} carried {V.him} upstairs.", "{V} later told a counselor fragments came back: {V.he} remembered asking {D} to stay."),
        defendant: [.direct("Did {V} agree to go upstairs with you?", "\"Yes. {V} said yes and kissed me on the landing. {V} was drunk, but talking and laughing.\""), .direct("How was {V} at the party?", "\"Drinking, social, and cheerful. {V} was dancing and talking with friends. {V} was unsteady at times, but I thought {V} was fine.\""), .direct("Why did you have your arm around {V} on the porch?", "\"{V} was unsteady on the porch steps. I helped {V} get up the stairs. {V} did not resist, and we were laughing.\""), .direct("What happened upstairs?", "\"We were together. {V} was awake and responsive. I thought it was what we both wanted.\""), .direct("Did {V} say anything the next morning?", "\"{V} texted to ask if we hung out and said {V} did not remember how {V} got to the bed. I told {V} the truth.\""), .direct("What would you say to {V}?", "\"That I am sorry if you did not remember or feel the same way. I believed you were willing, and I would never hurt you.\""), .cross("You knew {V} had been drinking heavily, didn't you?", "\"Yes. So had I. I thought {V} was drunk but able to decide.\""), .cross("A guest's message said {V} was out cold on the couch an hour earlier, didn't it?", "\"Yes. I saw the message later. I did not see {V} out cold. {V} was up and talking when I found {V}.\""), .cross("A second guest says {V} was not responding when you carried {V}, doesn't that guest?", "\"That is not what I remember. I helped {V} up the stairs, and {V} walked.\""), .cross("{V}'s blood alcohol was between 0.22 and 0.28, wasn't it?", "\"That is the toxicologist's estimate. Nobody told me any number that night.\""), .cross("You half-carried {V} toward the stairs, didn't you?", "\"I helped {V} walk. {V} was unsteady. I did not carry {V}.\"")],
        openings: ("At a lake house party, {V} drank heavily for hours. Around 12:40 a.m., a porch camera shows {V} stumbling and {D} half-carrying {V} upstairs. {V} woke with no memory and went to a hospital.", "{V} was drunk but talking, laughing, and walking, and {D} believed {V} was willing. A blackout is not the same as an inability to agree."),
        closings: ("A blood alcohol estimated at 0.22 to 0.28, a porch camera, and a guest message saying {V} was out cold an hour earlier. {V} could not consent.", "A blackout is not proof of incapacity. {V} walked, talked, laughed, and kissed {D} on the landing, and the morning text shows confusion and not complaint."),
        timeline: [(0, "Evening: the lake house party."), (0, "12:38 a.m.: the porch camera records {V} on the steps."), (0, "12:40 a.m.: {D} and {V} go upstairs."), (1, "{V} goes to the hospital.")],
        identified: "A porch camera and {V}'s report.",
        notDone: ["Not all guests in the porch video were interviewed.", "The second guest was never asked what {V} looked like on the couch."],
        mitigating: ["{DL} has no prior criminal record", "{DL} was also drinking"],
        mood: .divided,
        impact: "\"I left school for a semester after that night. I woke up with no memory of what happened and a friend driving me to a hospital. I don't trust my memory anymore, and I startle at parties. I'm working to get back to the person I was before.\"",
        doctrines: ["burdenOfProof", "lesserIncluded"],
        genders: ["D": .male, "V": .female])

    static let returnDeskV1 = SmallCases.make(
        key: "story.returnDesk",
        category: .property,
        headlines: ["Shopper Charged With Taking Power Drills From Shelf and Returning Them for Gift Card", "Copied Receipt Number Unravels Hardware Store Return"],
        law: "larcenyMerchant",
        threshold: 7,
        spec: "Took three cordless drills valued at $657 from the shelves of Ridgeway Hardware and, without paying for them, returned them at the service counter with a copied receipt to obtain a gift card for $657.",
        ages: 24...48,
        victim: false,
        summary: "On {DATE} at about 1:20 p.m., {D} picked up three cordless drills from aisle nine at Ridgeway Hardware, carried them straight to the service counter, and handed over a printed receipt. The clerk issued a $657 gift card. Loss prevention noticed that the receipt number matched a purchase of one drill the month before. Store video shows {DL} taking the drills from the shelf. {DL} says {D.he} bought the drills as gifts last month and found the extra receipt in a drawer.",
        state: [E(.video, 3, "Aisle Camera", "{D} takes three drills from the shelf and goes straight to the service counter."), E(.document, 3, "Receipt Match", "The receipt number belongs to a single-drill sale from a different customer a month earlier."), E(.statement, 2, "Counter Clerk", "The clerk says {D} did not ask about the three drills' prices and took the gift card at once.")],
        defense: [E(.document, 2, "Bank Statement", "{D}'s statement shows one drill purchased at Ridgeway a month earlier."), E(.statement, 2, "Drawer Receipt", "{DL} says the extra receipts were saved from earlier gifts.")],
        role: "Loss prevention officer",
        exam: [.direct("What is your job at Ridgeway Hardware?", "\"I am a loss prevention officer. I watch the floor and the cameras, review returns, and look into transactions that do not look right.\""), .direct("What did you see {D} do at about 1:20 p.m. on {DATE}?", "\"{D} took three cordless drills off the shelf in aisle nine and walked straight to the service counter without stopping anywhere else.\""), .direct("What happened at the counter?", "\"{DL} handed over a printed receipt, and the clerk issued a $657 gift card. {DL} took the card and turned to leave.\""), .direct("What did you find about the receipt?", "\"The receipt number belonged to a single-drill sale to a different customer a month earlier. It was not for three drills.\""), .direct("What did the clerk tell you about the defendant?", "\"That {D.he} did not ask about the prices of the three drills and took the gift card at once. The clerk thought it was a quick return.\""), .direct("What did the defendant's bank statement show?", "\"One drill purchased at Ridgeway a month earlier. It was a single purchase, not three.\""), .cross("{D} did buy a drill at your store before, didn't {D.he}?", "\"Yes. The statement shows one drill. That is consistent with what {D.he} says about gifts.\""), .cross("{D} did not run when you stopped {D.him}, did {D.he}?", "\"No. {D.He} stayed at the counter. {D.He} was calm and answered questions.\""), .cross("{D} went straight to the counter, didn't {D.he}?", "\"Yes. {D.He} did not hide the drills or try to avoid the camera. It looked like an ordinary return.\""), .cross("The drills were returned without boxes, weren't they?", "\"Yes. {D.He} had no boxes. A clerk might have asked about that, and no one did.\""), .cross("You do not know where the defendant got the receipt, do you?", "\"I know it was from another customer's sale. I do not know how {D.he} came to have it.\"")],
        defenseRole: "Defendant's partner",
        defenseExam: [.direct("How are you connected to {D}?", "\"I am {D}'s partner. We live together, and I know {D.his} habits with receipts and purchases.\""), .direct("Did the defendant buy gifts last month?", "\"Yes. A drill for a relative's birthday. I was there when {D.he} wrapped it.\""), .direct("Where does the defendant keep receipts?", "\"In a kitchen drawer. {D.He} keeps every one. There is a drawer full of them.\""), .direct("Does the defendant often return items to stores?", "\"Hardly ever. {D.He} keeps what {D.he} buys, and a return is unusual enough that I would remember one.\""), .direct("How did the defendant react when this came up?", "\"Upset. {D.He} said it was a mistake with a receipt, and {D.he} was embarrassed.\""), .direct("What kind of person is the defendant?", "\"Honest. {D.He} is careful with money and would not cheat a store. I was shocked.\""), .cross("You do not know about three drills, do you?", "\"No. I only know about one. I cannot say what else {DF} bought.\""), .cross("You did not see the defendant take drills off the shelf, did you?", "\"No. I was at home, so all I have is {D.his} own account.\""), .cross("A drawer of receipts proves nothing about this one, does it?", "\"It shows {DF} keeps receipts. I cannot say where this receipt came from.\""), .cross("You are close to the defendant, aren't you?", "\"Yes. I am {D.his} partner. I am trying to be honest.\""), .cross("You did not see the receipt, did you?", "\"No. I never saw it. I only heard about it.\"")],
        theory: ("{D} took drills off a shelf and returned them with a copied receipt for a gift card.", "A shopper with old receipts and a simple mistake."),
        allocution: "\"I found that receipt in a drawer at home with other old ones, and I thought it was mine. I'd bought gifts and wanted to return extras, so I carried the drills straight to the service counter. I made a mistake and I'm sorry. I'll go back to the store and sort it out.\"",
        truths: ("A second phone in {DL}'s truck held a list of stores and receipt numbers copied from the trash.", "The receipt came from a trash can outside the store, and a clerk had misread {DL}'s original purchase."),
        defendant: [.direct("Whose receipt did you use?", "\"I thought it was mine. I found it in a drawer at home with other old receipts from gifts I bought.\""), .direct("Why did you take three drills to the counter?", "\"I had bought gifts and wanted to return the extras. I thought the receipt covered what I had bought.\""), .direct("Why did you pick up the drills from the shelf?", "\"I took them off the shelf to return them. I did not have the boxes. I threw the boxes away after wrapping the gifts.\""), .direct("Did you buy a drill at Ridgeway last month?", "\"Yes. One drill, as a gift. I kept the receipt and put it in a drawer. I thought I had more than one.\""), .direct("What did you do when loss prevention stopped you?", "\"I told the officer I thought it was my receipt. I did not argue, and I offered to give the gift card back.\""), .direct("What would you say to the store?", "\"That I am sorry. I made a mistake, and I did not mean to cheat anyone.\""), .cross("A second phone in your truck held a list of stores and receipt numbers, didn't it?", "\"Yes. I use the phone for tracking my purchases. I know how it looks.\""), .cross("The receipt belonged to another customer, didn't it?", "\"I know that now. I did not know it at the time.\""), .cross("You took three drills off the shelf and returned them, didn't you?", "\"Yes. I did. I thought I was returning my own.\""), .cross("You had no boxes, did you?", "\"No. I threw them away. I should have kept them.\""), .cross("You took the gift card at once, didn't you?", "\"Yes. It was offered, and I took it. I should have asked more.\"")],
        openings: ("{D} took three cordless drills off a shelf, carried them to the service counter, and handed over a receipt for a single-drill sale from a month earlier. The clerk issued a $657 gift card.", "{D} found an old receipt in a drawer and believed it covered gifts {DL} had bought. It was an honest mistake by a shopper who keeps every receipt, not a theft."),
        closings: ("The receipt belongs to someone else's one-drill sale, and {D} returned three drills with no boxes and took a gift card. The store was cheated.", "A drawer full of receipts proves nothing except that {D} saves them. {D.He} went straight to the counter and did not run."),
        timeline: [(-30, "{DL} buys one drill at the store."), (0, "1:20 p.m.: {D} takes three drills from the shelf."), (0, "1:25 p.m.: the counter issues a $657 gift card."), (1, "Loss prevention matches the receipt.")],
        identified: "The aisle camera and a receipt match.",
        notDone: ["The first drill's transaction was not pulled until the day after the arrest."],
        aggravating: ["Repeated over several weeks"],
        mitigating: ["No prior criminal record", "Working and supporting a household"],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let protectiveOrderV1 = SmallCases.make(
        key: "story.protectiveOrder",
        category: .violent,
        headlines: ["Daycare Lot Struggle Leaves Parent Cut Under Protective Order", "A Pocketknife and Two Stories at the Daycare"],
        law: "awdwisi",
        threshold: 4,
        spec: "Assaulted {V} with a pocketknife, a deadly weapon, inflicting serious injury, while a domestic violence protective order was in effect.",
        ages: 25...44,
        victim: true,
        summary: "{V} held a domestic violence protective order against {D}, the other parent of their six-year-old, that barred contact except for exchanges arranged by a relative. On {DATE}, {DL} came to the child's daycare parking lot unannounced at pickup time with the child's asthma inhaler. There was a struggle at {V}'s car door. {V} was cut across the palm and wrist, needing eleven stitches and nerve repair. A daycare camera recorded part of it. {DL} says {V} grabbed {DL}'s jacket and swung a steering lock, and {DL} opened the knife only to break free.",
        state: [E(.video, 3, "Daycare Camera", "{D} walks up to {V}'s car door, there is a struggle, and {V} steps back holding a bleeding hand."), E(.document, 2, "Medical Records", "An eleven-stitch laceration across the palm and wrist with nerve repair."), E(.document, 2, "Protective Order", "An order barring {D} from going to {V}'s car or home without arrangement.")],
        defense: [E(.statement, 2, "Daycare Worker", "A worker says {V} grabbed {D}'s jacket and swung something metal."), E(.physical, 1, "Steering Lock", "A steering wheel lock was found on the ground beside the car door.", .search)],
        role: "Responding officer",
        exam: [.direct("What did you find when you arrived at the daycare parking lot?", "\"{V} bleeding from the hand and {D} still in the lot. A steering lock lay on the ground next to the car door.\""), .direct("What was the protective order?", "\"An order barring {DL} from going to {V}'s car or home without arrangement. Exchanges of the child were to go through a relative.\""), .direct("What did the daycare camera show?", "\"It shows {DL} walking up to {V}'s car door, a struggle, and {V} stepping back holding a bleeding hand.\""), .direct("What injuries did {V} suffer?", "\"An eleven-stitch laceration across the palm and wrist, with nerve repair. {V} had surgery that same night.\""), .direct("What did {D} tell you?", "\"That {DL} came to bring the child's asthma inhaler, and that {V} grabbed {DL}'s jacket and swung a steering lock.\""), .direct("What did a driver's dashcam record?", "\"It showed {DL} saying, 'You'll regret this,' before walking up. It was a parked driver's dashcam that picked up the audio.\""), .cross("A steering lock was on the ground next to the door, wasn't it?", "\"Yes. It was by the car door. I do not know who held it first.\""), .cross("{D} stayed until you arrived, didn't {D.he}?", "\"Yes. {D.He} did not leave. {D.He} stayed in the lot and cooperated.\""), .cross("A daycare worker says {V} grabbed {D}'s jacket, doesn't the worker?", "\"Yes. The worker said {V} grabbed the jacket and swung something metal.\""), .cross("{D} brought the child's inhaler, didn't {D.he}?", "\"Yes. {D.He} had the inhaler. I understand why {D.he} says that was the reason.\""), .cross("{D} did not intend to cut that deep, did {D.he}?", "\"{D.He} says not. I cannot say what {D.he} intended.\"")],
        defenseRole: "Daycare worker",
        defenseExam: [.direct("What is your job at the daycare?", "\"I am a daycare worker. I help the children at pickup and keep an eye on the parking lot.\""), .direct("What did you see at {V}'s car door?", "\"{V} grabbed {D}'s jacket and swung a metal bar. It was a steering lock. I saw it from the doorway.\""), .direct("How did {D} react?", "\"{D.He} stepped back and put up an arm. Then {D.he} pulled something out. I did not see what until later.\""), .direct("Did you see the knife?", "\"Only after. I saw it in {D.his} hand when {D.he} was backing away. I did not see it open.\""), .direct("What did you do?", "\"I ran to help {V} and called 911. I took the children inside.\""), .direct("How did the defendant behave afterward?", "\"{D.He} looked shocked and dropped the knife. {D.He} stayed in the lot and did not run.\""), .cross("You did not see who struck first, did you?", "\"I saw {V} grab the jacket. I did not see what happened right before.\""), .cross("You did not see the knife open, did you?", "\"No. I saw it afterward. I do not know when it was opened.\""), .cross("{D} was not supposed to be there, was {D.he}?", "\"I know about the order. {D.He} should not have come.\""), .cross("You work with {V} at pickup, don't you?", "\"Yes. I see {V} every day. I have no reason to favor anyone.\""), .cross("You were in the doorway, thirty feet away, weren't you?", "\"About that. I had a view, but not a close one.\"")],
        theory: ("{D} violated a protective order and cut {V} with a pocketknife.", "A parent who was grabbed and struck and opened a knife to break free."),
        allocution: "\"I came to that parking lot with my child's inhaler because I was worried, and I knew I wasn't supposed to be there. When {V} grabbed my jacket and swung the steering lock, I put up my arm and opened the knife only to get free.\"",
        truths: ("A parked driver's dashcam recorded {D} saying, \"You'll regret this,\" before walking up.", "{V} later told a counselor {V.he} had picked up the steering lock first and swung it when {D} stepped close."),
        defendant: [.direct("Why were you at the daycare?", "\"To bring the inhaler. The child has asthma and I was worried. I should have arranged it through the relative.\""), .direct("Why did you open the knife?", "\"{V} had my jacket and swung the steering lock. I opened the knife to break free, not to hurt {V}.\""), .direct("What did {V} do before you opened it?", "\"{V} grabbed my jacket and swung a steering lock at me. I put up an arm and felt the lock hit.\""), .direct("What did you say before you walked up?", "\"I said something harsh. I was angry and upset, and I had no plan to injure anyone.\""), .direct("What did you do after {V} was cut?", "\"I dropped the knife and tried to help. I called out for the daycare staff. I stayed until the officer arrived.\""), .direct("What would you say to {V}?", "\"That I am sorry. I did not mean to cut you that deep, and I wish I had not come.\""), .cross("The order said no contact, didn't it?", "\"Yes. I knew. I went anyway. That was wrong.\""), .cross("You said 'You'll regret this' before you walked up, didn't you?", "\"I said something like that. I was upset. I did not mean it.\""), .cross("You cut {V} across the palm and wrist, didn't you?", "\"Yes. Eleven stitches. I never meant it to be that bad.\""), .cross("You could have left the inhaler with the daycare, couldn't you?", "\"Yes. I should have. I wanted to see my child.\""), .cross("You brought a pocketknife to a child's daycare, didn't you?", "\"I carry one for work. It was in my pocket. I should have left it.\"")],
        openings: ("{V} held a protective order against {D}, who came to the daycare parking lot at pickup. There was a struggle at {V}'s car door, and {V} was cut across the palm and wrist, needing eleven stitches and nerve repair.", "{V} grabbed {D}'s jacket and swung a steering lock. {DL} opened a knife only to break free and never meant to cut that deep."),
        closings: ("The order was clear, and {D} came anyway. A dashcam caught {DL} saying 'You'll regret this' before walking up, and {V} needed eleven stitches and nerve repair.", "A daycare worker saw {V} grab {D}'s jacket and swing a metal bar. {DL} protected {D.himself} and brought an inhaler for a child with asthma."),
        timeline: [(0, "5:05 p.m.: {D} arrives at the daycare lot."), (0, "5:08 p.m.: the struggle at the car door."), (0, "5:15 p.m.: officers arrive.")],
        identified: "The daycare camera; {D} stayed at the scene.",
        notDone: ["Other parents in the lot were not canvassed.", "The steering lock was not tested for blood."],
        aggravating: ["The offense was committed in the presence of a child"],
        mitigating: ["{DL} stayed at the scene until deputies arrived", "{DL} was also injured"],
        mood: .divided,
        impact: "\"I cannot grip a pan or a pen the way I used to. I only want my child and me to be safe.\"",
        doctrines: ["selfDefense", "burdenOfProof"])

    static let rentalFireV1 = SmallCases.make(
        key: "story.rentalFire",
        category: .property,
        headlines: ["Porch Fire Spreads Into Duplex With Family Asleep", "Landlord Charged After Lighter Fluid Bottle Found Under Steps"],
        law: "arson1",
        threshold: 4,
        spec: "Willfully and maliciously burned the dwelling at a duplex on Cedar Row, occupied at the time by {V} and family.",
        ages: 45...66,
        victim: true,
        summary: "{D} owns a duplex and had been trying for three months to remove {V}, who withheld rent over a leaking roof and complained to the housing inspector. At about 3:10 a.m. on {DATE}, fire started on the front porch and spread through the door while {V} and two children slept. A neighbor banged on the door and all three escaped. The fire marshal found a burn pattern on the porch boards and a lighter fluid bottle under the steps. {DL} says {D.he} was visiting a hospitalized sibling that night and the fire started from a faulty space heater on the porch.",
        state: [E(.forensic, 3, "Burn Pattern", "A pour pattern across the porch boards, and lab tests found a petroleum distillate in two samples."), E(.physical, 3, "Lighter Fluid Bottle", "A bottle under the steps with a partial print that matches {D}.", .search), E(.document, 2, "Prior Notices", "Three eviction notices and a heated text, \"You'll be out one way or another.\"")],
        defense: [E(.document, 2, "Hospital Log", "A visitor sign-in shows {D} at the hospital at 11:50 p.m., though not when {D} left."), E(.statement, 2, "Heater Report", "An electrician says the porch space heater had a frayed cord that can arc.")],
        role: "Deputy fire marshal",
        exam: [.direct("What did you find on the porch after the fire?", "\"A pour pattern across the porch boards, and a lighter fluid bottle under the steps. The pattern shows liquid poured and ignited.\""), .direct("What did the lab find?", "\"A petroleum distillate in two samples from the porch boards. That is consistent with lighter fluid.\""), .direct("What did you learn about the family?", "\"{V} and two children were asleep inside when the fire started at about 3:10 a.m. A neighbor banged on the door, and all three escaped.\""), .direct("What had {D} done in the months before the fire?", "\"{D} sent three eviction notices and texted, 'You'll be out one way or another.' {V} had withheld rent over a leaking roof.\""), .direct("What did you find on the bottle?", "\"A partial print. It matched {D.him}. It was not a complete print.\""), .direct("What did the defendant say?", "\"That {D.he} was at the hospital visiting a hospitalized sibling and that the fire began from a faulty space heater on the porch.\""), .cross("A space heater was near the door, wasn't it?", "\"Yes. There was a space heater near the door. An electrician says the cord was frayed.\""), .cross("The print on the bottle is only partial, isn't it?", "\"Yes. It is partial, and {D.he} says {D.he} stocked the porch with supplies.\""), .cross("{D} signed in at the hospital at 11:50 p.m., didn't {D.he}?", "\"Yes. The visitor log shows it. It does not show when {D.he} left.\""), .cross("A heater with a frayed cord can start a fire, can't it?", "\"It can. But a heater does not make a pour pattern on the boards or leave a petroleum distillate.\""), .cross("You cannot say who poured the liquid, can you?", "\"No. I can say where and how. I cannot say who held the bottle.\"")],
        defenseRole: "Electrician",
        defenseExam: [.direct("What is your work?", "\"I am an electrician. I inspect wiring and appliances and repair electrical faults. I examined the porch heater after the fire.\""), .direct("What was wrong with the heater?", "\"A frayed cord. It had a worn spot that can arc and spark. It is a known cause of fires.\""), .direct("Where was the heater on the porch?", "\"Near the door, close to the boards. A spark there could ignite nearby material.\""), .direct("Could the heater have started the fire?", "\"It could have started a fire, yes. It is a real possibility, given the frayed cord.\""), .direct("What did the cord look like?", "\"Cracked insulation and bare wire at one spot. It was in poor shape and should have been replaced.\""), .direct("What would you recommend?", "\"That an investigator treat the heater as a possible cause. I cannot say it was the cause.\""), .cross("Can a heater make a pour pattern on boards?", "\"No. A heater does not pour liquid. That pattern would have to come from something else.\""), .cross("You cannot say the heater started this fire, can you?", "\"No. I can say it was a hazard. I cannot say it caused this fire.\""), .cross("You did not see the fire, did you?", "\"No. I examined the heater afterward. I only know what I found.\""), .cross("Heater cords usually leave burn marks near the cord, don't they?", "\"Yes. The burn marks I saw were around the cord. I did not see a pour pattern.\""), .cross("You were hired by the defense, weren't you?", "\"Yes. I am paid for my time. I am telling you what I found.\"")],
        theory: ("{D} poured accelerant on a porch and set a fire while a family slept.", "A frayed cord on a heater and a landlord at a hospital."),
        allocution: "\"I was at the hospital with my sibling that night, and I would never put anyone's life at risk in a fire. I stocked that porch with supplies, including lighter fluid for the grill. I'm sorry for what that family lost. I never meant for anyone to be hurt.\"",
        truths: ("{DL}'s phone location showed {D.him} leaving the hospital at 1:30 a.m. and driving past the duplex.", "A hardware store's footage showed another man buying the same lighter fluid brand the day before."),
        defendant: [.direct("Did you set the fire?", "\"No. I did not. I was at the hospital that night. I would never put people in danger, and certainly not children.\""), .direct("When did you leave the hospital?", "\"Around midnight. I went home, and then I drove past the duplex on my way. I did not stop.\""), .direct("Why is your print on the bottle?", "\"I stocked that porch with supplies, including lighter fluid for a grill. I handled that bottle weeks before the fire.\""), .direct("Why did you want {V} out?", "\"{V} stopped paying rent over a leak. I tried to evict through the court. I sent notices and a text. I was angry.\""), .direct("What did you mean by 'You'll be out one way or another'?", "\"That I would get {V} out through the court. I did not mean anything violent. I should have written it differently.\""), .direct("How do you feel about what happened?", "\"Horrified. A family could have died. I helped the family find a new place after the fire.\""), .cross("Your phone showed you leaving the hospital at 1:30 a.m., didn't it?", "\"Yes. I drove past the duplex on my way home. I did not stop.\""), .cross("You wanted {V} out of the duplex, didn't you?", "\"Yes. Through the court, not like this.\""), .cross("You sent three eviction notices and a heated text, didn't you?", "\"Yes. I know how it looks. I was frustrated.\""), .cross("Your print was on the bottle, wasn't it?", "\"A partial print. I stocked that porch. It was my bottle.\""), .cross("You knew a family slept inside, didn't you?", "\"Yes. And I would never have hurt them.\"")],
        openings: ("At about 3:10 a.m., fire started on the porch of a duplex while {V} and two children slept. The marshal found a pour pattern and a lighter fluid bottle, and {D} had sent three eviction notices.", "{D} was at a hospital that night, and a space heater on the porch had a frayed cord. A partial print and a bad heater are no proof of arson."),
        closings: ("A pour pattern on the boards, a petroleum distillate in the samples, a bottle under the steps with {D}'s print, and a text that said {V} would be out one way or another.", "The print is partial and {D} stocked that porch. A frayed heater cord is a real cause, and another person was seen buying the same fluid."),
        timeline: [(-90, "{DL} sends the first eviction notice."), (0, "3:10 a.m.: fire on the front porch."), (0, "3:30 a.m.: the family is outside."), (1, "The fire marshal collects samples.")],
        identified: "A burn pattern and a partial print.",
        notDone: ["Cell-site records for {DL}'s phone were never requested.", "The hospital's exit camera was not checked."],
        aggravating: ["The dwelling was occupied by children at the time of the fire"],
        mitigating: ["No prior criminal record"],
        mood: .wantsConviction,
        impact: "\"We lost everything we owned. I woke up to smoke coming through the door with my kids asleep, and a neighbor's banging saved us. My kids still ask if the porch will catch fire. We were living in that duplex while I fought to get the roof repaired.\"",
        doctrines: ["burdenOfProof"])

    static let fishingCabinV1 = SmallCases.make(
        key: "story.fishingCabin",
        category: .violent,
        headlines: ["Business Partner Shot Dead in Duck Blind at Dawn", "Accident or Murder in the Marsh?"],
        law: "murder1",
        threshold: 5,
        spec: "Killed {V} with a shotgun, with malice, premeditation, and deliberation.",
        ages: 38...60,
        victim: true,
        summary: "{D} and {V} owned a farm supply store together for nine years. Before dawn on {DATE}, the two climbed into a duck blind on a coastal marsh. At 6:05 a.m., {D.he} called 911 and said {V}'s shotgun had gone off as {V.he} climbed in, and {V} was dead. The medical examiner says the shot was fired from three to four feet away, level with the chest. Two weeks earlier, {V} had told an accountant {V.he} wanted to buy {DL} out, and a $600,000 buy-sell policy would pay {DL} if {V} died. {DL} says it was a terrible accident.",
        state: [E(.forensic, 3, "Medical Examiner", "A single shotgun wound to the chest from about three to four feet, fired level, not from below."), E(.document, 3, "Buy-Sell Policy", "A $600,000 buy-sell policy naming {D}, increased from $200,000 five weeks before the trip."), E(.statement, 3, "Accountant", "The accountant says {V} planned to force {D} out of the store within the month.")],
        defense: [E(.physical, 2, "Shotgun Test", "A range test showed {V}'s shotgun can fire on a hard bump with the safety off."), E(.statement, 1, "Immediate Call", "{D} called 911 within two minutes and stayed beside {V}.")],
        role: "Lead investigator",
        exam: [.direct("What did the medical examiner find about {V}'s wound?", "\"A single shotgun wound to the chest from about three to four feet, fired level and not from below. That distance and angle matter in this case.\""), .direct("What did {D} tell you happened in the blind?", "\"That {V}'s shotgun went off as {V} climbed in. {D} called 911 at 6:05 a.m. and said it was a terrible accident.\""), .direct("What did you learn about the business?", "\"{DL} and {V} owned a farm supply store together for nine years. Two weeks before the trip, {V} told an accountant {V} wanted to buy {DL} out.\""), .direct("What did the insurance policy show?", "\"A $600,000 buy-sell policy naming {DL}, increased from $200,000 five weeks before the trip. It would pay {DL} if {V} died.\""), .direct("What did you find on the defendant's second phone?", "\"A search from the night before the trip that read 'hunting accident what happens legally.'\""), .direct("What did the range test show about the shotgun?", "\"That it can fire on a hard bump with the safety off. On the test range it fired once that way.\""), .cross("{D} called 911 within two minutes, didn't {D.he}?", "\"Yes. {DL} called quickly and stayed beside {V}. I would not call {DL}'s behavior cold.\""), .cross("The gun can fire on a bump, can't it?", "\"On the test range it did, once, with the safety off and a hard bump. I cannot say it did so here.\""), .cross("The blind was a tight, cramped space, wasn't it?", "\"Yes. It was small, and two people were climbing in. A gun could be bumped in that space.\""), .cross("The shotgun was worn, wasn't it?", "\"It was old and had been repaired. A gunsmith examined it afterward.\""), .cross("You did not see the shot, did you?", "\"No. No one did. I rely on the physical evidence and what {D.he} told me.\"")],
        defenseRole: "Retired gunsmith",
        defenseExam: [.direct("What is your work?", "\"I am a retired gunsmith. I repaired and tested firearms for over thirty years, and I examined the shotgun in this case.\""), .direct("Could this gun fire if bumped?", "\"With the safety off, yes. The trigger sear was worn and could release with a hard bump.\""), .direct("How does a worn sear cause a discharge?", "\"The sear holds the hammer back. When it wears, a jolt can slip it and let the hammer fall. It is a known defect in old guns.\""), .direct("Does that explain a level shot?", "\"If the muzzle was up and level when the gun was bumped, yes. In a cramped blind that is possible.\""), .direct("What did your range test show?", "\"The gun fired by itself again a year later when the safety was off and the muzzle bumped a blind frame.\""), .direct("What do you recommend for guns like this?", "\"Retire them or replace the sear. A gun like that should not be carried loaded in a blind.\""), .cross("The safety would have to have been off, wouldn't it?", "\"Yes. With the safety on, I do not think it would fire. I cannot say whether it was off.\""), .cross("You were hired for the defense, weren't you?", "\"Yes. I am compensated for my time, not for my opinion.\""), .cross("A gun can also be fired on purpose, can't it?", "\"Of course. My testing only shows that this gun can fire from a bump.\""), .cross("You did not see what happened in the blind, did you?", "\"No. I only examined the gun. I cannot say how it was handled.\""), .cross("A bump does not guarantee a discharge, does it?", "\"No. It took a hard bump and the right conditions. It did not fire every time.\"")],
        theory: ("{D} shot a business partner at close range to collect a policy and keep the store.", "A worn gun that went off in a cramped blind and a partner who called for help at once."),
        allocution: "\"{V} was my business partner of nine years, and I loved {V} like a brother. When that gun went off, I tried to stop the bleeding with my jacket. I called 911 right away. I'm sorry beyond words for what happened in that duck blind, and I'm sorry to {V}'s family.\"",
        truths: ("{DL}'s second phone held a search the night before the trip: \"hunting accident what happens legally.\"", "The same shotgun fired by itself again on a range test a year later when the safety was off and the muzzle bumped a blind frame."),
        defendant: [.direct("What happened in the blind?", "\"{V} was climbing in with the gun and it went off. I heard the blast and turned, and {V} was down.\""), .direct("What did you do?", "\"I called 911 and tried to stop the bleeding. I pressed my jacket on the wound and stayed until help came.\""), .direct("Why was the policy increased?", "\"The accountant suggested it. We were reviewing the business, and the accountant said the coverage was too low for what we owned.\""), .direct("Why did you search 'hunting accident what happens legally' the night before?", "\"I was thinking about safety. We hunt in tight blinds, and I had read about accidents. I was curious about the rules.\""), .direct("What was your relationship with {V}?", "\"Business partners for nine years, and friends. We argued about the store, but I never wanted {V} dead.\""), .direct("How do you feel about {V}'s death?", "\"Devastated. I lost a partner and a friend. I replay that morning every night.\""), .cross("{V} had told an accountant {V} planned to force you out, hadn't {V}?", "\"I learned that after the accident. It stung. I did not know before.\""), .cross("You stood to collect $600,000 if {V} died, didn't you?", "\"Yes. The policy named me. I did not think about it that morning.\""), .cross("The examiner says the shot was fired level from three to four feet, doesn't the examiner?", "\"The report says so. I cannot tell how the gun was pointed. It all happened fast.\""), .cross("You searched for the legal side of a hunting accident the night before, didn't you?", "\"Yes. I know how that looks. I was not planning anything.\""), .cross("You kept a second phone, didn't you?", "\"Yes. It was for business. I used it for searches too.\"")],
        openings: ("{D} and {V} owned a farm supply store together. In a duck blind at dawn, {V} was killed by a shotgun blast from three to four feet away, and a $600,000 policy would pay {DL}.", "{D} called 911 within two minutes after {V}'s old shotgun went off as {V} climbed into a cramped duck blind. It was a terrible accident, and {DL} lost a friend."),
        closings: ("A level shot at close range, a policy that was raised five weeks earlier, a partner about to force {D} out, and a late-night search about hunting accidents.", "The same shotgun fired by itself again on a range test, and {D} called for help at once. A gun that fires on a bump is not a murder weapon."),
        timeline: [(-35, "The buy-sell policy is increased."), (-14, "{V} tells the accountant about the buyout."), (0, "6:00 a.m.: the shot in the blind."), (0, "6:05 a.m.: {D} calls 911.")],
        identified: "{D} called 911 and reported the shooting.",
        notDone: ["The blind was not measured to reconstruct where each partner sat.", "The store's books were not audited for a shortfall."],
        aggravating: ["The offense was committed for pecuniary gain"],
        mitigating: ["{DL} called 911 immediately and stayed with {V}", "No prior criminal record"],
        mood: .divided,
        impact: "\"I grew up calling {D} my uncle, and I spent summers at that farm supply store as a boy. My father went out before dawn that day and never came home. I just want the truth about what happened in that blind. My mother and I deserve to hear it.\"",
        doctrines: ["burdenOfProof", "lesserIncluded"],
        genders: ["D": .male])

    static let duplexBurglaryV1 = SmallCases.make(
        key: "story.duplexBurglary",
        category: .property,
        headlines: ["Balcony Door Forced at 3 a.m.; Game Console Listing Leads to Arrest", "Fingerprint on Sliding Glass Ties Former Maintenance Worker to Break-In"],
        law: "burglary1",
        threshold: 7,
        spec: "Broke and entered the occupied dwelling of {V} at night with intent to commit larceny.",
        ages: 24...36,
        victim: true,
        summary: "At about 3:30 a.m. on {DATE}, {V} woke to a scrape and saw a silhouette crossing the living room of a second-floor apartment. The balcony door had been forced. The intruder left with a game console, a purse, and a set of car keys. A print lifted from the sliding glass matched {D}, who had done maintenance work in the building six months earlier. Four days later a resale app listing offered a console with a serial number matching {V}'s. {DL} says {D.he} touched the glass during an old repair and sold the console after buying it from a coworker.",
        state: [E(.forensic, 3, "Latent Print", "A print on the outside of the sliding glass door matches {D}.", .search), E(.digital, 3, "Resale Listing", "A listing from {D}'s account offering a console with the serial number from {V}'s purchase record."), E(.statement, 2, "Silhouette", "{V} saw a person of medium build in a dark cap, face not visible.")],
        defense: [E(.document, 2, "Work Order", "A work order shows {D} replaced the balcony door's lock six months before."), E(.statement, 2, "Partner Alibi", "{DL}'s partner says {D.he} was asleep beside {D.him} all night.")],
        role: "Property crimes detective",
        exam: [.direct("What did the lab find on the sliding glass door?", "\"A fingerprint that matches {D}. It was lifted from the outside of the glass near the handle.\""), .direct("What happened at {V}'s apartment on {DATE}?", "\"At about 3:30 a.m., {V} woke to a scrape and saw a silhouette crossing the living room. The balcony door had been forced.\""), .direct("What was taken?", "\"A game console, a purse, and a set of car keys. The intruder left through the balcony.\""), .direct("How did you find the console?", "\"A resale listing four days later offered a console with a serial number matching {V}'s purchase record. It was posted from {DL}'s account.\""), .direct("What is {D}'s connection to the building?", "\"{DL} did maintenance work there six months earlier. A work order shows {DL} replaced the balcony door's lock.\""), .direct("What did {V} see?", "\"A person of medium build in a dark cap. {V} did not see a face. It was dark, and it happened quickly.\""), .cross("{D} worked in the building six months earlier, didn't {D.he}?", "\"Yes. {D.He} replaced the balcony door's lock. A print could date from that visit.\""), .cross("You cannot say when the print was left, can you?", "\"No. A print does not carry a date. It might have been left six months earlier.\""), .cross("The silhouette did not show a face, did it?", "\"No. {V} saw a medium build in a dark cap. It could be many people.\""), .cross("{D}'s partner says {D} was asleep all night, doesn't the partner?", "\"Yes. I know about that statement. I considered it.\""), .cross("A coworker was later arrested with other consoles, wasn't a coworker?", "\"Yes. Someone was arrested in another county with three consoles from break-ins and confessed to this one.\"")],
        defenseRole: "Defendant's partner",
        defenseExam: [.direct("How are you related to {D}?", "\"I am {D}'s partner. We live together, and I was home that night.\""), .direct("Where was the defendant that night?", "\"In bed beside me. {D.He} was asleep all night. I would have noticed if {D.he} had left.\""), .direct("Did you sleep through the night?", "\"Mostly. I woke once around three and {D.he} was still there. I went back to sleep.\""), .direct("How did the defendant get the console?", "\"From a coworker. {D.He} told me about the deal. It was a cheap price, and I thought it was fine.\""), .direct("What kind of person is the defendant?", "\"Honest. {D.He} works hard and has never been in trouble. I was shocked when the deputies came.\""), .direct("What did the defendant say about the print?", "\"That it was from the repair. {D.He} explained it the same way each time.\""), .cross("You were asleep for part of the night, weren't you?", "\"Yes. I cannot say what happened while I slept.\""), .cross("You do not know where the defendant was at 3:30, do you?", "\"I believe {D.he} was beside me. I cannot swear to it.\""), .cross("You are the defendant's partner, aren't you?", "\"Yes. I want to help, and I am describing what I know.\""), .cross("You did not see the console, did you?", "\"No. I never saw it. I only heard about it.\""), .cross("You do not know the coworker, do you?", "\"I have met the coworker once. I do not know the coworker well.\"")],
        theory: ("{D} knew the building, forced the door, and sold the console days later.", "An old fingerprint and a console bought from a coworker."),
        allocution: "\"I was asleep in my own bed beside my partner all night, and I never went near that apartment. I bought that game console from a coworker for ninety dollars, and the coworker said it was a spare. I should not have bought it without asking more.\"",
        truths: ("A year later the purse turned up in a storage unit rented in {DL}'s name.", "The coworker was arrested in another county with three more consoles from break-ins and confessed to {V}'s."),
        defendant: [.direct("Were you in {V}'s apartment?", "\"No. I was not. I was asleep in my own bed beside my partner all night.\""), .direct("How did you get the console?", "\"From a coworker for $90. The coworker said it was a spare, and I thought it was a good deal.\""), .direct("Why is your print on the glass?", "\"I worked on that door six months earlier. I touched the glass during the repair. It is an old print.\""), .direct("Why did you list the serial number?", "\"Nothing about it looked stolen to me. I took photos of the console and posted it. The serial was in the photo.\""), .direct("What did you do when you learned the console was stolen?", "\"I told the detective who sold it to me and gave the coworker's name. I wanted to help.\""), .direct("What would you say to {V}?", "\"That I am sorry for what happened. I did not break in, and I hope you get your property back.\""), .cross("You listed the console four days after the break-in, didn't you?", "\"Yes. I know how it looks, but nobody had told me it was stolen.\""), .cross("You knew the building, didn't you?", "\"Yes. I worked there. That is why I knew how the door worked, and why I would not have used it.\""), .cross("Your print was on the glass, wasn't it?", "\"Yes. From the repair. I cannot explain how it stayed that long.\""), .cross("The purse turned up in a storage unit rented in your name a year later, didn't it?", "\"I cannot account for that unit. I did not rent it for that purpose.\""), .cross("You paid only $90 for a console, didn't you?", "\"Yes. It was cheap. I should have asked why.\"")],
        openings: ("At 3:30 a.m., {V} woke to a scrape and saw a silhouette in the living room. The balcony door had been forced, a print on the glass matched {D}, and a console with {V}'s serial number was listed by {DL}.", "{D} touched the glass during a repair six months earlier and bought the console from a coworker. A print can be old."),
        closings: ("A forced balcony door, {D}'s print on the glass, and {V}'s console listed by {DL} four days later. {DL} knew the building and its lock.", "A print can be six months old, and the coworker was later arrested with three more consoles and confessed to this one. {D} did not break in."),
        timeline: [(-180, "{DL} replaces the balcony door's lock."), (0, "3:30 a.m.: the intruder crosses the apartment."), (4, "The console is listed for sale."), (6, "A latent print is matched.")],
        identified: "A fingerprint and a resale listing.",
        notDone: ["The coworker was never interviewed.", "No search was made of {DL}'s apartment for the purse or the keys."],
        aggravating: ["The victim was confronted face to face and has suffered lasting fear"],
        mitigating: ["{DL} listed the console openly under {D.his} own name", "No prior burglary convictions"],
        mood: .indifferent,
        impact: "\"I moved out after that night. I woke to a scrape and saw a shape crossing my living room, and I couldn't stand to look at that balcony door afterward. I lost sleep for weeks, and I flinched at every sound. I just want to feel safe in my home again.\"",
        doctrines: ["burdenOfProof", "lesserIncluded"])

    static let parkingLotShootingV1 = SmallCases.make(
        key: "story.parkingLotShooting",
        category: .violent,
        headlines: ["Driver Shot After Fender-Bender in Grocery Lot", "Hand in the Window: Concealed Carry Holder Fires Twice"],
        law: "awdwikisi",
        threshold: 4,
        spec: "Assaulted {V} with a handgun, with intent to kill, inflicting serious injury.",
        ages: 23...48,
        victim: true,
        summary: "On {DATE} at dusk, a small fender-bender happened in a grocery store parking lot. {V}, the other driver, walked up to {D}'s car, shouted, and reached through the open driver's window. {DL}, who has a concealed carry permit, fired twice, hitting {V} in the chest and arm. {V} survived after surgery. {DL} says {V} grabbed for the keys and the steering wheel and {DL} feared being dragged out. {V} says {V.he} only reached to point at the dent.",
        state: [E(.video, 3, "Lot Camera", "{V} stands at the open window with {V.his} hand inside for about three seconds before the shots."), E(.document, 2, "Hospital Records", "Gunshot wounds to the chest and the upper arm; two weeks in the hospital.")],
        defense: [E(.statement, 2, "Bystander", "A shopper says {V} was yelling and had {V.his} arm inside the car."), E(.physical, 1, "Key Fob", "{D}'s key fob was found on the pavement beside the car door.", .search)],
        role: "Lead detective",
        exam: [.direct("What does the lot camera show?", "\"{V} at the open driver's window of {D}'s car with a hand inside for about three seconds before two shots. {V} then falls back.\""), .direct("What happened before the shots?", "\"A small fender-bender in the grocery store lot. {V}, the other driver, walked up to {DL}'s car, shouted, and reached through the open window.\""), .direct("What were {V}'s injuries?", "\"Gunshot wounds to the chest and the upper arm. {V} survived after surgery and spent two weeks in the hospital.\""), .direct("Was {V} armed?", "\"No. We searched {V} and the car and found no weapon. {V} had a phone and car keys.\""), .direct("What did {D} tell you?", "\"That {V} grabbed for the keys and the steering wheel, and that {DL} feared being dragged out of the car.\""), .direct("What did the defendant's dashcam show?", "\"{V}'s hand resting on the window frame and not reaching inside. {DL} had said the dashcam was not recording.\""), .cross("{V}'s arm was inside the car, wasn't it?", "\"It appears so in the lot camera. The picture is small, and the window frame blocks part of it.\""), .cross("A second shopper's video shows {V} grabbing the wheel, doesn't it?", "\"I have seen it. It shows {V} grabbing the steering wheel and {DL}'s collar before the shots.\""), .cross("{D} has a concealed carry permit, doesn't {D.he}?", "\"Yes. {D.He} had a valid permit. {D.He} called 911 right away.\""), .cross("The key fob was on the ground beside the door, wasn't it?", "\"Yes. It was next to the car door. It was found beside the door, and I cannot explain it.\""), .cross("{V} was yelling and angry, wasn't {V}?", "\"Yes. A bystander says so. {V} was shouting at {DL} through the window.\"")],
        defenseRole: "Shopper in the lot",
        defenseExam: [.direct("Why were you in the grocery lot?", "\"I was a shopper walking to my car. I saw the whole exchange from about thirty feet away.\""), .direct("What did you see?", "\"{V} shouting with an arm in the window. {V} was loud and angry and leaning in.\""), .direct("Did you see a grab?", "\"I saw the arm move toward the dash. I could not tell if {V} touched anything.\""), .direct("What did you hear?", "\"Shouting, then two shots. I dropped behind a car and then called 911.\""), .direct("How did {D} look?", "\"Scared. {D} was holding the wheel and leaning away. It all happened in seconds.\""), .direct("What did you do after?", "\"I stayed behind a car until it was clear. I gave my name to the deputies and told them what I saw.\""), .cross("You did not see a weapon, did you?", "\"No. I did not. I only saw an arm in the window.\""), .cross("You did not see {V} grab the steering wheel, did you?", "\"No. I saw the arm move. I cannot say what it touched.\""), .cross("You were thirty feet away, weren't you?", "\"About that. I could see them, but not every detail.\""), .cross("You do not know the defendant, do you?", "\"No. I never saw {D.him} before that day.\""), .cross("Where were you in relation to the car?", "\"At the passenger side, about six feet back. The window was open.\"")],
        theory: ("{D} shot an unarmed driver who reached to point at a dent.", "A driver who reached into a car and was shot to stop a grab."),
        allocution: "\"{V} had an arm in my car and grabbed at the keys and the wheel, and I was boxed in with a car in front and one behind. I thought I was about to be pulled out. I called for help as soon as I fired. I'm sorry for what I did, and for {V}'s injuries.\"",
        truths: ("{DL}'s dashcam, which {D.he} said was not recording, showed {V}'s hand resting on the window frame and not reaching inside.", "A second shopper's phone video later showed {V} grabbing the steering wheel and {D}'s collar before the shots."),
        defendant: [.direct("Why did you fire?", "\"{V} had an arm in my car and grabbed at the keys and the wheel. I feared being dragged out, and I was afraid for my life.\""), .direct("Did you call 911?", "\"Right away. I called as soon as I fired, and I stayed with {V} until help came.\""), .direct("Could you have driven away?", "\"I was boxed in. A car was in front of me and another behind. I could not move.\""), .direct("What did {V} do before the fender-bender argument got worse?", "\"{V} walked up shouting and pointing at the dent. Then {V} reached in. I felt a hand on my collar.\""), .direct("Why did you say the dashcam was not recording?", "\"I did not think it was. I was surprised when it was. I did not try to hide anything.\""), .direct("What would you say to {V}?", "\"That I am sorry you were hurt. I did not know you were unarmed, and I would give anything to take it back.\""), .cross("{V} had no weapon, did {V}?", "\"No. I did not know that. I only knew a person had an arm in my car.\""), .cross("Your own dashcam shows {V}'s hand resting on the window frame, doesn't it?", "\"I have heard that. It may show that. I felt a grab.\""), .cross("You fired twice at a person over a dent, didn't you?", "\"I fired twice at a person grabbing my wheel. I know how it looks.\""), .cross("You could have stayed in the car and called 911, couldn't you?", "\"I could have. I felt I had no time.\""), .cross("You said the dashcam was not recording, didn't you?", "\"Yes. I thought it was off. I was wrong about that.\"")],
        openings: ("After a fender-bender in a grocery store lot, {V} walked up to {D}'s car, shouted, and reached through the open window. {DL}, who has a concealed carry permit, fired twice, hitting {V} in the chest and arm.", "{V} grabbed for the keys and the steering wheel, and {D} feared being dragged out of {D.his} own car. {DL} was boxed in and had seconds."),
        closings: ("An unarmed driver was shot over a dent. The lot camera shows a hand in the window for three seconds, and {D}'s own dashcam shows a hand resting on the frame.", "A shopper's video shows {V} grabbing the steering wheel and {D}'s collar before the shots. A reasonable person fears a grab inside {D.his} own car."),
        timeline: [(0, "Dusk: the fender-bender."), (0, "{V} walks to the open window."), (0, "Two shots; {D} calls 911."), (0, "{V} goes to surgery.")],
        identified: "{D} called 911 and stayed.",
        notDone: ["{DL}'s car was not checked for a working dashcam.", "Other shoppers in the lot were not canvassed."],
        aggravating: ["{DL} fired twice at close range"],
        mitigating: ["{DL} called 911 immediately and remained at the scene", "{V} was the initial aggressor in confronting {DL}", "No prior criminal record"],
        mood: .divided,
        impact: "\"I should not have reached in, and I have said so from day one. I did not deserve to be shot.\"",
        doctrines: ["selfDefense", "imperfectSelfDefense", "burdenOfProof"])

    static let kitchenStrangulationV1 = SmallCases.make(
        key: "story.kitchenStrangulation",
        category: .violent,
        headlines: ["Woman Runs Into Gas Station Holding Her Neck After Car Argument", "Clerk's 911 Call Leads to Strangulation Charge"],
        law: "strangulation",
        threshold: 5,
        spec: "Assaulted {V} and inflicted physical injury by strangulation.",
        ages: 26...45,
        victim: true,
        summary: "At about 12:20 a.m. on {DATE}, {V} ran into a gas station holding {V.his} neck and asked the clerk to call 911, saying {D} had choked {V.him} in the car outside. The station camera shows {DL}'s car at the pump and {DL} getting out. Deputies found red marks on {V}'s neck and a cracked phone on the floor. {DL} had fresh scratches on the forearm. {DL} says {V} had been drinking, hit {D.him} first, and {D.he} only held {V.his} arms. By trial, {V} says {V.he} cannot remember who started it.",
        state: [E(.video, 3, "Station Camera", "{V} bursts through the door holding {V.his} neck; moments later {D} gets out of a car at the pump."), E(.forensic, 3, "Nurse Exam", "Petechiae in both eyes and finger-shaped bruising on the neck."), E(.statement, 2, "Clerk", "The clerk says {V} could barely speak and kept saying, \"He choked me.\"")],
        defense: [E(.statement, 2, "Recantation", "{V} now says {V.he} swung first and the marks came from a scarf pulled tight."), E(.document, 1, "Scratch Photos", "Photos of fresh scratches on {D}'s forearm and cheek.")],
        role: "Gas station clerk",
        exam: [.direct("What is your job at the gas station?", "\"I am the clerk on the overnight shift. I work the register, watch the pumps through the window, and call for help if there is trouble.\""), .direct("What happened at about 12:20 a.m. on {DATE}?", "\"{V} burst through the door holding {V.his} neck and could barely speak. {V} asked me to call 911 and said {D} had choked {V.him} in the car outside.\""), .direct("What did {V} say?", "\"That {DL} had choked {V.him}, over and over. {V}'s voice was hoarse and {V} kept touching {V.his} throat.\""), .direct("What did you do?", "\"I locked the door and called 911. I stayed on the line with the dispatcher and kept my eyes on the lot.\""), .direct("What did you see on the camera after {V} came in?", "\"Moments later, {DL} gets out of a car at the pump and walks toward the door. {DL} did not come in.\""), .direct("How did {V} look?", "\"Red marks on the neck, shaking, and crying. {V} was frightened and kept looking over {V.his} shoulder.\""), .cross("You did not see the car until after {V} was inside, did you?", "\"No. I saw {V} come in first. The camera shows the car afterward.\""), .cross("You smelled alcohol on {V}, didn't you?", "\"Yes. I could smell it. I did not know how much {V} had had.\""), .cross("You did not see anyone's hands on anyone's neck, did you?", "\"No. I was inside the whole time. I only saw {V} and what {V} said.\""), .cross("{V} later said something different, didn't {V}?", "\"I have heard that. I cannot speak to what {V} says now. I only know what {V} said that night.\""), .cross("{D} stayed at the pump and did not run, didn't {D.he}?", "\"Yes. {D.He} stayed there until deputies came. {D.He} did not try to leave.\"")],
        defenseRole: "Friend of the couple",
        defenseExam: [.direct("How do you know {D} and {V}?", "\"I am a friend of the couple. I have known them both for years, and I was at the bar with them that night.\""), .direct("What was {V} like that night?", "\"Drunk and angry. {V} threw a punch at the bar. I stepped in and calmed {V} down.\""), .direct("How did the defendant handle {V}'s anger?", "\"Patiently. {D} tried to get {V} to leave. {DF} did not raise a hand.\""), .direct("Have you seen {V} hit the defendant before?", "\"Once, at a party. {DF} did not hit back then. {DF} just left.\""), .direct("What kind of person is the defendant?", "\"Calm. {D.He} does not fight. I was shocked to hear what {V} said.\""), .direct("What did {V} say about the night afterward?", "\"That {V} did not remember who started it. Later, {V} said {V} swung first.\""), .cross("You were not in the car, were you?", "\"No. I was at the bar. I left before they did.\""), .cross("You do not know what happened in the car, do you?", "\"No. I only know about the bar. I cannot say what happened later.\""), .cross("You are friends with both, aren't you?", "\"Yes. I care about both of them. I am telling you only what I know.\""), .cross("You did not see the marks on {V}'s neck, did you?", "\"I saw them the next day. They looked bad. I do not know how they happened.\""), .cross("{V} was afraid of the defendant that night, wasn't {V}?", "\"{V} was upset. I do not know whether {V} was afraid.\"")],
        theory: ("{D} choked {V} in a parked car and {V} ran for help.", "A drunken scuffle, a scarf, and a recanting {V}."),
        allocution: "\"I never choked {V}. {V} hit me first and I held {V}'s arms to stop it, and {V} scratched my arm and cheek in the fight. I'm sorry for that night and for how it ended with {V} in a gas station asking for help. I'm getting help.\"",
        truths: ("{DL} later told a cellmate that {D.he} had {V} pinned against the seat when {V} stopped fighting.", "Months later, {V} told a counselor {V.he} had swung first and remembered it only when sober."),
        defendant: [.direct("Did you touch {V}'s neck?", "\"No. I held {V}'s arms. {V} hit me first, and I was trying to stop {V} from hitting me again.\""), .direct("Who started it?", "\"{V} did. {V} had been drinking and was angry. {V} swung at me in the car, and I caught {V}'s arms.\""), .direct("How did you get the scratches?", "\"{V} scratched my forearm and cheek during the fight. The photos show them. I did not hit back.\""), .direct("What about the scarf?", "\"It was around {V}'s neck already. {V} was wearing it, and it may have been pulled tight in the struggle.\""), .direct("Why did you stop at the gas station?", "\"We needed gas. {V} ran in when I got out of the car. I did not know what {V} would say.\""), .direct("What would you say to {V}?", "\"That I am sorry you were hurt. I never meant to hurt you, and I wish we had not fought.\""), .cross("Petechiae were found in both of {V}'s eyes, weren't they?", "\"I cannot explain it. I did not touch {V}'s neck.\""), .cross("The nurse found finger-shaped bruising on the neck, didn't the nurse?", "\"So the nurse reported. I cannot explain how it happened.\""), .cross("You had {V} pinned against the seat, didn't you?", "\"I held {V}'s arms. I may have leaned in. {V} stopped fighting, and I let go.\""), .cross("You told a cellmate you had {V} pinned when {V} stopped fighting, didn't you?", "\"I said something like that. I was telling it badly.\""), .cross("You had been drinking too, hadn't you?", "\"A little. I was not drunk. I was driving.\"")],
        openings: ("At 12:20 a.m., {V} ran into a gas station holding {V.his} neck and said {D} had choked {V.him} in the car outside. A nurse found petechiae in both eyes and finger-shaped bruising on the neck.", "{V} was drunk and hit {D} first, and {DL} only held {V}'s arms. By trial, {V} says {V.he} swung first and the marks came from a scarf."),
        closings: ("The camera and the nurse tell the story: {V} bursting in, hoarse and marked, and petechiae in both eyes. {D} told a cellmate {D.he} had {V} pinned.", "{V} now says {V.he} started it and cannot remember. A scarf, a drunken scuffle, and a scratch on {D}'s cheek tell a different story."),
        timeline: [(0, "12:05 a.m.: the argument in the parked car."), (0, "12:20 a.m.: {V} runs into the station."), (0, "12:35 a.m.: deputies arrive.")],
        identified: "The station camera and the clerk's 911 call.",
        notDone: ["The scarf was not tested.", "{DL}'s injuries were photographed at the jail but not examined by a medical professional."],
        aggravating: ["The offense was committed against a person in a domestic relationship"],
